import bcrypt from 'bcryptjs'
import { NextRequest, NextResponse } from 'next/server'

import { prisma } from '@/lib/prisma'
import { logger } from '@/lib/utils/logger'

/**
 * Endpoint para ejecutar el seed de la base de datos
 * 
 * SEGURIDAD:
 * - Solo se puede ejecutar si el usuario admin NO existe (primera vez)
 * - Requiere un token secreto en el header o query param (SEED_SECRET)
 * - Solo funciona en producción o con el token correcto
 */
export async function POST(request: NextRequest) {
  try {
    // Verificar token secreto (opcional pero recomendado)
    const authHeader = request.headers.get('authorization')
    const seedSecret = request.nextUrl.searchParams.get('secret')
    const providedSecret = authHeader?.replace('Bearer ', '') || seedSecret
    
    // En producción, requerir token secreto (configurar SEED_SECRET en Vercel)
    const expectedSecret = process.env.SEED_SECRET
    if (process.env.NODE_ENV === 'production' && expectedSecret) {
      if (!providedSecret || providedSecret !== expectedSecret) {
        logger.security('Intento de ejecutar seed sin autorización', {
          ip: request.headers.get('x-forwarded-for') || 'unknown',
        })
        return NextResponse.json(
          { error: 'No autorizado. Se requiere token secreto.' },
          { status: 401 }
        )
      }
    }

    // Verificar si el usuario admin ya existe
    const existingUser = await prisma.profile.findUnique({
      where: { email: 'jhonatanancasi@gmail.com' }
    })

    if (existingUser) {
      return NextResponse.json(
        { 
          message: 'El seed ya fue ejecutado. El usuario admin ya existe.',
          userExists: true,
          userId: existingUser.id
        },
        { status: 200 }
      )
    }

    // Ejecutar el seed
    logger.info('Iniciando seed de la base de datos...')
    
    const password = '10571705'
    const hashedPassword = await bcrypt.hash(password, 12)

    const user = await prisma.profile.create({
      data: {
        email: 'jhonatanancasi@gmail.com',
        password: hashedPassword,
        fullName: 'Jhonatan Anasi',
        role: 'Super Administrador',
        isSuperAdmin: true,
        isActive: true
      }
    })

    logger.info('Seed completado exitosamente', {
      userId: user.id,
      email: user.email
    })

    return NextResponse.json(
      {
        success: true,
        message: 'Seed ejecutado correctamente',
        user: {
          id: user.id,
          email: user.email,
          fullName: user.fullName,
          role: user.role,
          isSuperAdmin: user.isSuperAdmin
        },
        credentials: {
          email: 'jhonatanancasi@gmail.com',
          password: '10571705',
          warning: '⚠️ Cambia la contraseña después del primer login'
        }
      },
      { status: 201 }
    )
  } catch (error: any) {
    logger.error('Error ejecutando seed', error, {
      endpoint: 'admin_seed'
    })

    return NextResponse.json(
      {
        error: 'Error al ejecutar el seed',
        message: error.message || 'Error desconocido'
      },
      { status: 500 }
    )
  }
}

/**
 * GET: Verificar estado del seed (sin ejecutarlo)
 */
export async function GET() {
  try {
    const existingUser = await prisma.profile.findUnique({
      where: { email: 'jhonatanancasi@gmail.com' }
    })

    return NextResponse.json({
      seedExecuted: !!existingUser,
      userExists: !!existingUser,
      userId: existingUser?.id || null
    })
  } catch (error: any) {
    return NextResponse.json(
      { error: 'Error al verificar estado del seed' },
      { status: 500 }
    )
  }
}

"use client"

import {
  BarChart3,
  TrendingUp,
  Users,
  Package,
  DollarSign,
  Target,
  Brain,
  PieChart,
  LineChart,
  Activity,
  Sparkles,
  Lightbulb,
  AlertTriangle,
  MessageSquare,
  FileText,
  Download,
  Loader2
} from "lucide-react"
import { useTranslations } from "next-intl"
import { useState, useEffect, useCallback } from "react"
import { toast } from "sonner"

import { CustomerSegmentationChart } from "./customer-segmentation-chart"
import { DateRangePicker } from "./date-range-picker"
import { KPICard } from "./kpi-card"
import { KPICustomizer } from "./kpi-customizer"
import { ProductProfitabilityTable } from "./product-profitability-table"
import { SalesPredictionsChart } from "./sales-predictions-chart"
import { TrendsChart } from "./trends-chart"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Textarea } from "@/components/ui/textarea"


interface AnalyticsPageClientProps {
  organizationId: string
  customerSlug: string
}

export function AnalyticsPageClient({ organizationId, customerSlug }: AnalyticsPageClientProps) {
  const t = useTranslations()
  const [kpis, setKpis] = useState<any[]>([])
  const [trends, setTrends] = useState<any[]>([])
  const [profitability, setProfitability] = useState<any[]>([])
  const [segments, setSegments] = useState<any[]>([])
  const [predictions, setPredictions] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [dateRange, setDateRange] = useState<{ start: Date; end: Date } | null>(null)
  const [selectedKPIs, setSelectedKPIs] = useState<string[]>([])
  const [aiInsights, setAiInsights] = useState<{
    summary: string
    highlights: string[]
    anomalies: string[]
    recommendations: string[]
    scenarios: Array<{ title: string; description: string; impact: string }>
  } | null>(null)
  const [aiLoading, setAiLoading] = useState(false)
  const [chatMessages, setChatMessages] = useState<Array<{ role: "user" | "assistant"; content: string }>>([
    {
      role: "assistant",
      content:
        t("analytics.ai.chatIntro") ||
        "Hola, soy tu asistente inteligente. Pregúntame sobre ventas, clientes o cualquier indicador del período.",
    },
  ])
  const [chatInput, setChatInput] = useState("")
  const [chatLoading, setChatLoading] = useState(false)
  const [reportGenerating, setReportGenerating] = useState(false)

  const buildQuery = useCallback(() => {
    const params = new URLSearchParams()
    if (dateRange) {
      params.append("start", dateRange.start.toISOString())
      params.append("end", dateRange.end.toISOString())
    }
    return params.toString()
  }, [dateRange])

  const loadAnalytics = useCallback(async () => {
    setLoading(true)
    try {
      const query = buildQuery()
      const [kpisRes, trendsRes, profitabilityRes, segmentsRes, predictionsRes] = await Promise.all([
        fetch(`/api/${customerSlug}/analytics/kpis${query ? `?${query}` : ""}`, { credentials: "include" }),
        fetch(`/api/${customerSlug}/analytics/trends${query ? `?${query}` : ""}`, { credentials: "include" }),
        fetch(`/api/${customerSlug}/analytics/profitability${query ? `?${query}` : ""}`, { credentials: "include" }),
        fetch(`/api/${customerSlug}/analytics/segmentation`, { credentials: "include" }),
        fetch(`/api/${customerSlug}/analytics/predictions`, { credentials: "include" }),
      ])

      const [kpisData, trendsData, profitabilityData, segmentsData, predictionsData] = await Promise.all([
        kpisRes.json(),
        trendsRes.json(),
        profitabilityRes.json(),
        segmentsRes.json(),
        predictionsRes.json(),
      ])

      if (kpisData.success) setKpis(kpisData.data || [])
      if (trendsData.success) setTrends(trendsData.data || [])
      if (profitabilityData.success) setProfitability(profitabilityData.data || [])
      if (segmentsData.success) setSegments(segmentsData.data || [])
      if (predictionsData.success) setPredictions(predictionsData.data || [])

      // Inicializar KPIs seleccionados con todos los disponibles
      if (kpisData.success && kpisData.data) {
        setSelectedKPIs((prev) => (prev.length === 0 ? kpisData.data.map((k: any) => k.id) : prev))
      }
    } catch (error) {
      console.error("Error cargando analytics:", error)
    } finally {
      setLoading(false)
    }
  }, [buildQuery, customerSlug])

  const loadAIInsights = useCallback(async () => {
    setAiLoading(true)
    try {
      const query = buildQuery()
      const response = await fetch(`/api/${customerSlug}/analytics/insights${query ? `?${query}` : ""}`, {
        credentials: "include",
      })
      const data = await response.json()
      if (!response.ok || !data.success) {
        throw new Error(data.error || "No se pudieron cargar los insights")
      }
      setAiInsights(data.data)
    } catch (error) {
      console.error("Error cargando insights IA:", error)
      toast.error("No se pudieron cargar los insights inteligentes.")
      setAiInsights(null)
    } finally {
      setAiLoading(false)
    }
  }, [buildQuery, customerSlug])

  useEffect(() => {
    loadAnalytics()
    loadAIInsights()
  }, [loadAnalytics, loadAIInsights])

  const handleAskQuestion = async () => {
    if (!chatInput.trim()) return
    const newMessages = [...chatMessages, { role: "user" as const, content: chatInput.trim() }]
    setChatMessages(newMessages)
    setChatInput("")
    setChatLoading(true)

    try {
      const history = newMessages.slice(-6)
      const payload: any = {
        question: newMessages[newMessages.length - 1].content,
        history: history,
      }
      if (dateRange) {
        payload.dateRange = {
          start: dateRange.start.toISOString(),
          end: dateRange.end.toISOString(),
        }
      }
      const response = await fetch(`/api/${customerSlug}/analytics/ask`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(payload),
      })
      const data = await response.json()
      if (!response.ok || !data.success) {
        throw new Error(data.error || "No se pudo obtener la respuesta")
      }
      setChatMessages((prev) => [...prev, { role: "assistant", content: data.data.answer }])
    } catch (error: any) {
      console.error("Error consultando IA:", error)
      toast.error(error?.message || "No se pudo responder la pregunta.")
      setChatMessages((prev) => [
        ...prev,
        { role: "assistant", content: "No pude obtener la respuesta en este momento. Intenta de nuevo más tarde." },
      ])
    } finally {
      setChatLoading(false)
    }
  }

  const handleGenerateReport = async () => {
    setReportGenerating(true)
    try {
      const payload: any = {}
      if (dateRange) {
        payload.dateRange = {
          start: dateRange.start.toISOString(),
          end: dateRange.end.toISOString(),
        }
      }
      const response = await fetch(`/api/${customerSlug}/analytics/report`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(payload),
      })
      const data = await response.json()
      if (!response.ok || !data.success) {
        throw new Error(data.error || "No se pudo generar el reporte")
      }

      const markdown = data.data?.markdown || ""
      const blob = new Blob([markdown], { type: "text/markdown" })
      const url = URL.createObjectURL(blob)
      const link = document.createElement("a")
      const filename = `reporte-analytics-${new Date().toISOString().slice(0, 10)}.md`
      link.href = url
      link.download = filename
      link.click()
      URL.revokeObjectURL(url)
      toast.success(t("analytics.ai.reportSuccess") || "Reporte generado correctamente.")
    } catch (error: any) {
      console.error("Error generando reporte:", error)
      toast.error(error?.message || t("analytics.ai.reportError") || "No se pudo generar el reporte.")
    } finally {
      setReportGenerating(false)
    }
  }

  const displayedKPIs = kpis.filter(kpi => selectedKPIs.includes(kpi.id))

  return (
    <div className="space-y-6 p-4 md:p-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white">
            {t('analytics.title') || 'Analytics y Business Intelligence'}
          </h1>
          <p className="text-sm md:text-base text-gray-600 dark:text-gray-400 mt-1">
            {t('analytics.description') || 'Análisis avanzado de datos y métricas de tu negocio'}
          </p>
        </div>
        <DateRangePicker
          dateRange={dateRange}
          onDateRangeChange={setDateRange}
        />
      </div>

      {/* KPIs Personalizables */}
      <div>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white flex items-center gap-2">
            <Target className="h-5 w-5" />
            {t('analytics.kpis.title') || 'KPIs Principales'}
          </h2>
          <KPICustomizer
            kpis={kpis}
            selectedKPIs={selectedKPIs}
            onKPIsChange={setSelectedKPIs}
          />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4">
          {loading ? (
            Array.from({ length: 5 }).map((_, i) => (
              <Card key={i} className="animate-pulse">
                <CardContent className="p-6">
                  <div className="h-20 bg-gray-200 dark:bg-gray-700 rounded" />
                </CardContent>
              </Card>
            ))
          ) : (
            displayedKPIs.map((kpi) => (
              <KPICard key={kpi.id} kpi={kpi} customerSlug={customerSlug} />
            ))
          )}
        </div>
      </div>

      {/* AI Insights */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Card className="border-dashed border-gray-200 dark:border-gray-800">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-purple-500" />
              {t("analytics.ai.summaryTitle") || "Resumen inteligente"}
            </CardTitle>
            <CardDescription>
              {t("analytics.ai.summaryDescription") || "Narrativa automática generada con IA."}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {aiLoading ? (
              <div className="space-y-2">
                <div className="h-4 w-3/4 bg-gray-200 dark:bg-gray-800 rounded animate-pulse" />
                <div className="h-4 w-2/3 bg-gray-200 dark:bg-gray-800 rounded animate-pulse" />
                <div className="h-4 w-1/2 bg-gray-200 dark:bg-gray-800 rounded animate-pulse" />
              </div>
            ) : aiInsights ? (
              <>
                <p className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed">
                  {aiInsights.summary}
                </p>
                <div>
                  <p className="text-xs font-semibold text-gray-500 uppercase mb-2">
                    {t("analytics.ai.highlights") || "Puntos destacados"}
                  </p>
                  <ul className="space-y-2">
                    {aiInsights.highlights.length > 0 ? (
                      aiInsights.highlights.map((item, index) => (
                        <li key={index} className="text-sm text-gray-700 dark:text-gray-300">
                          • {item}
                        </li>
                      ))
                    ) : (
                      <li className="text-sm text-gray-500">
                        {t("analytics.ai.insightsEmpty") || "Sin novedades para este período."}
                      </li>
                    )}
                  </ul>
                </div>
              </>
            ) : (
              <p className="text-sm text-gray-500">{t("analytics.ai.summaryFallback") || "Sin datos disponibles."}</p>
            )}
          </CardContent>
        </Card>

        <Card className="border-dashed border-gray-200 dark:border-gray-800">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Lightbulb className="h-5 w-5 text-amber-500" />
              {t("analytics.ai.recommendationsTitle") || "Recomendaciones e insights"}
            </CardTitle>
            <CardDescription>
              {t("analytics.ai.recommendationsDescription") || "Acciones sugeridas y alertas detectadas automáticamente."}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            <div>
              <div className="flex items-center gap-2 text-sm font-semibold text-rose-600 dark:text-rose-400 mb-2">
                <AlertTriangle className="h-4 w-4" />
                {t("analytics.ai.anomaliesTitle") || "Anomalías"}
              </div>
              <ul className="space-y-2">
                {aiLoading ? (
                  <li className="h-4 w-full bg-gray-200 dark:bg-gray-800 rounded animate-pulse" />
                ) : aiInsights && aiInsights.anomalies.length > 0 ? (
                  aiInsights.anomalies.map((item, index) => (
                    <li key={index} className="text-sm text-gray-700 dark:text-gray-300">
                      • {item}
                    </li>
                  ))
                ) : (
                  <li className="text-sm text-gray-500">
                    {t("analytics.ai.noAnomalies") || "Sin anomalías relevantes detectadas."}
                  </li>
                )}
              </ul>
            </div>
            <div>
              <div className="flex items-center gap-2 text-sm font-semibold text-emerald-600 dark:text-emerald-400 mb-2">
                <Lightbulb className="h-4 w-4" />
                {t("analytics.ai.recommendations") || "Recomendaciones"}
              </div>
              <ul className="space-y-2">
                {aiLoading ? (
                  <li className="h-4 w-full bg-gray-200 dark:bg-gray-800 rounded animate-pulse" />
                ) : aiInsights && aiInsights.recommendations.length > 0 ? (
                  aiInsights.recommendations.map((item, index) => (
                    <li key={index} className="text-sm text-gray-700 dark:text-gray-300">
                      • {item}
                    </li>
                  ))
                ) : (
                  <li className="text-sm text-gray-500">
                    {t("analytics.ai.noRecommendations") || "Sin acciones específicas por ahora."}
                  </li>
                )}
              </ul>
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Card className="border-dashed border-gray-200 dark:border-gray-800">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <BarChart3 className="h-5 w-5 text-blue-500" />
              {t("analytics.ai.scenariosTitle") || "Escenarios simulados"}
            </CardTitle>
            <CardDescription>
              {t("analytics.ai.scenariosDescription") || "Explora impactos potenciales con IA."}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {aiLoading ? (
              <>
                <div className="h-16 bg-gray-200 dark:bg-gray-800 rounded animate-pulse" />
                <div className="h-16 bg-gray-200 dark:bg-gray-800 rounded animate-pulse" />
              </>
            ) : aiInsights && aiInsights.scenarios.length > 0 ? (
              aiInsights.scenarios.map((scenario, index) => (
                <div key={index} className="border border-gray-200 dark:border-gray-700 rounded-lg p-3">
                  <p className="text-sm font-semibold text-gray-900 dark:text-white">{scenario.title}</p>
                  <p className="text-sm text-gray-600 dark:text-gray-300 mt-1">{scenario.description}</p>
                  <p className="text-xs text-blue-600 dark:text-blue-300 mt-2">{scenario.impact}</p>
                </div>
              ))
            ) : (
              <p className="text-sm text-gray-500">{t("analytics.ai.noScenarios") || "Sin escenarios disponibles."}</p>
            )}
          </CardContent>
        </Card>

        <Card className="border-dashed border-gray-200 dark:border-gray-800">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <MessageSquare className="h-5 w-5 text-cyan-500" />
              {t("analytics.ai.chatTitle") || "Asistente conversacional"}
            </CardTitle>
            <CardDescription>
              {t("analytics.ai.chatDescription") || "Haz preguntas directas sobre tus métricas."}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="h-48 overflow-y-auto space-y-3 pr-2 mb-4">
              {chatMessages.map((message, index) => (
                <div
                  key={index}
                  className={`rounded-xl px-3 py-2 text-sm ${
                    message.role === "assistant"
                      ? "bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-gray-100"
                      : "bg-blue-600 text-white ml-auto"
                  } max-w-full`}
                >
                  {message.content}
                </div>
              ))}
            </div>
            <div className="space-y-2">
              <Textarea
                placeholder={t("analytics.ai.chatPlaceholder") || "Ej. ¿Cuál fue el margen promedio esta semana?"}
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                disabled={chatLoading}
                className="min-h-[90px]"
              />
              <div className="flex justify-end">
                <Button onClick={handleAskQuestion} disabled={chatLoading || !chatInput.trim()}>
                  {chatLoading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                  {t("analytics.ai.chatButton") || "Preguntar"}
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card className="border-dashed border-gray-200 dark:border-gray-800">
        <CardHeader className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5 text-indigo-500" />
              {t("analytics.ai.reportTitle") || "Reporte ejecutivo con IA"}
            </CardTitle>
            <CardDescription>
              {t("analytics.ai.reportDescription") || "Genera un documento listo para compartir con tu equipo."}
            </CardDescription>
          </div>
          <Button onClick={handleGenerateReport} disabled={reportGenerating}>
            {reportGenerating ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                {t("analytics.ai.reportGenerating") || "Generando..."}
              </>
            ) : (
              <>
                <Download className="h-4 w-4 mr-2" />
                {t("analytics.ai.reportButton") || "Descargar reporte"}
              </>
            )}
          </Button>
        </CardHeader>
      </Card>

      {/* Tabs con diferentes análisis */}
      <Tabs defaultValue="trends" className="space-y-4">
        <TabsList className="grid w-full grid-cols-2 md:grid-cols-5">
          <TabsTrigger value="trends" className="flex items-center gap-2">
            <TrendingUp className="h-4 w-4" />
            <span className="hidden sm:inline">{t('analytics.tabs.trends') || 'Tendencias'}</span>
          </TabsTrigger>
          <TabsTrigger value="profitability" className="flex items-center gap-2">
            <DollarSign className="h-4 w-4" />
            <span className="hidden sm:inline">{t('analytics.tabs.profitability') || 'Rentabilidad'}</span>
          </TabsTrigger>
          <TabsTrigger value="segmentation" className="flex items-center gap-2">
            <Users className="h-4 w-4" />
            <span className="hidden sm:inline">{t('analytics.tabs.segmentation') || 'Segmentación'}</span>
          </TabsTrigger>
          <TabsTrigger value="predictions" className="flex items-center gap-2">
            <Brain className="h-4 w-4" />
            <span className="hidden sm:inline">{t('analytics.tabs.predictions') || 'Predicciones'}</span>
          </TabsTrigger>
          <TabsTrigger value="overview" className="flex items-center gap-2">
            <BarChart3 className="h-4 w-4" />
            <span className="hidden sm:inline">{t('analytics.tabs.overview') || 'Resumen'}</span>
          </TabsTrigger>
        </TabsList>

        <TabsContent value="trends" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <LineChart className="h-5 w-5" />
                {t('analytics.trends.title') || 'Análisis de Tendencias'}
              </CardTitle>
              <CardDescription>
                {t('analytics.trends.description') || 'Evolución de ventas e ingresos en el tiempo'}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <TrendsChart data={trends} loading={loading} customerSlug={customerSlug} />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="profitability" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <DollarSign className="h-5 w-5" />
                {t('analytics.profitability.title') || 'Rentabilidad por Producto'}
              </CardTitle>
              <CardDescription>
                {t('analytics.profitability.description') || 'Análisis de ingresos, costos y márgenes de ganancia por producto'}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <ProductProfitabilityTable data={profitability} loading={loading} customerSlug={customerSlug} />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="segmentation" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <PieChart className="h-5 w-5" />
                {t('analytics.segmentation.title') || 'Segmentación de Clientes'}
              </CardTitle>
              <CardDescription>
                {t('analytics.segmentation.description') || 'Análisis RFM: Recency, Frequency, Monetary'}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <CustomerSegmentationChart data={segments} loading={loading} customerSlug={customerSlug} />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="predictions" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Brain className="h-5 w-5" />
                {t('analytics.predictions.title') || 'Predicciones con Machine Learning'}
              </CardTitle>
              <CardDescription>
                {t('analytics.predictions.description') || 'Pronósticos de ventas futuras basados en datos históricos'}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <SalesPredictionsChart data={predictions} loading={loading} customerSlug={customerSlug} />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="overview" className="space-y-4">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Activity className="h-5 w-5" />
                  {t('analytics.overview.trends') || 'Tendencias Rápidas'}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <TrendsChart data={trends.slice(-30)} loading={loading} customerSlug={customerSlug} />
              </CardContent>
            </Card>
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Package className="h-5 w-5" />
                  {t('analytics.overview.topProducts') || 'Top Productos Rentables'}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <ProductProfitabilityTable data={profitability.slice(0, 5)} loading={loading} customerSlug={customerSlug} />
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  )
}

"use client";

import { useTranslations } from "next-intl";
import { useState, useEffect, useCallback } from "react";

import type { CashRegisterWithRelations } from "./types"

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";


interface CashRegisterFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  cashRegister?: CashRegisterWithRelations;
  customerSlug: string;
  onSave: (data: any) => void;
  maxBranches?: number | null;
  openCashRegisters?: CashRegisterWithRelations[]; // Cajas abiertas para filtrar sucursales
}

const formatDateForName = (date: Date) =>
  date.toLocaleDateString("es-BO", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  });

const getDefaultCashRegisterName = () => {
  const now = new Date();
  const weekday = now
    .toLocaleDateString("es-BO", { weekday: "long" })
    .toLowerCase();
  return `Caja ${
    weekday.charAt(0).toUpperCase() + weekday.slice(1)
  } ${formatDateForName(now)}`;
};

const getCurrentDateTimeDisplay = () =>
  new Date().toLocaleString("es-BO", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });

export function CashRegisterFormDialog({
  open,
  onOpenChange,
  cashRegister,
  customerSlug,
  onSave,
  maxBranches,
  openCashRegisters = [],
}: CashRegisterFormDialogProps) {
  const t = useTranslations()
  const [name, setName] = useState("");
  const [branchId, setBranchId] = useState("");
  const [openingBalance, setOpeningBalance] = useState("0");
  const [branches, setBranches] = useState<any[]>([]);
  const [allBranches, setAllBranches] = useState<any[]>([]); // Todas las sucursales (sin filtrar)
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [currentDateTime, setCurrentDateTime] = useState<string>(
    getCurrentDateTimeDisplay()
  );
  const [currentUser, setCurrentUser] = useState<{ isAdmin: boolean; branchId: string | null } | null>(null);

  const loadBranches = useCallback(async () => {
    try {
      setIsLoadingData(true);
      const response = await fetch(`/api/${customerSlug}/sucursales`);
      if (response.ok) {
        const data = await response.json();
        const allBranchesData = data.branches || [];
        setAllBranches(allBranchesData); // Guardar todas las sucursales
        
        // Si el usuario NO es administrador, no necesitamos filtrar (no verá el select)
        if (!currentUser?.isAdmin) {
          setBranches(allBranchesData);
          return;
        }
        
        // Para administradores: filtrar sucursales con cajas abiertas
        const branchesWithOpenCashRegister = new Set(
          openCashRegisters
            .filter(register => register.isOpen && register.branchId)
            .map(register => register.branchId)
        );
        
        // Si estamos editando una caja existente, no filtrar su sucursal actual
        const currentBranchId = cashRegister?.branchId;
        
        // Filtrar sucursales: mostrar solo las que no tienen caja abierta
        // O la sucursal actual si estamos editando
        const availableBranches = allBranchesData.filter((branch: any) => {
          // Si es la sucursal de la caja que estamos editando, siempre mostrarla
          if (currentBranchId && branch.id === currentBranchId) {
            return true;
          }
          // Para nuevas cajas o otras sucursales, solo mostrar si no tienen caja abierta
          return !branchesWithOpenCashRegister.has(branch.id);
        });
        
        setBranches(availableBranches);
      }
    } catch (error) {
      console.error("Error al cargar sucursales:", error);
    } finally {
      setIsLoadingData(false);
    }
  }, [customerSlug, openCashRegisters, cashRegister, currentUser]);

  const loadCurrentUser = useCallback(async () => {
    try {
      const response = await fetch(`/api/${customerSlug}/auth/me`, {
        credentials: 'include'
      });
      if (response.ok) {
        const userData = await response.json();
        // Verificar si el usuario es administrador (rol nombre "Administrador")
        const isAdmin = userData.rol?.nombre?.toLowerCase() === 'administrador' || 
                       userData.rol?.name?.toLowerCase() === 'administrador';
        setCurrentUser({
          isAdmin,
          branchId: userData.sucursalId || userData.branchId || null
        });
      }
    } catch (error) {
      console.error("Error al cargar usuario:", error);
    }
  }, [customerSlug]);

  // Cargar usuario actual primero
  useEffect(() => {
    if (open) {
      loadCurrentUser();
    }
  }, [open, loadCurrentUser]);

  // Cargar sucursales después de que el usuario esté disponible
  useEffect(() => {
    if (open && currentUser !== null) {
      loadBranches();
    }
  }, [open, currentUser, loadBranches]);

  // Cargar datos de la caja si existe
  useEffect(() => {
    if (cashRegister && open) {
      setName(cashRegister.name || "");
      setBranchId(cashRegister.branchId || "");
      setOpeningBalance(Number(cashRegister.openingBalance).toString());
    } else if (!cashRegister && open) {
      // Generar nombre por defecto usando traducciones
      const now = new Date();
      const weekday = now.toLocaleDateString("es-BO", { weekday: "long" }).toLowerCase();
      const formattedDate = formatDateForName(now);
      setName(`${t('cashRegisters.title').split(' ')[0]} ${
        weekday.charAt(0).toUpperCase() + weekday.slice(1)
      } ${formattedDate}`);
      setBranchId("");
      setOpeningBalance("0");
    }
  }, [cashRegister, open, t]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!name.trim()) {
      return;
    }

    setIsLoading(true);
    try {
      // Si el usuario NO es administrador, usar su sucursal automáticamente
      // Si el usuario ES administrador, permitir selección manual
      let branchIdForSubmit: string | undefined = undefined
      
      if (!currentUser?.isAdmin && currentUser?.branchId) {
        // Usuario NO administrador: usar su sucursal automáticamente
        branchIdForSubmit = currentUser.branchId
      } else if (shouldHideBranchSelect && branches.length === 1) {
        // Plan con una sola sucursal: asignar automáticamente
        branchIdForSubmit = branches[0].id
      } else if (currentUser?.isAdmin) {
        // Usuario administrador: permitir selección manual
        branchIdForSubmit = branchId || undefined
      } else {
        // Por defecto: sin sucursal
        branchIdForSubmit = undefined
      }
      
      await onSave({
        name: name.trim(),
        branchId: branchIdForSubmit,
        openingBalance: parseFloat(openingBalance) || 0,
      });
    } finally {
      setIsLoading(false);
    }
  };

  // Ocultar select de sucursal si:
  // 1. El usuario NO es administrador - se usa su sucursal automáticamente
  // NOTA: Para administradores, siempre mostrar el select si hay sucursales disponibles
  // (incluso si maxBranches === 1, el admin puede elegir la sucursal)
  const shouldHideBranchSelect = 
    currentUser !== null && !currentUser.isAdmin

  useEffect(() => {
    if (!open) {
      return;
    }

    if (!currentUser?.isAdmin && currentUser?.branchId) {
      // Usuario NO administrador: usar su sucursal automáticamente
      setBranchId(currentUser.branchId);
    } else if (shouldHideBranchSelect && branches.length === 1) {
      // Si el select está oculto y hay una sola sucursal, seleccionarla automáticamente
      setBranchId(branches[0].id);
    } else if (branches.length === 1 && !cashRegister) {
      // Si hay una sola sucursal y no es edición, seleccionarla
      setBranchId(branches[0].id);
    }
  }, [branches, open, shouldHideBranchSelect, cashRegister, currentUser]);

  // Asegurar que cuando se oculta el select, siempre se tenga la sucursal seleccionada
  useEffect(() => {
    if (!currentUser?.isAdmin && currentUser?.branchId) {
      // Usuario NO administrador: usar su sucursal automáticamente
      setBranchId(currentUser.branchId);
    } else if (shouldHideBranchSelect && branches.length === 1 && !branchId) {
      // Solo asignar automáticamente si hay una sola sucursal
      setBranchId(branches[0].id);
    }
  }, [shouldHideBranchSelect, branches, branchId, currentUser]);

  useEffect(() => {
    if (!open) {
      return;
    }

    const updateDateTime = () =>
      setCurrentDateTime(getCurrentDateTimeDisplay());
    updateDateTime();

    const intervalId = window.setInterval(updateDateTime, 1000);

    return () => window.clearInterval(intervalId);
  }, [open]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px] lg:max-w-2xl max-h-[92vh] flex flex-col overflow-hidden p-0 rounded-lg">
        <div className="px-6 sm:px-8 py-5 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky top-0 z-10">
          <DialogHeader className="px-0 py-0 space-y-2">
            <DialogTitle className="text-2xl font-semibold text-gray-900 dark:text-white">
              {cashRegister ? t('cashRegisters.edit') : t('cashRegisters.new')}
            </DialogTitle>
            <DialogDescription className="text-gray-500 dark:text-gray-400">
              {cashRegister
                ? t('cashRegisters.editDescription')
                : t('cashRegisters.newDescription')}
            </DialogDescription>
          </DialogHeader>
        </div>
        <form onSubmit={handleSubmit} className="flex flex-col flex-1 min-h-0">
          <div className="flex-1 overflow-y-auto px-6 sm:px-8 py-6 space-y-6 bg-gray-50/60 dark:bg-[#0c0c0c]">
            {/* Nombre generado */}
            <div className="space-y-2">
              <Label>{t('cashRegisters.form.name')}</Label>
              <div className="rounded-full bg-gray-100 dark:bg-[#2a2a2a] border border-gray-200 dark:border-[#2a2a2a] px-4 py-3 text-sm font-medium text-gray-900 dark:text-white">
                {name}
              </div>
            </div>

            {/* Sucursal */}
            {currentUser !== null && !currentUser.isAdmin && currentUser.branchId ? (
              <div className="space-y-2">
                <Label>{t('form.branch')}</Label>
                <div className="rounded-full bg-gray-100 dark:bg-[#2a2a2a] border border-gray-200 dark:border-[#2a2a2a] px-4 py-3 text-sm text-gray-600 dark:text-gray-400">
                  {branches.find(b => b.id === currentUser.branchId)?.name || 
                   (allBranches?.find((b: any) => b.id === currentUser.branchId)?.name) || 
                   t('cashRegisters.form.assignedBranch')}
                  <p className="text-xs mt-1 text-gray-500 dark:text-gray-500">
                    {t('cashRegisters.form.willUseBranch')}
                  </p>
                </div>
              </div>
            ) : currentUser !== null && currentUser.isAdmin ? (
              branches.length > 0 ? (
                <div className="space-y-2">
                  <Label htmlFor="branchId">{t('form.branch')}</Label>
                  <Select
                    value={branchId || undefined}
                    onValueChange={setBranchId}
                    disabled={isLoading || isLoadingData}
                  >
                    <SelectTrigger className="rounded-full w-full">
                      <SelectValue placeholder={t('cashRegisters.form.selectBranch')} />
                    </SelectTrigger>
                    <SelectContent>
                      {branches.map((branch) => (
                        <SelectItem key={branch.id} value={branch.id}>
                          {branch.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              ) : (
                <div className="space-y-2">
                  <Label>{t('form.branch')}</Label>
                  <div className="rounded-full bg-gray-100 dark:bg-[#2a2a2a] border border-gray-200 dark:border-[#2a2a2a] px-4 py-3 text-sm text-gray-600 dark:text-gray-400">
                    {t('cashRegisters.form.noBranchesAvailable')}
                  </div>
                </div>
              )
            ) : currentUser === null ? (
              <div className="space-y-2">
                <Label>{t('form.branch')}</Label>
                <div className="rounded-full bg-gray-100 dark:bg-[#2a2a2a] border border-gray-200 dark:border-[#2a2a2a] px-4 py-3 text-sm text-gray-600 dark:text-gray-400">
                  {t('cashRegisters.form.loadingInfo')}
                </div>
              </div>
            ) : null}

            {/* Balance inicial (solo si es nueva caja) */}
            {!cashRegister && (
              <div className="space-y-2">
                <Label htmlFor="openingBalance">{t('cashRegisters.form.initialBalance')}</Label>
                <Input
                  id="openingBalance"
                  type="number"
                  step="0.01"
                  min="0"
                  value={openingBalance}
                  onChange={(e) => setOpeningBalance(e.target.value)}
                  placeholder={t('common.placeholders.amount')}
                  disabled={isLoading}
                  className="rounded-full"
                />
                <p className="text-xs text-gray-500">
                  Este será el balance inicial cuando la caja se abra por
                  primera vez
                </p>
              </div>
            )}
            {/* Fecha y hora actual */}
            <div className="space-y-2">
                <Label htmlFor="currentDateTime">{t('cashRegisters.form.dateTime')}</Label>
              <Input
                id="currentDateTime"
                value={currentDateTime}
                readOnly
                disabled={isLoading || isLoadingData}
                className="rounded-full"
              />
            </div>
          </div>
          <DialogFooter className="flex flex-col sm:flex-row items-stretch sm:items-center justify-center sm:justify-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 sm:px-8 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky bottom-0 z-10">
            <Button
              type="button"
              variant="outline"
              className="rounded-full w-full sm:w-auto"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              {t('action.cancel')}
            </Button>
            <Button
              type="submit"
              variant="new"
              className="rounded-full w-full sm:w-auto"
              disabled={isLoading || !name.trim()}
            >
              {isLoading
                ? t('message.saving')
                : cashRegister
                ? t('action.update')
                : t('action.add')}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Componente para mostrar alertas de stock bajo
 */

"use client"

import { AlertTriangle, Package } from "lucide-react"
import { useTranslations } from "next-intl"
import { useEffect, useState } from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"

interface LowStockAlert {
  productId: string
  productName: string
  currentStock: number
  minStock: number
  reorderPoint: number | null
  branchId?: string | null
  branchName?: string | null
  organizationId: string
}

interface InventoryAlertsProps {
  customerSlug: string
}

export function InventoryAlerts({ customerSlug }: InventoryAlertsProps) {
  const t = useTranslations()
  const [alerts, setAlerts] = useState<LowStockAlert[]>([])
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    loadAlerts()
  }, [customerSlug])

  const loadAlerts = async () => {
    try {
      setIsLoading(true)
      const response = await fetch(`/api/${customerSlug}/inventory/alerts`)
      const data = await response.json()
      
      if (data.success) {
        setAlerts(data.alerts || [])
      }
    } catch (error) {
      console.error("Error cargando alertas:", error)
    } finally {
      setIsLoading(false)
    }
  }

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-yellow-500" />
            {t('inventory.alerts.title') || 'Alertas de Stock Bajo'}
          </CardTitle>
          <CardDescription>
            {t('inventory.alerts.description') || 'Productos con stock bajo o en punto de reorden'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {[1, 2, 3].map((i) => (
              <Skeleton key={i} className="h-20 w-full" />
            ))}
          </div>
        </CardContent>
      </Card>
    )
  }

  if (alerts.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Package className="h-5 w-5 text-green-500" />
            {t('inventory.alerts.title') || 'Alertas de Stock Bajo'}
          </CardTitle>
          <CardDescription>
            {t('inventory.alerts.description') || 'Productos con stock bajo o en punto de reorden'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            {t('inventory.alerts.noAlerts') || 'No hay alertas de stock bajo'}
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-yellow-500" />
              {t('inventory.alerts.title') || 'Alertas de Stock Bajo'}
            </CardTitle>
            <CardDescription>
              {t('inventory.alerts.description') || 'Productos con stock bajo o en punto de reorden'}
            </CardDescription>
          </div>
          <Badge variant="destructive" className="text-sm">
            {alerts.length}
          </Badge>
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-3">
          {alerts.map((alert) => (
            <div
              key={alert.productId}
              className="flex items-center justify-between p-3 rounded-lg border border-yellow-200 dark:border-yellow-900 bg-yellow-50 dark:bg-yellow-950/20"
            >
              <div className="flex-1 min-w-0">
                <div className="font-medium text-gray-900 dark:text-white truncate">
                  {alert.productName}
                </div>
                <div className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                  {alert.branchName && (
                    <span className="mr-2">{alert.branchName}</span>
                  )}
                  <span>
                    {t('inventory.alerts.currentStock') || 'Stock actual'}: <strong>{alert.currentStock}</strong>
                  </span>
                  {alert.reorderPoint !== null && (
                    <span className="ml-2">
                      {t('inventory.alerts.reorderPoint') || 'Punto de reorden'}: <strong>{alert.reorderPoint}</strong>
                    </span>
                  )}
                </div>
              </div>
              <div className="ml-4 text-right">
                <Badge
                  variant={alert.currentStock <= alert.minStock ? "destructive" : "default"}
                  className="text-xs"
                >
                  {alert.currentStock <= alert.minStock
                    ? t('inventory.alerts.belowMin') || 'Bajo mínimo'
                    : t('inventory.alerts.atReorder') || 'En reorden'}
                </Badge>
              </div>
            </div>
          ))}
        </div>
        <div className="mt-4">
          <Button
            variant="outline"
            size="sm"
            onClick={loadAlerts}
            className="w-full rounded-full"
          >
            {t('action.refresh') || 'Actualizar'}
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

"use client"

import { Loader2, CheckSquare2 } from "lucide-react"
import { useTranslations } from "next-intl"
import { useEffect, useState, useMemo } from "react"
import { toast } from "sonner"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { PermissionSasService } from "@/lib/services/sales/permission-sas-service"

interface PermissionSasFormDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSuccess: () => void
  customerSlug: string
  maxBranches?: number | null
}

export function PermissionSasFormDialog({ open, onOpenChange, onSuccess, customerSlug, maxBranches }: PermissionSasFormDialogProps) {
  const t = useTranslations()
  const [selectedModule, setSelectedModule] = useState<string>("")
  const [selectedActions, setSelectedActions] = useState<string[]>([])
  const [existingPermissionNames, setExistingPermissionNames] = useState<string[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [loadingExistingPermissions, setLoadingExistingPermissions] = useState(false)

  // Obtener módulos disponibles y filtrar:
  // - "dashboard" (todos pueden verlo, se maneja con reglas en el módulo)
  // - "sucursales" si maxBranches === 1
  const allModules = PermissionSasService.getAvailableModules()
  const modules = useMemo(() => {
    let filtered = allModules.filter(module => module.id !== 'dashboard')
    
    if (maxBranches === 1) {
      filtered = filtered.filter(module => module.id !== 'sucursales')
    }
    
    return filtered
  }, [allModules, maxBranches])
  
  // Usar useMemo para que actions sea estable y no cause re-renders infinitos
  const actions = useMemo(() => PermissionSasService.getAvailableActions(), [])

  // Reset form when dialog opens/closes
  useEffect(() => {
    if (!open) {
      setSelectedModule("")
      setSelectedActions([])
      setExistingPermissionNames([])
    }
  }, [open])

  // Cargar permisos existentes cuando se selecciona un módulo
  useEffect(() => {
    if (!selectedModule) {
      setSelectedActions([])
      setExistingPermissionNames([])
      return
    }

    let cancelled = false

    const loadExistingPermissions = async () => {
      setLoadingExistingPermissions(true)
      try {
        const response = await fetch(`/api/${customerSlug}/permisos`)
        if (!response.ok) {
          throw new Error("Error al cargar permisos existentes")
        }

        const allPermissions: Array<{ name: string }> = await response.json()
        
        if (cancelled) return
        
        // Filtrar permisos del módulo seleccionado
        const modulePermissions = allPermissions.filter(perm => 
          perm.name.startsWith(`${selectedModule}_`)
        )

        // Extraer las acciones de los permisos existentes
        const existingActions: string[] = []
        const existingNames: string[] = []
        
        actions.forEach(action => {
          const permissionName = PermissionSasService.generatePermissionName(selectedModule, action.id)
          if (modulePermissions.some(p => p.name === permissionName)) {
            existingActions.push(action.id)
            existingNames.push(permissionName)
          }
        })

        if (!cancelled) {
          setSelectedActions(existingActions)
          setExistingPermissionNames(existingNames)
        }
      } catch (error) {
        console.error("Error al cargar permisos existentes:", error)
        if (!cancelled) {
          setSelectedActions([])
        }
      } finally {
        if (!cancelled) {
          setLoadingExistingPermissions(false)
        }
      }
    }

    loadExistingPermissions()

    return () => {
      cancelled = true
    }
  }, [selectedModule, customerSlug, actions])

  const handleActionToggle = (actionId: string) => {
    setSelectedActions(prev =>
      prev.includes(actionId)
        ? prev.filter(id => id !== actionId)
        : [...prev, actionId]
    )
  }

  const handleSelectAllActions = () => {
    if (selectedModule) {
      setSelectedActions(actions.map(action => action.id))
    }
  }

  const handleSubmit = async () => {
    if (!selectedModule) {
      toast.error(t('permissions.sas.moduleRequired'))
      return
    }

    if (selectedActions.length === 0) {
      toast.error(t('permissions.sas.actionsRequired'))
      return
    }

    setIsLoading(true)

    try {
      const existingPermissionsResponse = await fetch(`/api/${customerSlug}/permisos`)
      const existingPermissions: Array<{ name: string }> = existingPermissionsResponse.ok 
        ? await existingPermissionsResponse.json()
        : []

      const allPermissions = selectedActions.map(action =>
        PermissionSasService.generatePermissionName(selectedModule, action)
      )

      const newPermissions = allPermissions.filter(perm =>
        !existingPermissions.some(existing => existing.name === perm)
      )

      if (newPermissions.length === 0) {
        toast.info("Todos los permisos ya están registrados", {
          description: `Todos los permisos seleccionados para el módulo ${modules.find(m => m.id === selectedModule)?.label} ya existen en el sistema`,
        })
        onSuccess()
        onOpenChange(false)
        setIsLoading(false)
        return
      }

      const newActions = selectedActions.filter(action => {
        const permissionName = PermissionSasService.generatePermissionName(selectedModule, action)
        return newPermissions.includes(permissionName)
      })

      const response = await fetch(`/api/${customerSlug}/permisos`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          module: selectedModule,
          actions: newActions,
          permissions: newPermissions,
        }),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || "Error al crear los permisos")
      }

      const existingCount = allPermissions.length - newPermissions.length
      const message = existingCount > 0
        ? `Se han creado ${newPermissions.length} permiso(s) nuevo(s). ${existingCount} permiso(s) ya existían.`
        : `Se han creado ${newPermissions.length} permiso(s) para el módulo ${modules.find(m => m.id === selectedModule)?.label}`

      toast.success(t('permissions.sas.registeredSuccess'), {
        description: message,
      })

      onSuccess()
      onOpenChange(false)
    } catch (error: any) {
      console.error("Error al crear permisos:", error)
      toast.error(t('permissions.sas.errorRegistering'), {
        description: error.message || "No se pudieron crear los permisos",
      })
    } finally {
      setIsLoading(false)
    }
  }

  const selectedModuleLabel = modules.find(m => m.id === selectedModule)?.label || ""

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] lg:max-w-2xl max-h-[90vh] flex flex-col overflow-hidden p-0 rounded-lg">
        <div className="px-6 py-5 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky top-0 z-10">
          <DialogHeader className="px-0 py-0 space-y-2">
            <DialogTitle>Registrar Nuevos Permisos</DialogTitle>
            <DialogDescription>
              Selecciona un módulo y las acciones que deseas registrar como permisos
            </DialogDescription>
          </DialogHeader>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6 bg-gray-50/60 dark:bg-[#0c0c0c]">
          {/* Módulo y Marcar Todos - En una fila de 2 */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="module" className="text-sm font-semibold text-gray-700 dark:text-gray-200">
                Módulo
              </Label>
              <Select value={selectedModule} onValueChange={setSelectedModule}>
                <SelectTrigger id="module" className="rounded-full w-full">
                  <SelectValue placeholder={t('common.placeholders.selectModule')} />
                </SelectTrigger>
                <SelectContent>
                  {modules.map((module) => (
                    <SelectItem key={module.id} value={module.id}>
                      {module.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label className="text-sm font-semibold text-gray-700 dark:text-gray-200 opacity-0 pointer-events-none">
                Acciones
              </Label>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleSelectAllActions}
                disabled={loadingExistingPermissions || !selectedModule}
                className="rounded-full text-xs whitespace-nowrap"
              >
                <CheckSquare2 className="h-3 w-3 mr-1" />
                Marcar Todos
              </Button>
            </div>
          </div>

          {loadingExistingPermissions && selectedModule && (
            <div className="text-xs text-gray-500 dark:text-gray-400">
              Cargando permisos existentes...
            </div>
          )}

          {selectedModule && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 border border-gray-200 dark:border-[#2a2a2a] rounded-lg p-4">
                {actions.map((action) => {
                  const permissionName = PermissionSasService.generatePermissionName(
                    selectedModule,
                    action.id
                  )
                  const description = PermissionSasService.generatePermissionDescription(
                    selectedModule,
                    action.id
                  )
                  const isChecked = selectedActions.includes(action.id)

                  return (
                    <div key={action.id} className="flex items-start space-x-3">
                      <Checkbox
                        id={`action-${action.id}`}
                        checked={isChecked}
                        onCheckedChange={() => handleActionToggle(action.id)}
                        className="mt-1"
                        disabled={loadingExistingPermissions}
                      />
                      <div className="flex-1 space-y-1">
                        <div className="flex items-center gap-2">
                          <Label
                            htmlFor={`action-${action.id}`}
                            className="cursor-pointer font-medium text-gray-900 dark:text-white"
                          >
                            {action.label}
                          </Label>
                          {isChecked && existingPermissionNames.includes(permissionName) && (
                            <span className="text-xs px-2 py-0.5 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 rounded-full">
                              Existente
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-gray-500 dark:text-gray-400">
                          {description}
                        </p>
                        <p className="text-xs font-mono text-gray-400 dark:text-gray-500">
                          {permissionName}
                        </p>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          )}

          {selectedModule && selectedActions.length > 0 && (() => {
            const newPermissions = selectedActions
              .map(action => PermissionSasService.generatePermissionName(selectedModule, action))
              .filter(name => !existingPermissionNames.includes(name))
            
            const existingCount = selectedActions.length - newPermissions.length

            return (
              <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
                <p className="text-sm font-semibold text-blue-900 dark:text-blue-200 mb-2">
                  Permisos seleccionados ({selectedActions.length}):
                  {existingCount > 0 && (
                    <span className="ml-2 text-xs font-normal text-green-700 dark:text-green-300">
                      ({existingCount} existente(s), {newPermissions.length} nuevo(s))
                    </span>
                  )}
                </p>
                <ul className="space-y-1">
                  {selectedActions.map((action) => {
                    const permissionName = PermissionSasService.generatePermissionName(
                      selectedModule,
                      action
                    )
                    const isExisting = existingPermissionNames.includes(permissionName)
                    return (
                      <li key={action} className="text-xs font-mono text-blue-700 dark:text-blue-300 flex items-center gap-2 flex-wrap">
                        <span>• {permissionName}</span>
                        {isExisting && (
                          <span className="text-xs px-1.5 py-0.5 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 rounded-full">
                            Ya existe
                          </span>
                        )}
                        {!isExisting && (
                          <span className="text-xs px-1.5 py-0.5 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 rounded-full">
                            Nuevo
                          </span>
                        )}
                      </li>
                    )
                  })}
                </ul>
              </div>
            )
          })()}
        </div>

        <DialogFooter className="flex w-full flex-col sm:flex-row sm:justify-center items-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky bottom-0 z-10">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isLoading}
            className="w-full sm:w-auto rounded-full"
          >
            Cancelar
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={!selectedModule || selectedActions.length === 0 || isLoading}
            className="w-full sm:w-auto rounded-full px-6"
          >
            {isLoading ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Agregando...
              </>
            ) : (
              "Agregar"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"


import { SalesProduct, Category, Branch } from "@prisma/client"
import { Package, Edit, Power, PowerOff, Trash2, Building2, Sparkles, Eye } from "lucide-react"
import { useTranslations } from "next-intl"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card"
import { CardsGridSkeleton } from "@/components/ui/cards-grid-skeleton"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"

interface ProductsGridProps {
  products: (SalesProduct & { category: Category | null; branch: Branch | null })[]
  isLoading?: boolean
  showBranchColumn?: boolean
  onEdit?: (product: SalesProduct & { category: Category | null; branch: Branch | null }) => void
  onDelete?: (product: SalesProduct & { category: Category | null; branch: Branch | null }) => void
  onToggleStatus?: (product: SalesProduct & { category: Category | null; branch: Branch | null }) => void
  onView?: (product: SalesProduct & { category: Category | null; branch: Branch | null }) => void
}

import { formatCurrencyWithPreferences } from "@/lib/utils/preferences"
import { getProductDescription } from "@/lib/utils/product-description"

function formatCurrency(value: number | string | { toNumber?: () => number }) {
  let numericValue = 0
  if (value && typeof value === 'object' && 'toNumber' in value && value.toNumber) {
    numericValue = value.toNumber()
  } else {
    numericValue = typeof value === "string" ? Number(value) : Number(value)
  }
  if (Number.isNaN(numericValue)) return "-"
  return formatCurrencyWithPreferences(numericValue)
}

function truncateText(text: string | null | undefined, maxLength = 120) {
  if (!text) return ""
  if (text.length <= maxLength) return text
  const truncated = text.slice(0, maxLength)
  const lastSpace = truncated.lastIndexOf(" ")
  return `${truncated.slice(0, lastSpace > 60 ? lastSpace : maxLength).trimEnd()}...`
}

export function ProductsGrid({
  products,
  isLoading = false,
  showBranchColumn = false,
  onEdit,
  onDelete,
  onToggleStatus,
  onView,
}: ProductsGridProps) {
  const t = useTranslations()
  if (isLoading) {
    return <CardsGridSkeleton columns={3} />
  }

  if (products.length === 0) {
    return (
      <Card className="border-dashed border-gray-200 dark:border-[#2a2a2a] bg-white/60 dark:bg-[#0f0f0f]/60">
        <CardHeader className="items-center text-center">
          <div className="flex h-16 w-16 items-center justify-center rounded-full bg-gray-100 dark:bg-[#1f1f1f]">
            <Package className="h-8 w-8 text-gray-400 dark:text-gray-500" />
          </div>
          <CardTitle className="text-lg">Sin productos</CardTitle>
          <CardDescription>No encontramos productos para los filtros seleccionados.</CardDescription>
        </CardHeader>
      </Card>
    )
  }

  return (
    <TooltipProvider>
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">
        {products.map((product) => {
          const isActive = product.isActive
          const isLowStock = product.stock <= product.minStock
          // Obtener descripción según el idioma actual
          const currentLanguage = (() => {
            try {
              const prefs = JSON.parse(localStorage.getItem('sas_prefs') || '{}');
              return prefs?.language || 'es';
            } catch {
              return 'es';
            }
          })();
          const description = getProductDescription(
            product.description,
            (product as any).descriptionTranslations,
            currentLanguage
          )?.trim() ?? ""

          return (
            <Card
              key={product.id}
              className="border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#1a1a1a] shadow-sm"
            >
              <CardHeader className="gap-4 pb-0">
                <div className="relative h-40 w-full overflow-hidden rounded-xl bg-gray-100 dark:bg-[#2a2a2a]">
                  {product.imageUrl ? (
                     
                    <img
                      src={product.imageUrl}
                      alt={product.name}
                      className="h-full w-full object-cover"
                      onError={(e) => {
                        const target = e.target as HTMLImageElement
                        target.style.display = "none"
                        const fallback = target.nextElementSibling as HTMLElement | null
                        if (fallback) {
                          fallback.style.display = "flex"
                        }
                      }}
                    />
                  ) : null}
                  <div
                    className="absolute inset-0 hidden h-full w-full items-center justify-center"
                    style={{ display: product.imageUrl ? "none" : "flex" }}
                  >
                    <Package className="h-10 w-10 text-gray-400 dark:text-gray-500" />
                  </div>
                </div>
                <div className="flex items-start justify-between gap-3">
                  <div className="space-y-1">
                    <CardTitle className="text-base leading-tight text-gray-900 dark:text-white">
                      {product.name}
                    </CardTitle>
                    {product.sku && (
                      <CardDescription className="text-xs font-medium uppercase tracking-wide">
                        SKU: {product.sku}
                      </CardDescription>
                    )}
                  </div>
                  <Badge
                    className={
                      isActive
                        ? "bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400 border-green-200 dark:border-green-800"
                        : "bg-gray-100 text-gray-700 dark:bg-gray-900/20 dark:text-gray-400 border-gray-200 dark:border-gray-800"
                    }
                  >
                    {isActive ? "Activo" : "Inactivo"}
                  </Badge>
                </div>
              </CardHeader>

              <CardContent className="space-y-4 pt-4">
                <div className="grid grid-cols-2 gap-x-4 gap-y-2 text-sm">
                  <div className="text-muted-foreground">Marca</div>
                  <div className="font-medium text-gray-900 dark:text-white">
                    {product.brand?.trim() || "-"}
                  </div>
                  <div className="text-muted-foreground">Modelo</div>
                  <div className="font-medium text-gray-900 dark:text-white">
                    {product.model?.trim() || "-"}
                  </div>
                  <div className="text-muted-foreground">Precio venta</div>
                  <div className="font-semibold text-gray-900 dark:text-white">
                    {formatCurrency(product.price)}
                  </div>
                  <div className="text-muted-foreground">Precio compra</div>
                  <div className="text-sm text-gray-700 dark:text-gray-300">
                    {formatCurrency(product.cost)}
                  </div>
                  <div className="text-muted-foreground">Stock</div>
                  <div
                    className={`font-semibold ${
                      isLowStock
                        ? "text-red-600 dark:text-red-400"
                        : "text-gray-900 dark:text-white"
                    }`}
                  >
                    {product.stock}
                    <span className="text-xs text-muted-foreground"> / mín. {product.minStock}</span>
                  </div>
                  {showBranchColumn && (
                    <>
                      <div className="text-muted-foreground flex items-center gap-1">
                        <Building2 className="h-4 w-4" />
                        Sucursal
                      </div>
                      <div className="font-medium text-gray-900 dark:text-white">
                        {product.branch?.name || "-"}
                      </div>
                    </>
                  )}
                </div>

                {description ? (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <p className="text-sm text-gray-600 dark:text-gray-300 line-clamp-3 cursor-help">
                        {truncateText(description)}
                      </p>
                    </TooltipTrigger>
                    <TooltipContent className="max-w-xs whitespace-pre-wrap">
                      {description}
                    </TooltipContent>
                  </Tooltip>
                ) : (
                  <p className="text-sm italic text-muted-foreground">Sin descripción</p>
                )}
              </CardContent>

              <CardFooter className="border-t border-dashed border-gray-200 pt-4 dark:border-[#2a2a2a]">
                <div className="flex w-full flex-wrap items-center justify-between gap-2">
                  <div className="flex items-center gap-2 text-xs text-muted-foreground">
                    <Sparkles className="h-4 w-4" />
                    <span>{product.category?.name || t('common.noCategory')}</span>
                  </div>
                  <div className="flex flex-1 justify-end gap-2">
                    {onView && (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button
                            variant="outline"
                            size="icon"
                            className="rounded-full"
                            onClick={() => onView(product)}
                            aria-label="Ver detalles"
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>Ver detalles</TooltipContent>
                      </Tooltip>
                    )}
                    {onEdit && (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button
                            variant="outline"
                            size="icon"
                            className="rounded-full"
                            onClick={() => onEdit(product)}
                            aria-label="Editar producto"
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>Editar producto</TooltipContent>
                      </Tooltip>
                    )}
                    {onToggleStatus && (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button
                            variant="outline"
                            size="icon"
                            className="rounded-full"
                            onClick={() => onToggleStatus(product)}
                            aria-label={isActive ? "Desactivar producto" : "Activar producto"}
                          >
                            {isActive ? (
                              <PowerOff className="h-4 w-4 text-orange-500" />
                            ) : (
                              <Power className="h-4 w-4 text-green-500" />
                            )}
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>
                          {isActive ? "Desactivar producto" : "Activar producto"}
                        </TooltipContent>
                      </Tooltip>
                    )}
                    {onDelete && (
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Button
                            variant="outline"
                            size="icon"
                            className="rounded-full text-red-600 hover:text-red-600"
                            onClick={() => onDelete(product)}
                            aria-label="Eliminar producto"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </TooltipTrigger>
                        <TooltipContent>Eliminar producto</TooltipContent>
                      </Tooltip>
                    )}
                  </div>
                </div>
              </CardFooter>
            </Card>
          )
        })}
      </div>
    </TooltipProvider>
  )
}

"use client";

import {
  Edit,
  Trash2,
  Power,
  PowerOff,
  Package,
  Building2,
  Eye,
} from "lucide-react";
import { useTranslations } from "next-intl";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { TableSkeleton } from "@/components/ui/table-skeleton";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { formatCurrencyWithPreferences } from "@/lib/utils/preferences";
import { getProductDescription } from "@/lib/utils/product-description";

// Función para truncar nombre manteniendo el nombre más corto disponible
function truncateProductName(name: string, maxLength: number = 40): string {
  if (name.length <= maxLength) {
    return name;
  }

  // Intentar encontrar un punto de corte más natural (espacio o guion)
  const truncated = name.substring(0, maxLength);
  const lastSpace = truncated.lastIndexOf(" ");
  const lastDash = truncated.lastIndexOf("-");
  const lastBreak = Math.max(lastSpace, lastDash);

  if (lastBreak > maxLength * 0.6) {
    // Si hay un punto de corte razonable (al menos 60% del maxLength)
    return truncated.substring(0, lastBreak) + "...";
  }

  return truncated + "...";
}

// Función para truncar texto por palabras
function truncateByWords(text: string, maxWords: number = 6): string {
  if (!text) return "";

  const words = text.trim().split(/\s+/);
  if (words.length <= maxWords) {
    return text;
  }

  return words.slice(0, maxWords).join(" ") + "...";
}

interface ProductWithRelations {
  id: string;
  name: string;
  brand?: string | null;
  model?: string | null;
  description?: string | null;
  descriptionTranslations?: any; // JSON con traducciones { es, en, pt }
  price: number;
  cost: number;
  stock: number;
  minStock: number;
  sku?: string | null;
  imageUrl?: string | null;
  isActive: boolean;
  category: { name: string } | null;
  branch: { name: string } | null;
}

interface ProductsTableProps {
  products: ProductWithRelations[];
  isLoading?: boolean;
  showBranchColumn?: boolean;
  onEditClick?: (product: ProductWithRelations) => void;
  onDeleteClick?: (product: ProductWithRelations) => void;
  onToggleStatus?: (product: ProductWithRelations) => void;
  onViewClick?: (product: ProductWithRelations) => void;
}

export function ProductsTable({
  products,
  isLoading,
  showBranchColumn = false,
  onEditClick,
  onDeleteClick,
  onToggleStatus,
  onViewClick,
}: ProductsTableProps) {
  const t = useTranslations();
  
  if (isLoading) {
    return (
      <TableSkeleton
        columns={showBranchColumn ? 11 : 10}
        rows={5}
        showActions={true}
      />
    );
  }

  return (
    <TooltipProvider>
      <div className="overflow-x-auto w-full">
        <Table>
          <TableHeader>
            <TableRow className="bg-gray-50 dark:bg-[#2a2a2a] border-b border-gray-200 dark:border-[#2a2a2a]">
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold w-[80px]">
                Imagen
              </TableHead>
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                Producto
              </TableHead>
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                Marca
              </TableHead>
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                Modelo
              </TableHead>
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                Descripción
              </TableHead>
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                Precio Venta
              </TableHead>
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                Precio Compra
              </TableHead>
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                Stock
              </TableHead>
              {showBranchColumn && (
                <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                  Sucursal
                </TableHead>
              )}
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold">
                Estado
              </TableHead>
              <TableHead className="text-gray-700 dark:text-gray-300 font-semibold text-right">
                Acciones
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {products.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={showBranchColumn ? 11 : 10}
                  className="text-center text-muted-foreground py-12"
                >
                  <div className="flex flex-col items-center gap-2">
                    <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-[#2a2a2a] flex items-center justify-center">
                      <Package className="h-8 w-8 text-gray-400" />
                    </div>
                    <p className="text-gray-500 dark:text-gray-400">
                      No hay productos registrados
                    </p>
                  </div>
                </TableCell>
              </TableRow>
            ) : (
              products.map((product) => {
                const isLowStock = product.stock <= product.minStock;
                const truncatedName = truncateProductName(product.name);
                const brand = product.brand?.trim() ?? "";
                const model = product.model?.trim() ?? "";
                // Obtener descripción según el idioma actual
                const currentLanguage = (() => {
                  try {
                    const prefs = JSON.parse(localStorage.getItem('sas_prefs') || '{}');
                    return prefs?.language || 'es';
                  } catch {
                    return 'es';
                  }
                })();
                const description = getProductDescription(
                  product.description,
                  product.descriptionTranslations,
                  currentLanguage
                )?.trim() ?? "";
                const hasDescription = description.length > 0;
                const truncatedDescription = hasDescription
                  ? truncateByWords(description, 6)
                  : "";
                const shouldShowDescriptionTooltip =
                  hasDescription && truncatedDescription !== description;

                return (
                  <TableRow
                    key={product.id}
                    className="hover:bg-gray-50 dark:hover:bg-[#2a2a2a] transition-colors border-b border-gray-100 dark:border-[#2a2a2a]"
                  >
                    <TableCell>
                      <div className="w-16 h-16 rounded-lg overflow-hidden bg-gray-100 dark:bg-[#2a2a2a] flex items-center justify-center relative">
                        {product.imageUrl ? (
                          <img
                            src={product.imageUrl}
                            alt={product.name}
                            className="object-cover w-full h-full"
                            onError={(e) => {
                              // Si la imagen falla al cargar, reemplazar con icono
                              const target = e.target as HTMLImageElement;
                              target.style.display = "none";
                              const fallback =
                                target.nextElementSibling as HTMLElement;
                              if (fallback) {
                                fallback.style.display = "flex";
                              }
                            }}
                          />
                        ) : null}
                        <div
                          className="absolute inset-0 flex items-center justify-center w-full h-full"
                          style={{
                            display: product.imageUrl ? "none" : "flex",
                          }}
                        >
                          <Package className="h-8 w-8 text-gray-400 dark:text-gray-500" />
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col py-2">
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <span className="font-semibold text-gray-900 dark:text-white cursor-help">
                              {truncatedName}
                            </span>
                          </TooltipTrigger>
                          {product.name.length > 40 && (
                            <TooltipContent>
                              <p className="max-w-xs">{product.name}</p>
                            </TooltipContent>
                          )}
                        </Tooltip>
                        {product.sku && (
                          <span className="text-xs text-gray-500 dark:text-gray-400">
                            SKU: {product.sku}
                          </span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm text-gray-700 dark:text-gray-300">
                        {brand || "-"}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm text-gray-700 dark:text-gray-300">
                        {model || "-"}
                      </span>
                    </TableCell>
                    <TableCell>
                      {hasDescription ? (
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <span className="text-sm text-gray-600 dark:text-gray-400 cursor-help">
                              {truncatedDescription}
                            </span>
                          </TooltipTrigger>
                          {shouldShowDescriptionTooltip && (
                            <TooltipContent>
                              <p className="max-w-xs whitespace-pre-wrap">
                                {description}
                              </p>
                            </TooltipContent>
                          )}
                        </Tooltip>
                      ) : (
                        <span className="text-sm text-gray-400 italic">
                          Sin descripción
                        </span>
                      )}
                    </TableCell>
                    <TableCell>
                      <span className="text-sm font-semibold text-gray-900 dark:text-white">
                        {formatCurrencyWithPreferences(Number(product.price))}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm text-gray-600 dark:text-gray-400">
                        {formatCurrencyWithPreferences(Number(product.cost))}
                      </span>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-semibold text-gray-900 dark:text-white">
                          {product.stock}
                        </span>
                        {product.stock === 0 ? (
                          <Badge className="rounded-full bg-red-500/10 text-red-600 dark:bg-red-500/20 dark:text-red-300 border border-red-500/40 px-2 py-1 text-[11px] uppercase tracking-wide">
                            Agotado
                          </Badge>
                        ) : isLowStock ? (
                          <Badge className="rounded-full bg-amber-500/10 text-amber-600 dark:bg-amber-500/20 dark:text-amber-300 border border-amber-500/40 px-2 py-1 text-[11px] uppercase tracking-wide">
                            Unidades
                          </Badge>
                        ) : null}
                      </div>
                    </TableCell>
                    {showBranchColumn && (
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Building2 className="h-4 w-4 text-gray-400" />
                          <span className="text-sm text-gray-700 dark:text-gray-300">
                            {product.branch?.name || "-"}
                          </span>
                        </div>
                      </TableCell>
                    )}
                    <TableCell>
                      <Badge
                        className={
                          product.isActive
                            ? "bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400 border-green-200 dark:border-green-800"
                            : "bg-gray-100 text-gray-700 dark:bg-gray-900/20 dark:text-gray-400 border-gray-200 dark:border-gray-800"
                        }
                      >
                        {product.isActive ? "Activo" : "Inactivo"}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        {onViewClick && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => onViewClick(product)}
                                className="hover:bg-blue-100 dark:hover:bg-blue-900/20 text-blue-600 dark:text-blue-400"
                              >
                                <Eye className="h-4 w-4" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent>Ver detalles</TooltipContent>
                          </Tooltip>
                        )}
                        {onEditClick && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => onEditClick(product)}
                                className="hover:bg-green-100 dark:hover:bg-green-900/20 text-green-600 dark:text-green-400"
                              >
                                <Edit className="h-4 w-4" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent>Editar producto</TooltipContent>
                          </Tooltip>
                        )}
                        {onToggleStatus && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => onToggleStatus(product)}
                                className={
                                  product.isActive
                                    ? "hover:bg-orange-100 dark:hover:bg-orange-900/20 text-orange-600 dark:text-orange-400"
                                    : "hover:bg-green-100 dark:hover:bg-green-900/20 text-green-600 dark:text-green-400"
                                }
                              >
                                {product.isActive ? (
                                  <PowerOff className="h-4 w-4" />
                                ) : (
                                  <Power className="h-4 w-4" />
                                )}
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent>
                              {product.isActive
                                ? "Desactivar producto"
                                : "Activar producto"}
                            </TooltipContent>
                          </Tooltip>
                        )}
                        {onDeleteClick && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => onDeleteClick(product)}
                                className="hover:bg-red-100 dark:hover:bg-red-900/20 text-red-600 dark:text-red-400"
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent>Eliminar producto</TooltipContent>
                          </Tooltip>
                        )}
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>
    </TooltipProvider>
  );
}

"use client";


import { BrowserMultiFormatReader } from "@zxing/library";
import { Plus, Trash2, QrCode } from "lucide-react";
import { useTranslations } from "next-intl";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

import { SalesQuotationWithRelations } from "./types";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

const paymentOptions = [
  { value: "cash", label: "Efectivo" },
  { value: "card", label: "Tarjeta" },
  { value: "transfer", label: "Transferencia" },
  { value: "qr", label: "QR / Billetera" },
];

interface ProductOption {
  id: string;
  name: string;
  price: number;
  stock: number;
}

interface LineItem {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  unitPrice: number;
  codes: string[];
}

const generateTempId = () =>
  typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID()
    : Math.random().toString(36).slice(2);

const EMPTY_PRODUCT_VALUE = "__none__";

import { formatDateWithPreferences, formatCurrencyWithPreferences } from "@/lib/utils/preferences"

const formatDate = (value?: string | Date | null) => {
  if (!value) return "--";
  return formatDateWithPreferences(value);
};

const formatCurrency = (value: unknown) => {
  const numValue = Number(value ?? 0);
  return formatCurrencyWithPreferences(numValue);
};

interface QuotationConvertDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  quotation?: SalesQuotationWithRelations;
  onConfirm: (payload: {
    paymentMethod: string;
    notes?: string | null;
    items: Array<{
      productId: string;
      productName?: string | null;
      quantity: number;
      unitPrice: number;
      subtotal: number;
    }>;
    discount: number;
  }) => void | Promise<void>;
  isSubmitting?: boolean;
  customerSlug: string;
  isAdmin?: boolean;
  selectedBranchId?: string | null;
  userBranchId?: string | null;
  maxBranches?: number | null;
}

export function QuotationConvertDialog({
  open,
  onOpenChange,
  quotation,
  onConfirm,
  isSubmitting = false,
  customerSlug,
  isAdmin = false,
  selectedBranchId,
  userBranchId,
  maxBranches,
}: QuotationConvertDialogProps) {
  const t = useTranslations();
  const [paymentMethod, setPaymentMethod] = useState<string>("cash");
  const [notes, setNotes] = useState<string>("");
  const [products, setProducts] = useState<ProductOption[]>([]);
  const [isLoadingProducts, setIsLoadingProducts] = useState(false);
  const [items, setItems] = useState<LineItem[]>([]);
  const [discountValue, setDiscountValue] = useState<number>(0);
  const [codeInputs, setCodeInputs] = useState<Record<string, string>>({});
  const [isScanning, setIsScanning] = useState(false);
  const [videoStream, setVideoStream] = useState<MediaStream | null>(null);
  const readerRef = useRef<BrowserMultiFormatReader | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const lastScannedCodeRef = useRef<string | null>(null);

  useEffect(() => {
    if (!open) return;
    setPaymentMethod("cash");
    setNotes(quotation?.notes ?? "");
    setDiscountValue(Number(quotation?.discount ?? 0));

    const initialItems: LineItem[] = (quotation?.items ?? []).map((item) => {
      const quantity = Number(item.quantity ?? 1) || 1;
      const unitPrice = Number(item.unitPrice ?? item.product?.price ?? 0);
      const initialProductId = item.productId ?? EMPTY_PRODUCT_VALUE;
      const rawTrackingCodes = (item as any)?.trackingCodes;
      return {
        id: generateTempId(),
        productId: initialProductId,
        productName: item.product?.name ?? item.productName ?? "",
        quantity,
        unitPrice,
        codes:
          initialProductId === EMPTY_PRODUCT_VALUE
            ? []
            : Array.isArray(rawTrackingCodes)
                ? (rawTrackingCodes as unknown[])
                    .filter((code): code is string => typeof code === "string")
                    .map((code) => code.trim())
                    .filter((code) => code.length > 0)
                : [],
      };
    });

    setItems(initialItems);
    const inputState: Record<string, string> = {};
    initialItems.forEach((item) => {
      inputState[item.id] = "";
    });
    setCodeInputs(inputState);
  }, [open, quotation]);

  const loadProducts = useCallback(
    async (branchId?: string | null) => {
      setIsLoadingProducts(true);
      try {
        const branchQuery = branchId ? `&branchId=${branchId}` : "";
        const response = await fetch(
          `/api/${customerSlug}/productos?page=1&pageSize=1000${branchQuery}`
        );
        if (!response.ok) return;
        const data = await response.json();
        const options: ProductOption[] = (data.products || []).map(
          (product: any) => ({
            id: product.id,
            name: product.name ?? "Producto sin nombre",
            price: Number(product.price ?? 0),
            stock: Number(product.stock ?? 0),
          })
        );
        setProducts(options);
      } catch (error) {
        console.error("Error al cargar productos:", error);
      } finally {
        setIsLoadingProducts(false);
      }
    },
    [customerSlug]
  );

  useEffect(() => {
    if (!open || products.length === 0) return;
    setItems((prev) =>
      prev.map((item) => {
        if (
          item.productId === EMPTY_PRODUCT_VALUE ||
          (item.productName && item.productName.length > 0)
        ) {
          return item;
        }
        const product = products.find((prod) => prod.id === item.productId);
        if (!product) return item;
        const unitPrice = item.unitPrice > 0 ? item.unitPrice : product.price;
        return {
          ...item,
          productName: product?.name ?? "",
          unitPrice,
          codes: product ? item.codes : [],
        };
      })
    );
  }, [open, products]);

  useEffect(() => {
    if (!open) return;

    const initialBranch = isAdmin
      ? selectedBranchId ?? null
      : userBranchId ?? null;

    loadProducts(initialBranch);

  }, [open, customerSlug, isAdmin, selectedBranchId, userBranchId, loadProducts]);

  useEffect(() => {
    if (!open || !isAdmin) return;
    const branchToLoad = selectedBranchId ?? null;
    loadProducts(branchToLoad);
  }, [open, isAdmin, selectedBranchId, loadProducts]);

  const subtotal = useMemo(
    () =>
      items.reduce((sum, item) => {
        if (item.productId === EMPTY_PRODUCT_VALUE) return sum;
        return sum + item.quantity * item.unitPrice;
      }, 0),
    [items]
  );

  const validItems = useMemo(
    () => items.filter((item) => item.productId !== EMPTY_PRODUCT_VALUE),
    [items]
  );

  const rawTotal = subtotal - discountValue;
  const total = rawTotal >= 0 ? rawTotal : 0;

  const hasMissingProducts = items.some(
    (item) => item.productId === EMPTY_PRODUCT_VALUE
  );
  const hasInvalidValues = items.some(
    (item) => item.quantity <= 0 || item.unitPrice < 0
  );
  const hasInvalidCodes = items.some(
    (item) => item.codes.length > 0 && item.codes.length !== item.quantity
  );
  const alreadyConverted = quotation?.status === "converted";
  const statusLabel = useMemo(() => {
    const raw = quotation?.status ?? "";
    if (raw === "converted") return "Vendida";
    if (raw === "active") return "Activa";
    if (raw === "expired") return "Vencida";
    return raw ? raw.charAt(0).toUpperCase() + raw.slice(1) : "";
  }, [quotation?.status]);

  const statusBadgeClass = useMemo(() => {
    switch (quotation?.status) {
      case "converted":
        return "bg-purple-600 text-white dark:bg-purple-400 dark:text-black";
      case "active":
        return "bg-emerald-500 text-white dark:bg-emerald-400 dark:text-black";
      case "expired":
        return "bg-red-500 text-white dark:bg-red-400 dark:text-black";
      default:
        return "bg-gray-900 text-white dark:bg-gray-100 dark:text-gray-900";
    }
  }, [quotation?.status]);

  const disableConfirm =
    isSubmitting ||
    alreadyConverted ||
    validItems.length === 0 ||
    hasMissingProducts ||
    hasInvalidValues ||
    hasInvalidCodes ||
    rawTotal < 0;

  const conversionWarning = useMemo(() => {
    if (alreadyConverted) return "Esta cotización ya fue convertida en venta.";
    if (validItems.length === 0)
      return "Agrega al menos un producto antes de convertir la cotización.";
    if (hasMissingProducts)
      return "Todos los productos deben estar asociados a un producto del catálogo para convertir la cotización.";
    if (hasInvalidValues)
      return "Verifica las cantidades y los precios de cada producto.";
    if (hasInvalidCodes)
      return "La cantidad de códigos debe coincidir con las unidades vendidas en cada producto.";
    if (rawTotal < 0)
      return "El total no puede ser negativo. Ajusta el descuento.";
    return null;
  }, [
    alreadyConverted,
    validItems.length,
    hasMissingProducts,
    hasInvalidValues,
    hasInvalidCodes,
    rawTotal,
  ]);

  const handleAddItem = useCallback(() => {
    const id = generateTempId();
    setItems((prev) => [
      ...prev,
      {
        id,
        productId: EMPTY_PRODUCT_VALUE,
        productName: "",
        quantity: 1,
        unitPrice: 0,
        codes: [],
      },
    ]);
    setCodeInputs((prev) => ({ ...prev, [id]: "" }));
  }, []);

  const handleRemoveItem = useCallback((itemId: string) => {
    setItems((prev) => prev.filter((item) => item.id !== itemId));
    setCodeInputs((prev) => {
      const clone = { ...prev };
      delete clone[itemId];
      return clone;
    });
  }, []);

  const handleProductChange = useCallback(
    (itemId: string, productId: string) => {
      const product = products.find((prod) => prod.id === productId);
      setItems((prev) =>
        prev.map((item) =>
          item.id === itemId
            ? {
                ...item,
                productId: product ? product.id : EMPTY_PRODUCT_VALUE,
                productName: product?.name ?? "",
                unitPrice: product?.price ?? 0,
                codes: product ? item.codes : [],
              }
            : item
        )
      );
      if (!product) {
        setCodeInputs((prev) => ({ ...prev, [itemId]: "" }));
      }
    },
    [products]
  );

  const handleQuantityChange = useCallback(
    (itemId: string, quantity: number) => {
      const normalized = Number.isFinite(quantity) ? quantity : 0;
      setItems((prev) =>
        prev.map((item) =>
          item.id === itemId
            ? { ...item, quantity: Math.max(0, normalized) }
            : item
        )
      );
    },
    []
  );

  const handleUnitPriceChange = useCallback(
    (itemId: string, unitPrice: number) => {
      const normalized = Number.isFinite(unitPrice) ? unitPrice : 0;
      setItems((prev) =>
        prev.map((item) =>
          item.id === itemId
            ? { ...item, unitPrice: Math.max(0, normalized) }
            : item
        )
      );
    },
    []
  );

  const stopScanning = useCallback(() => {
    readerRef.current?.reset();
    setIsScanning(false);
    if (videoStream) {
      videoStream.getTracks().forEach((track) => track.stop());
    }
    setVideoStream(null);
    lastScannedCodeRef.current = null;
  }, [readerRef, videoStream]);

  const addCodeToItem = useCallback((itemId: string, value: string) => {
    const code = value.trim();
    if (!code) return;
    setItems((prev) =>
      prev.map((item) => {
        if (item.id !== itemId) return item;
        if (item.codes.includes(code)) {
          toast.info(t('sales.form.codeAlreadyAdded'));
          return item;
        }
        if (item.codes.length >= item.quantity) {
          toast.error(t('sales.form.codesExceedQuantity'));
          return item;
        }
        return {
          ...item,
          codes: [...item.codes, code],
        };
      })
    );
    setCodeInputs((prev) => ({ ...prev, [itemId]: "" }));
  }, []);

  const removeCodeFromItem = useCallback((itemId: string, code: string) => {
    setItems((prev) =>
      prev.map((item) =>
        item.id === itemId
          ? {
              ...item,
              codes: item.codes.filter((existing) => existing !== code),
            }
          : item
      )
    );
  }, []);

  const handleManualCodeAdd = useCallback(
    (itemId: string) => {
      const value = codeInputs[itemId] ?? "";
      addCodeToItem(itemId, value);
    },
    [addCodeToItem, codeInputs]
  );

  const canAddCodes = useCallback(
    (item: LineItem) =>
      item.productId !== EMPTY_PRODUCT_VALUE &&
      item.quantity > 0 &&
      item.codes.length < item.quantity,
    []
  );

  const startScanning = useCallback(
    async (itemId: string) => {
      const targetItem = items.find((item) => item.id === itemId);
      if (!targetItem || !canAddCodes(targetItem)) return;
      try {
        stopScanning();
        const reader = new BrowserMultiFormatReader();
        readerRef.current = reader;
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "environment" },
        });
        readerRef.current = reader;
        setIsScanning(true);
        setVideoStream(stream);
        await new Promise((resolve) => setTimeout(resolve, 100));
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute("playsinline", "true");
          videoRef.current.setAttribute("muted", "true");
          await videoRef.current.play();
        }
        lastScannedCodeRef.current = null;
        reader.decodeFromVideoDevice(
          null,
          videoRef.current as HTMLVideoElement,
          (result, err) => {
            if (result) {
              const code = result.getText();
              if (lastScannedCodeRef.current === code) return;
              lastScannedCodeRef.current = code;
              addCodeToItem(itemId, code);
              toast.success(t('sales.form.codeScannedAndAdded'));
              stopScanning();
            }
            if (err && !(err as any).closed) {
              // Silenciar errores de lectura
            }
          }
        );
      } catch (error) {
        console.error("Error al acceder a la cámara", error);
        toast.error(t('common.cameraError'));
        stopScanning();
      }
    },
    [
      addCodeToItem,
      canAddCodes,
      items,
      lastScannedCodeRef,
      readerRef,
      stopScanning,
    ]
  );

  useEffect(() => {
    if (!open) {
      stopScanning();
    }
  }, [open, stopScanning]);

  const handleDiscountChange = (value: number) => {
    if (!Number.isFinite(value) || value < 0) {
      setDiscountValue(0);
      return;
    }
    setDiscountValue(value);
  };

  const handleConfirm = () => {
    if (disableConfirm) return;
    const saleItems = validItems.map((item) => ({
      productId: item.productId,
      productName: item.productName,
      quantity: item.quantity,
      unitPrice: item.unitPrice,
      subtotal: item.quantity * item.unitPrice,
      trackingCodes: item.codes,
    }));

    if (saleItems.length === 0) return;

    void onConfirm({
      paymentMethod,
      notes: notes.trim().length > 0 ? notes.trim() : null,
      items: saleItems,
      discount: discountValue,
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-3xl max-h-[92vh] flex flex-col overflow-hidden p-0">
        <DialogHeader className="px-6 py-5 border-b border-gray-200 dark:border-gray-800 bg-white/95 dark:bg-[#111111]/95 backdrop-blur">
          <DialogTitle className="text-lg font-semibold text-gray-900 dark:text-white">
            Convertir cotización a venta
          </DialogTitle>
          <DialogDescription className="text-sm text-gray-600 dark:text-gray-400">
            Revisa los datos de la cotización y selecciona el método de pago
            para generar la venta.
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col flex-1 min-h-0">
          <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6 bg-gray-50/60 dark:bg-[#0c0c0c]">
            <div className="space-y-6">
              <div className={`grid gap-4 ${maxBranches !== undefined && maxBranches !== null && maxBranches > 1 ? 'md:grid-cols-3' : 'md:grid-cols-2'}`}>
                <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] p-4 bg-gray-50 dark:bg-[#111]">
                  <div className="flex items-center justify-between">
                    <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                      Cotización
                    </p>
                    {statusLabel && (
                      <Badge
                        className={`rounded-full text-xs  ${statusBadgeClass}`}
                      >
                        {statusLabel}
                      </Badge>
                    )}
                  </div>
                  <p className="mt-2 text-base font-semibold text-gray-900 dark:text-white">
                    {quotation?.quotationNumber ?? "--"}
                  </p>
                  <div className="mt-3 space-y-1 text-xs text-gray-500 dark:text-gray-400">
                    <p>Emitida: {formatDate(quotation?.createdAt)}</p>
                    <p>Vence: {formatDate(quotation?.expiresAt)}</p>
                  </div>
                </div>
                {/* Card combinado de Cliente y Sucursal en móvil, separados en desktop */}
                <div className={`${maxBranches !== undefined && maxBranches !== null && maxBranches > 1 ? 'md:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-4' : ''}`}>
                  <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] p-4 bg-gray-50 dark:bg-[#111]">
                    <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                      Cliente
                    </p>
                    <p className="mt-2 text-base font-semibold text-gray-900 dark:text-white">
                      {(() => {
                        if (!quotation) return "--";
                        const fullName = `${quotation.customer?.name ?? ""} ${
                          quotation.customer?.lastName ?? ""
                        }`.trim();
                        return (
                          fullName ||
                          quotation.customerName ||
                          "Cliente sin registrar"
                        );
                      })()}
                    </p>
                    <div className="mt-3 space-y-1 text-xs text-gray-500 dark:text-gray-400">
                      {quotation?.customerPhone && (
                        <p>Teléfono: {quotation.customerPhone}</p>
                      )}
                      {quotation?.customer?.email && (
                        <p>Correo: {quotation.customer.email}</p>
                      )}
                    </div>
                    {/* Mostrar sucursal en el mismo card en móvil si maxBranches > 1 */}
                    {maxBranches !== undefined && maxBranches !== null && maxBranches > 1 && (
                      <div className="mt-4 pt-4 border-t border-gray-200 dark:border-[#2a2a2a] md:hidden">
                        <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                          Sucursal
                        </p>
                        <p className="mt-2 text-base font-semibold text-gray-900 dark:text-white">
                          {quotation?.branch?.name ?? t('common.noBranch')}
                        </p>
                        {quotation?.branch?.address && (
                          <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                            {quotation.branch.address}
                          </p>
                        )}
                      </div>
                    )}
                  </div>
                  {/* Card de Sucursal solo en desktop si maxBranches > 1 */}
                  {maxBranches !== undefined && maxBranches !== null && maxBranches > 1 && (
                    <div className="hidden md:block rounded-2xl border border-gray-200 dark:border-[#2a2a2a] p-4 bg-gray-50 dark:bg-[#111]">
                      <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                        Sucursal
                      </p>
                      <p className="mt-2 text-base font-semibold text-gray-900 dark:text-white">
                        {quotation?.branch?.name ?? t('common.noBranch')}
                      </p>
                      {quotation?.branch?.address && (
                        <p className="mt-3 text-xs text-gray-500 dark:text-gray-400">
                          {quotation.branch.address}
                        </p>
                      )}
                    </div>
                  )}
                </div>
              </div>

              <div className="space-y-3">
                {items.length > 0 ? (
                  <div className="space-y-3">
                    {items.map((item, index) => {
                      const subtotalItem = item.quantity * item.unitPrice;
                      return (
                        <div
                          key={item.id}
                          className="rounded-3xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#0d0d0d] p-4 space-y-3"
                        >
                          <div className="grid gap-3 md:grid-cols-[1.5fr_1fr_1fr_auto]">
                            <div className="space-y-2 w-full md:w-auto">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Producto {index + 1}
                              </Label>
                              <Select
                                value={
                                  item.productId === EMPTY_PRODUCT_VALUE
                                    ? EMPTY_PRODUCT_VALUE
                                    : item.productId
                                }
                                onValueChange={(value) =>
                                  handleProductChange(item.id, value)
                                }
                                disabled={isLoadingProducts}
                              >
                                <SelectTrigger className="rounded-2xl w-full">
                                  <SelectValue
                                    placeholder={
                                      item.productName ||
                                      "Selecciona un producto"
                                    }
                                  />
                                </SelectTrigger>
                                <SelectContent className="rounded-2xl">
                                  <SelectItem value={EMPTY_PRODUCT_VALUE}>
                                    Selecciona un producto
                                  </SelectItem>
                                  {products.map((product) => (
                                    <SelectItem
                                      key={product.id}
                                      value={product.id}
                                    >
                                      {product.name}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                            </div>
                            {/* Cantidad y Precio: combinados en móvil, separados en desktop */}
                            <div className="space-y-2 md:hidden">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Cantidad / Precio U.
                              </Label>
                              <div className="flex gap-2">
                                <Input
                                  type="number"
                                  min={1}
                                  value={item.quantity}
                                  onChange={(event) =>
                                    handleQuantityChange(
                                      item.id,
                                      Number(event.target.value)
                                    )
                                  }
                                  className={`flex-1 rounded-2xl ${(() => {
                                    const product = products.find((prod) => prod.id === item.productId)
                                    return product && item.quantity > product.stock ? 'border border-red-500 text-red-600' : ''
                                  })()}`}
                                  placeholder={t('common.placeholders.quantity')}
                                />
                                <Input
                                  type="number"
                                  min={0}
                                  step="0.01"
                                  value={item.unitPrice}
                                  onChange={(event) =>
                                    handleUnitPriceChange(
                                      item.id,
                                      Number(event.target.value)
                                    )
                                  }
                                  className="flex-1 rounded-2xl"
                                  placeholder={t('common.placeholders.price')}
                                />
                              </div>
                            </div>
                            <div className="hidden md:block space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Cantidad
                              </Label>
                              <Input
                                type="number"
                                min={1}
                                value={item.quantity}
                                onChange={(event) =>
                                  handleQuantityChange(
                                    item.id,
                                    Number(event.target.value)
                                  )
                                }
                                className={`rounded-2xl ${(() => {
                                  const product = products.find((prod) => prod.id === item.productId)
                                  return product && item.quantity > product.stock ? 'border border-red-500 text-red-600' : ''
                                })()}`}
                              />
                            </div>
                            <div className="hidden md:block space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Precio U.
                              </Label>
                              <Input
                                type="number"
                                min={0}
                                step="0.01"
                                value={item.unitPrice}
                                onChange={(event) =>
                                  handleUnitPriceChange(
                                    item.id,
                                    Number(event.target.value)
                                  )
                                }
                                className="rounded-2xl"
                              />
                            </div>
                            <div className="space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Subtotal
                              </Label>
                              <div className="flex items-center gap-3">
                                <Input
                                  type="text"
                                  readOnly
                                  value={formatCurrency(subtotalItem)}
                                  className="flex-[3] rounded-2xl bg-gray-100 dark:bg-[#1a1a1a] text-right font-semibold"
                                />
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="icon"
                                  className="flex-[1] rounded-full text-red-500 hover:bg-red-500/10"
                                  onClick={() => handleRemoveItem(item.id)}
                                  disabled={items.length === 1}
                                >
                                  <Trash2 className="h-4 w-4" />
                                </Button>
                              </div>
                            </div>
                          </div>

                          <div className="grid gap-3 md:grid-cols-[1.5fr_auto] md:items-end">
                            <div className="space-y-2">
                              <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                                Códigos únicos
                              </Label>
                              <Input
                                placeholder={t('common.placeholders.barcodeOrSerial')}
                                value={codeInputs[item.id] ?? ""}
                                onChange={(event) =>
                                  setCodeInputs((prev) => ({
                                    ...prev,
                                    [item.id]: event.target.value,
                                  }))
                                }
                                className="rounded-2xl"
                                disabled={!canAddCodes(item)}
                              />
                            </div>
                            <div className="flex flex-wrap items-end gap-2">
                              <Button
                                type="button"
                                variant="outline"
                                className="rounded-full"
                                onClick={() => handleManualCodeAdd(item.id)}
                                disabled={!canAddCodes(item)}
                              >
                                Agregar
                              </Button>
                              <Button
                                type="button"
                                variant="outline"
                                className="rounded-full"
                                onClick={() => startScanning(item.id)}
                                disabled={!canAddCodes(item)}
                              >
                                <QrCode className="h-4 w-4" />
                                Escanear
                              </Button>
                            </div>
                          </div>

                          <div className="space-y-2">
                            {item.codes.length > 0 && (
                              <div className="flex flex-wrap gap-2">
                                {item.codes.map((code) => (
                                  <span
                                    key={`${item.id}-${code}`}
                                    className="inline-flex items-center gap-1 rounded-full border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#0d0d0d] px-3 py-1 text-xs text-gray-600 dark:text-gray-300"
                                  >
                                    #{code}
                                    <button
                                      type="button"
                                      onClick={() =>
                                        removeCodeFromItem(item.id, code)
                                      }
                                      className="ml-1 text-gray-500 hover:text-rose-500 dark:text-gray-400 dark:hover:text-rose-400"
                                    >
                                      <Trash2 className="h-3 w-3" />
                                    </button>
                                  </span>
                                ))}
                              </div>
                            )}
                            {item.codes.length === 0 && (
                              <p className="text-xs text-gray-500 dark:text-gray-400">
                                Sin códigos registrados.
                              </p>
                            )}
                            {item.codes.length > 0 &&
                              item.codes.length < item.quantity && (
                                <p className="text-xs text-amber-600 dark:text-amber-400">
                                  Faltan {item.quantity - item.codes.length}{" "}
                                  códigos para coincidir con la cantidad
                                  vendida.
                                </p>
                              )}
                            {item.codes.length >= item.quantity &&
                              item.quantity > 0 && (
                                <p className="text-xs text-emerald-600 dark:text-emerald-400">
                                  Códigos completos para este producto.
                                </p>
                              )}
                            {(() => {
                              const product = products.find((prod) => prod.id === item.productId)
                              if (product && item.quantity > product.stock) {
                                return (
                                  <p className="text-xs text-red-500">
                                    Stock disponible: {product.stock}
                                  </p>
                                )
                              }
                              if (product) {
                                return (
                                  <p className="text-xs text-gray-500 dark:text-gray-400">
                                    Stock disponible: {product.stock}
                                  </p>
                                )
                              }
                              return null
                            })()}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    No hay productos registrados. Agrega al menos uno para
                    continuar.
                  </p>
                )}
                <div className="flex justify-center">
                  <Button
                    type="button"
                    variant="outline"
                    className="rounded-full"
                    onClick={handleAddItem}
                    disabled={isLoadingProducts || products.length === 0}
                  >
                    <Plus className="h-4 w-4" />
                    Agregar producto
                  </Button>
                </div>
              </div>
            </div>

            <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-gray-50 dark:bg-[#111] p-5">
              <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                Resumen
              </p>
              <div className="mt-4 space-y-4">
                <div className="flex flex-col gap-3 md:flex-row md:items-end md:gap-4">
                  {/* Subtotal y Descuento: combinados en móvil, separados en desktop */}
                  <div className="space-y-2 md:hidden">
                    <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                      Subtotal / Descuento
                    </Label>
                    <div className="flex gap-2">
                      <Input
                        type="text"
                        readOnly
                        value={formatCurrency(subtotal)}
                        className="flex-1 rounded-2xl bg-gray-100 dark:bg-[#1a1a1a] text-left font-semibold"
                        placeholder={t('common.placeholders.subtotal')}
                      />
                      <Input
                        type="number"
                        min={0}
                        step="0.01"
                        value={discountValue}
                        onChange={(event) =>
                          handleDiscountChange(Number(event.target.value))
                        }
                        className="flex-1 rounded-2xl"
                        placeholder={t('common.placeholders.discount')}
                      />
                    </div>
                  </div>
                  <div className="hidden md:block space-y-2 md:flex-1">
                    <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                      Subtotal
                    </Label>
                    <Input
                      type="text"
                      readOnly
                      value={formatCurrency(subtotal)}
                      className="w-full rounded-2xl bg-gray-100 dark:bg-[#1a1a1a] text-left font-semibold"
                    />
                  </div>
                  <div className="hidden md:block space-y-2 md:flex-1">
                    <Label className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                      Descuento
                    </Label>
                    <Input
                      type="number"
                      min={0}
                      step="0.01"
                      value={discountValue}
                      onChange={(event) =>
                        handleDiscountChange(Number(event.target.value))
                      }
                      className="w-full rounded-2xl"
                    />
                  </div>
                  <div className="space-y-2 md:flex-1">
                    <Label
                      htmlFor="quotation-payment-method"
                      className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400"
                    >
                      Método de pago
                    </Label>
                    <Select
                      value={paymentMethod}
                      onValueChange={setPaymentMethod}
                      disabled={alreadyConverted}
                    >
                      <SelectTrigger
                        id="quotation-payment-method"
                        className="w-full rounded-2xl"
                      >
                        <SelectValue placeholder={t('common.placeholders.selectPaymentMethod')} />
                      </SelectTrigger>
                      <SelectContent>
                        {paymentOptions.map((option) => (
                          <SelectItem key={option.value} value={option.value}>
                            {option.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>
                <div className="flex items-center justify-between rounded-xl bg-black dark:bg-white px-4 py-3 text-sm text-white dark:text-black">
                  <span>Total</span>
                  <span className="text-lg font-semibold">
                    {formatCurrency(total)}
                  </span>
                </div>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="quotation-convert-notes">
                Notas para la venta
              </Label>
              <Textarea
                id="quotation-convert-notes"
                placeholder={t('common.placeholders.additionalNotes')}
                className="h-28 w-full rounded-2xl"
                value={notes}
                onChange={(event) => setNotes(event.target.value)}
                disabled={isSubmitting}
              />
            </div>

            {conversionWarning && (
              <div className="rounded-xl border border-amber-400/40 bg-amber-50/80 px-4 py-3 text-sm text-amber-800 dark:border-amber-500/40 dark:bg-amber-500/10 dark:text-amber-200">
                {conversionWarning}
              </div>
            )}
          </div>
        </div>

        <DialogFooter className="flex w-full flex-col sm:flex-row sm:items-center sm:justify-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur">
          <Button
            variant="outline"
            className="w-full sm:w-auto rounded-full border border-gray-200 bg-white text-gray-700 hover:bg-gray-100 dark:border-[#2a2a2a] dark:bg-[#1a1a1a] dark:text-gray-200 dark:hover:bg-[#222]"
            onClick={() => onOpenChange(false)}
            disabled={isSubmitting}
          >
            Cancelar
          </Button>
          <Button
            variant="new"
            className="rounded-full w-full sm:w-auto"
            onClick={handleConfirm}
            disabled={disableConfirm}
          >
            {isSubmitting ? "Convirtiendo..." : "Convertir a venta"}
          </Button>
        </DialogFooter>

        {isScanning && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center">
            <div
              className="absolute inset-0 bg-black/70"
              onClick={stopScanning}
            />
            <div className="relative z-[121] flex flex-col items-center gap-4">
              <video
                ref={videoRef}
                className="w-72 h-72 rounded-3xl border-4 border-white object-cover shadow-2xl"
                autoPlay
                muted
                playsInline
              />
              <Button
                type="button"
                variant="secondary"
                className="rounded-full"
                onClick={stopScanning}
              >
                Detener escaneo
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";


import jsPDF from "jspdf";
import { MessageCircle } from "lucide-react";
import { useTranslations } from "next-intl";
import { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

import { SalesQuotationWithRelations } from "@/components/sales/quotation/types";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { cn } from "@/lib/utils";
import {
  formatCurrencyWithPreferences,
  formatDateWithPreferences,
  invalidateConfigCache,
} from "@/lib/utils/preferences";
import { getTranslatableText } from "@/lib/utils/translatable-text";

// Formato de fecha con hora (para mostrar en UI)
// Esta función se usa dentro del componente donde tenemos acceso a dateFormat y customerSlug
const createFormatDateTime = (dateFormat: string, customerSlug: string) => {
  return (date?: string | Date | null) => {
    if (!date) return "—";
    const d = new Date(date);
    // Usar formato de preferencia para la fecha, luego agregar hora
    const datePart = formatDateWithPreferences(d, customerSlug);
    const hours = String(d.getHours()).padStart(2, "0");
    const minutes = String(d.getMinutes()).padStart(2, "0");
    return `${datePart}, ${hours}:${minutes}`;
  };
};

const statusTokens: Record<string, { label: string; className: string }> = {
  active: {
    label: "Activa",
    className:
      "bg-green-100 text-green-700 dark:bg-green-900/20 dark:text-green-400 border-green-200 dark:border-green-800",
  },
  expired: {
    label: "Vencida",
    className:
      "bg-red-100 text-red-700 dark:bg-red-900/20 dark:text-red-400 border-red-200 dark:border-red-800",
  },
  converted: {
    label: "Convertida",
    className:
      "bg-blue-100 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400 border-blue-200 dark:border-blue-800",
  },
  pending: {
    label: "Pendiente",
    className:
      "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-300 border-yellow-200 dark:border-yellow-800",
  },
  approved: {
    label: "Aprobada",
    className:
      "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800",
  },
  rejected: {
    label: "Rechazada",
    className:
      "bg-gray-200 text-gray-700 dark:bg-gray-900/20 dark:text-gray-400 border-gray-200 dark:border-gray-800",
  },
};

const DEFAULT_CURRENCY = "BOB";

interface QuotationDetailsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  quotation?: SalesQuotationWithRelations;
  customerSlug: string;
  maxBranches?: number | null;
}

export function QuotationDetailsDialog({
  open,
  onOpenChange,
  quotation,
  customerSlug,
  maxBranches,
}: QuotationDetailsDialogProps) {
  const t = useTranslations()
  const [isExporting, setIsExporting] = useState(false);
  const [shareUrl, setShareUrl] = useState<string | null>(null);
  const [companyWhatsappNumber, setCompanyWhatsappNumber] =
    useState<string>("");
  const [companyName, setCompanyName] = useState<string>("");
  const [_companyContactName, _setCompanyContactName] = useState<string>("");
  const [_companyEmail, _setCompanyEmail] = useState<string>("");
  const [companyPhone, setCompanyPhone] = useState<string>("");
  const [companyAddress, setCompanyAddress] = useState<string>("");
  const [companyWebsite, setCompanyWebsite] = useState<string>("");
  const [companyNIT, setCompanyNIT] = useState<string>("");
  const [companyLogo, setCompanyLogo] = useState<string>("");
  const [ownerName, setOwnerName] = useState<string>("");
  const [currencyCode, setCurrencyCode] = useState<string>(DEFAULT_CURRENCY);
  const [dateFormat, setDateFormat] = useState<string>("dd/MM/yyyy");
  const [themeColor, setThemeColor] = useState<string>("green");
  const [showBranchInfo, setShowBranchInfo] = useState<boolean>(true);

  // Función de formateo de fecha con hora usando las preferencias
  const formatDateTime = useMemo(
    () => createFormatDateTime(dateFormat, customerSlug),
    [dateFormat, customerSlug]
  );

  const statusToken = useMemo(() => {
    if (!quotation) return statusTokens["active"];
    return (
      statusTokens[quotation.status] ?? {
        label: quotation.status,
        className: "bg-gray-100 text-gray-700",
      }
    );
  }, [quotation]);

  const formatCurrency = useCallback(
    (value: number) => {
      // Usar la moneda cargada desde la API, o la del sistema si no está disponible
      // Invalidar caché para asegurar que use la moneda más reciente
      invalidateConfigCache(customerSlug);
      return formatCurrencyWithPreferences(value, customerSlug, currencyCode);
    },
    [currencyCode, customerSlug]
  );

  // Formatear sin símbolo de moneda (solo números)
  const formatCurrencyWithoutSymbol = useCallback((value: number) => {
    const numAmount = typeof value === "string" ? parseFloat(value) : value;
    // Formatear solo el número sin símbolo de moneda
    return new Intl.NumberFormat("es-BO", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(numAmount);
  }, []);

  const customerName = useMemo(() => {
    if (!quotation) return "—";
    if (quotation.customer) {
      const fullName = `${quotation.customer.name ?? ""} ${
        quotation.customer.lastName ?? ""
      }`.trim();
      return (
        fullName ||
        quotation.customer.email ||
        quotation.customerName ||
        "Cliente sin registrar"
      );
    }
    return quotation.customerName || "Cliente sin registrar";
  }, [quotation]);

  const customerPhone = useMemo(() => {
    if (!quotation) return "";
    const base = quotation.customer?.phone || quotation.customerPhone || "";
    const digits = base.replace(/[^0-9]/g, "");
    if (!digits) return "";
    const prefixed = base.startsWith("+") ? base : `+${digits}`;
    return prefixed;
  }, [quotation]);

  const items = useMemo(() => quotation?.items ?? [], [quotation?.items]);
  const subtotal = Number(quotation?.subtotal ?? 0);
  const discount = Number(quotation?.discount ?? 0);
  const total = Number(quotation?.total ?? 0);

  useEffect(() => {
    if (!open) {
      setShareUrl(null);
    }
  }, [open]);

  useEffect(() => {
    setShareUrl(null);
  }, [quotation?.id]);

  const handleOpenShareUrl = useCallback(() => {
    if (!shareUrl) return;
    if (typeof window !== "undefined") {
      window.open(shareUrl, "_blank", "noopener,noreferrer");
    }
  }, [shareUrl]);

  useEffect(() => {
    // Determinar si mostrar información de sucursal basado en maxBranches
    setShowBranchInfo(
      maxBranches === undefined || maxBranches === null || maxBranches > 1
    );
  }, [maxBranches]);

  useEffect(() => {
    if (typeof document === "undefined" || !open) return;

    // Cargar preferencias (moneda y formato de fecha) desde la API cuando se abre el modal
    const loadPreferences = async () => {
      try {
        const response = await fetch(
          `/api/${customerSlug}/config/preferencias`,
          {
            credentials: "include",
          }
        );
        if (response.ok) {
          const data = await response.json();
          if (data?.success && data.configuration) {
            if (data.configuration.currency) {
              setCurrencyCode(data.configuration.currency);
            } else {
              setCurrencyCode(DEFAULT_CURRENCY);
            }
            if (data.configuration.dateFormat) {
              setDateFormat(data.configuration.dateFormat);
            } else {
              setDateFormat("dd/MM/yyyy");
            }
            if (data.configuration.themeColor) {
              setThemeColor(data.configuration.themeColor);
            } else {
              setThemeColor("green");
            }
          } else {
            setCurrencyCode(DEFAULT_CURRENCY);
            setDateFormat("dd/MM/yyyy");
            setThemeColor("green");
          }
        } else {
          setCurrencyCode(DEFAULT_CURRENCY);
          setDateFormat("dd/MM/yyyy");
          setThemeColor("green");
        }
      } catch {
        setCurrencyCode(DEFAULT_CURRENCY);
        setDateFormat("dd/MM/yyyy");
        setThemeColor("green");
      }
    };

    loadPreferences();
  }, [open, customerSlug]);

  useEffect(() => {
    if (typeof document === "undefined" || !open) return;

    // Cargar información de empresa desde la API de organización
    const loadOrganizationInfo = async () => {
      try {
        const response = await fetch(`/api/${customerSlug}/organizacion`, {
          credentials: "include",
        });

        if (response.ok) {
          const data = await response.json();
          if (data.success && data.organization) {
            const org = data.organization;
            // Usar razonSocial si existe, sino usar name
            setCompanyName(org.razonSocial || org.name || "");
            setCompanyAddress(org.address || "");
            setCompanyPhone(org.phone || "");
            setCompanyWebsite(org.website || "");
            setCompanyNIT(org.nit || "");
            setCompanyLogo(org.logoUrl || "");
            setOwnerName(org.ownerName || "");
            // Extraer número de WhatsApp del teléfono si tiene código de país
            if (org.phone) {
              const phoneDigits = org.phone.replace(/\D/g, "");
              if (phoneDigits) {
                setCompanyWhatsappNumber(
                  org.phone.startsWith("+") ? org.phone : `+${phoneDigits}`
                );
              }
            }
          }
        }
      } catch (error) {
        console.error("Error cargando información de organización:", error);
      }
    };

    loadOrganizationInfo();
  }, [customerSlug, open]);

  const fetchImageAsDataUrl = useCallback(
    async (url: string): Promise<string | null> => {
      if (!url) return null;
      try {
        const response = await fetch(url);
        if (!response.ok) return null;
        const blob = await response.blob();
        return await new Promise<string | null>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.onerror = () =>
            reject(new Error("No se pudo cargar la imagen"));
          reader.readAsDataURL(blob);
        });
      } catch (error) {
        console.error("No se pudo cargar el logo para el PDF:", error);
        return null;
      }
    },
    []
  );

  const handleExportPdf = useCallback(async () => {
    if (!quotation) return;

    if (shareUrl) {
      handleOpenShareUrl();
      toast.success(t('quotations.form.pdf.openingExisting'));
      return;
    }

    try {
      setIsExporting(true);
      setShareUrl(null);

      // Mapeo de colores del tema a RGB
      const themeColorMap: Record<string, { r: number; g: number; b: number }> =
        {
          green: { r: 26, g: 120, b: 102 },
          blue: { r: 37, g: 99, b: 235 },
          purple: { r: 147, g: 51, b: 234 },
          orange: { r: 249, g: 115, b: 22 },
          red: { r: 220, g: 38, b: 38 },
          pink: { r: 236, g: 72, b: 153 },
          teal: { r: 20, g: 184, b: 166 },
          cyan: { r: 6, g: 182, b: 212 },
          indigo: { r: 99, g: 102, b: 241 },
          yellow: { r: 234, g: 179, b: 8 },
          emerald: { r: 16, g: 185, b: 129 },
          rose: { r: 225, g: 29, b: 72 },
        };

      // Obtener color RGB del tema configurado desde las preferencias
      const primaryColor = themeColorMap[themeColor] || themeColorMap.green;
      const doc = new jsPDF({ unit: "mm", format: "a4" });
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const margin = 16;

      let cursorY = margin + 6;

      const logoDataUrl = companyLogo
        ? await fetchImageAsDataUrl(companyLogo)
        : null;

      const headerTitleY = margin;
      doc.setFont("helvetica", "bold");
      doc.setFontSize(18);
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b);
      doc.text("Detalle de Cotización", pageWidth / 2, headerTitleY, {
        align: "center",
      });

      const maxLogoHeight = 32;
      const logoX = pageWidth - margin - maxLogoHeight;
      let contactBlockTop = headerTitleY + 8;
      if (logoDataUrl) {
        doc.addImage(
          logoDataUrl,
          "PNG",
          logoX,
          headerTitleY - 6,
          maxLogoHeight,
          maxLogoHeight,
          undefined,
          "FAST"
        );
        contactBlockTop = headerTitleY - 6 + maxLogoHeight + 6;
      }

      const headerLeftX = margin;
      let headerLeftY = headerTitleY + 8;
      doc.setFont("helvetica", "bold");
      doc.setFontSize(13);
      doc.setTextColor(30, 30, 30);
      doc.text(companyName || "Nombre de la empresa", headerLeftX, headerLeftY);
      headerLeftY += 5;

      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(60, 60, 60);
      if (companyNIT) {
        doc.text(`NIT: ${companyNIT}`, headerLeftX, headerLeftY);
        headerLeftY += 5;
      }
      if (companyAddress) {
        doc.text(companyAddress, headerLeftX, headerLeftY);
        headerLeftY += 5;
      }
      if (companyWebsite) {
        // Remover https:// o http:// para mostrar solo el dominio
        const websiteDisplay = companyWebsite.replace(/^https?:\/\//, "");
        doc.text(`Web: ${websiteDisplay}`, headerLeftX, headerLeftY);
        headerLeftY += 5;
      }
      // Email no está disponible en la organización, se omite
      const formattedNow = formatDateTime(new Date());
      doc.setFont("helvetica", "bold");
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b);
      doc.text("Fecha y Hora :", headerLeftX, headerLeftY);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(60, 60, 60);
      doc.text(formattedNow, headerLeftX + 30, headerLeftY);
      headerLeftY += 8;

      const contactName = ownerName || companyName || "—";
      const contactPhone = companyPhone || companyWhatsappNumber || "—";
      let contactY = contactBlockTop;
      doc.setFont("helvetica", "bold");
      doc.setFontSize(11);
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b);
      doc.text(contactName, logoX + maxLogoHeight, contactY, {
        align: "right",
      });
      contactY += 6;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(60, 60, 60);
      doc.text(`Contactos: ${contactPhone}`, logoX + maxLogoHeight, contactY, {
        align: "right",
      });
      contactY += 6;

      const headerBottom =
        Math.max(headerLeftY, contactY, headerTitleY + maxLogoHeight) + 4;
      doc.setDrawColor(primaryColor.r, primaryColor.g, primaryColor.b);
      doc.setLineWidth(0.6);
      doc.line(margin, headerBottom, pageWidth - margin, headerBottom);
      cursorY = headerBottom + 6;

      const _infoLeftX = margin;
      const _infoRightX = pageWidth / 2 + 6;
      const _infoLabelColor = primaryColor;
      cursorY = headerBottom + 6;
      const rightInfoYStart = cursorY;
      let _rightCursorY = rightInfoYStart;

      const columnGap = 8;
      const leftColumnX = margin;
      const rightColumnX = pageWidth / 2 + columnGap / 2;

      const customerDetails: Array<[string, string]> = [
        ["Cliente", customerName],
        ["Teléfono", customerPhone || "—"],
        ["Correo", quotation.customer?.email || "—"],
        ["Dirección", quotation.customer?.address || "—"],
        ["Detalle de Cotización", (() => {
          const currentLanguage = (() => {
            try {
              const prefs = JSON.parse(localStorage.getItem('sas_prefs') || '{}');
              return prefs?.language || 'es';
            } catch {
              return 'es';
            }
          })();
          return getTranslatableText(quotation.notes, (quotation as any).notesTranslations, currentLanguage) || "—";
        })()],
      ];

      const quotationDetails: Array<[string, string]> = [
        ["Código", quotation.quotationNumber],
        ["Emitida", formatDateTime(quotation.createdAt)],
        ["Válido hasta", formatDateTime(quotation.expiresAt)],
      ];
      // Si el plan tiene solo una sucursal, no mostrar la sucursal pero sí la dirección de la empresa
      if (showBranchInfo) {
        quotationDetails.push(["Sucursal", quotation.branch?.name || "—"]);
      } else if (companyAddress) {
        // Si no se muestra la sucursal, mostrar la dirección de la empresa en su lugar
        quotationDetails.push(["Dirección", companyAddress]);
      }

      const drawDetailsColumn = (
        x: number,
        title: string,
        rows: Array<[string, string]>
      ) => {
        let y = cursorY;
        doc.setFont("helvetica", "bold");
        doc.setFontSize(11);
        doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b);
        doc.text(title.toUpperCase(), x, y);
        y += 6;
        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        doc.setTextColor(45, 45, 45);

        rows.forEach(([label, value]: [string, string]) => {
          doc.text(`${label}:`, x, y);
          const isDetail = label === "Detalle de Cotización";
          const valueX = isDetail ? x + 2 : x + 32;
          const width = pageWidth / 2 - columnGap - (isDetail ? 8 : 38);
          let startY = isDetail ? y + 5 : y;
          const lines = doc.splitTextToSize(value || "—", width) as string[];
          lines.forEach((line: string, idx: number) => {
            doc.text(line, valueX, startY + idx * 5);
          });
          y = Math.max(y + 6, startY + Math.max(lines.length * 5, 6));
        });

        return y;
      };

      const leftEnd = drawDetailsColumn(
        leftColumnX,
        "Datos del cliente",
        customerDetails
      );
      const rightEnd = drawDetailsColumn(
        rightColumnX,
        "Datos de la cotización",
        quotationDetails
      );
      cursorY = Math.max(leftEnd, rightEnd) + 6;

      const tableTop = cursorY + 4;
      const tableWidth = pageWidth - margin * 2;
      const colProduct = margin + 2;
      const colPrice = margin + tableWidth * 0.55;
      const colQty = margin + tableWidth * 0.74;
      const colSubtotal = margin + tableWidth - 2;

      doc.setFillColor(primaryColor.r, primaryColor.g, primaryColor.b);
      doc.setTextColor(255, 255, 255);
      doc.setFont("helvetica", "bold");
      doc.rect(margin, tableTop, tableWidth, 9, "F");
      doc.text("Nombre", colProduct, tableTop + 6);
      doc.text(`Precio ${currencyCode}`, colPrice, tableTop + 6);
      doc.text("Cantidad (U)", colQty, tableTop + 6);
      doc.text("Subtotal", colSubtotal, tableTop + 6, { align: "right" });

      let rowY = tableTop + 11;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(45, 45, 45);

      if (items.length === 0) {
        doc.text(
          "No hay productos registrados en esta cotización.",
          margin + 4,
          rowY + 4
        );
        rowY += 14;
      } else {
        items.forEach((item, index) => {
          const displayName =
            item.product?.name || item.productName || "Producto sin nombre";
          const descriptionLines = doc.splitTextToSize(
            displayName,
            tableWidth * 0.52
          ) as string[];
          const rowHeight = Math.max(descriptionLines.length * 5, 7) + 4;

          if (rowY + rowHeight > pageHeight - 40) {
            doc.addPage();
            rowY = margin;
            doc.setFont("helvetica", "bold");
            doc.setFontSize(10);
            doc.setFillColor(primaryColor.r, primaryColor.g, primaryColor.b);
            doc.setTextColor(255, 255, 255);
            doc.rect(margin, rowY, tableWidth, 9, "F");
            doc.text("Nombre", colProduct, rowY + 6);
            doc.text(`Precio ${currencyCode}`, colPrice, rowY + 6);
            doc.text("Cantidad (U)", colQty, rowY + 6);
            doc.text("Subtotal", colSubtotal, rowY + 6, { align: "right" });
            rowY += 11;
            doc.setFont("helvetica", "normal");
            doc.setFontSize(10);
            doc.setTextColor(45, 45, 45);
          }

          if (index % 2 === 0) {
            doc.setFillColor(248, 249, 252);
            doc.rect(margin, rowY - 3, tableWidth, rowHeight, "F");
          }

          descriptionLines.forEach((line: string, idx: number) => {
            doc.text(line, colProduct, rowY + idx * 5);
          });
          doc.text(formatCurrency(item.unitPrice), colPrice, rowY);
          doc.text(String(item.quantity), colQty, rowY);
          doc.text(formatCurrency(item.subtotal), colSubtotal, rowY, {
            align: "right",
          });

          rowY += rowHeight;
        });
      }

      doc.setDrawColor(230, 230, 230);
      const dividerY = tableTop - 4;
      doc.line(margin, dividerY, pageWidth - margin, dividerY);
      cursorY = rowY + 12;

      const summaryRows: Array<[string, string]> = [
        ["SUB TOTAL", formatCurrency(subtotal)],
        ["DESCUENTO", formatCurrency(discount)],
        ["TOTAL", formatCurrency(total)],
      ];

      doc.setFont("helvetica", "bold");
      doc.setFontSize(11);
      doc.setTextColor(primaryColor.r, primaryColor.g, primaryColor.b);
      doc.text("Resumen de Totales", pageWidth - margin, cursorY, {
        align: "right",
      });
      cursorY += 6;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(45, 45, 45);

      summaryRows.forEach(([label, value]) => {
        doc.text(label, pageWidth - margin - 70, cursorY);
        doc.text(value, pageWidth - margin, cursorY, { align: "right" });
        cursorY += 6;
      });

      const fileBaseName = quotation.id
        ? `cotizacion-${quotation.id}`
        : `cotizacion-${quotation.quotationNumber}`;
      doc.save(`${fileBaseName}.pdf`);

      const dataUri = doc.output("datauristring");
      const base64 = dataUri.split(",")[1];

      if (base64) {
        try {
          const response = await fetch(
            `/api/${customerSlug}/cotizaciones/export`,
            {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                fileName: fileBaseName,
                pdfBase64: base64,
              }),
            }
          );

          if (response.ok) {
            const payload = await response.json();
            const relativeUrl = payload?.url as string | undefined;
            if (relativeUrl) {
              const absoluteUrl = relativeUrl.startsWith("http")
                ? relativeUrl
                : `${
                    typeof window !== "undefined" ? window.location.origin : ""
                  }${relativeUrl}`;
              setShareUrl(absoluteUrl);
              toast.success(t('quotations.form.pdf.ready'));
            } else {
              toast.success(t('quotations.form.pdf.generated'));
            }
          } else {
            const errorData = await response.json().catch(() => ({}));
            toast.error(
              errorData?.error ||
                t('quotations.form.pdf.downloadError')
            );
          }
        } catch (uploadError) {
          console.error("Error subiendo PDF de cotización:", uploadError);
          toast.error(t('quotations.form.pdf.downloadError'));
        }
      }
    } catch (error) {
      console.error("Error al exportar la cotización:", error);
      toast.error(t('quotations.form.pdf.generateError'));
    } finally {
      setIsExporting(false);
    }
  }, [
    quotation,
    shareUrl,
    handleOpenShareUrl,
    companyLogo,
    customerSlug,
    currencyCode,
    customerName,
    customerPhone,
    items,
    subtotal,
    discount,
    total,
    formatCurrency,
    fetchImageAsDataUrl,
    companyName,
    companyAddress,
    companyPhone,
    companyWhatsappNumber,
    companyWebsite,
    companyNIT,
    ownerName,
    showBranchInfo,
    dateFormat,
    themeColor,
  ]);

  useEffect(() => {
    if (!open || !quotation || shareUrl || typeof window === "undefined")
      return;
    const candidates = [
      quotation.id
        ? `/uploads/quotations/${customerSlug}/cotizacion-${quotation.id}.pdf`
        : null,
      quotation.quotationNumber
        ? `/uploads/quotations/${customerSlug}/cotizacion-${quotation.quotationNumber}.pdf`
        : null,
    ].filter(Boolean) as string[];

    const checkExisting = async () => {
      for (const relativeUrl of candidates) {
        try {
          const res = await fetch(relativeUrl, { method: "HEAD" });
          if (res.ok) {
            const absolute = new URL(
              relativeUrl,
              window.location.origin
            ).toString();
            setShareUrl(absolute);
            break;
          }
        } catch {
          // ignore
        }
      }
    };

    checkExisting();
  }, [open, quotation, customerSlug, shareUrl]);

  const sanitizedCompanyWhatsapp = useMemo(
    () => companyWhatsappNumber.replace(/[^0-9]/g, ""),
    [companyWhatsappNumber]
  );

  const customerWhatsapp = useMemo(() => {
    return customerPhone.replace(/[^0-9]/g, "");
  }, [customerPhone]);

  const customerWhatsappLink = useMemo(() => {
    if (!shareUrl || !customerWhatsapp) return null;
    // Formatear el mensaje con la URL en una línea separada para que WhatsApp la reconozca como enlace
    // WhatsApp reconoce URLs automáticamente cuando están en su propia línea o con espacios
    let message = `Hola ${customerName || ""}, te comparto la cotización ${
      quotation?.quotationNumber ?? ""
    }.\n\n${shareUrl}`;
    if (sanitizedCompanyWhatsapp) {
      message += `\n\nPuedes responder a este número: +${sanitizedCompanyWhatsapp}`;
    }
    // Codificar el mensaje completo
    const encodedMessage = encodeURIComponent(message);
    return `https://wa.me/${customerWhatsapp}?text=${encodedMessage}`;
  }, [
    shareUrl,
    customerWhatsapp,
    sanitizedCompanyWhatsapp,
    quotation?.quotationNumber,
    customerName,
  ]);

  const handleSendWhatsapp = useCallback(() => {
    if (!customerWhatsappLink) {
      if (!customerWhatsapp) {
        toast.error(t('quotations.form.whatsapp.noPhone'));
      } else {
        toast.error(t('quotations.form.whatsapp.noWhatsappConfig'));
      }
      return;
    }
    if (typeof window !== "undefined") {
      window.open(customerWhatsappLink, "_blank", "noopener,noreferrer");
    }
  }, [customerWhatsapp, customerWhatsappLink]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[700px] max-h-[90vh] flex flex-col overflow-hidden p-0">
        <div className="px-6 py-4 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/90 dark:bg-[#111111]/90 backdrop-blur">
          <DialogHeader className="p-0">
            <DialogTitle>Detalles de la cotización</DialogTitle>
            <DialogDescription>
              Visualiza toda la información relacionada a la cotización
              seleccionada.
            </DialogDescription>
          </DialogHeader>
        </div>

        {quotation ? (
          <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6">
            <div className="flex flex-row items-center justify-between gap-4">
              <div className="space-y-1 flex-1 min-w-0">
                <p className="text-sm text-gray-500 dark:text-gray-400 uppercase">
                  Número
                </p>
                <p className="text-xl font-semibold text-gray-900 dark:text-white truncate">
                  {quotation.quotationNumber}
                </p>
              </div>
              <Badge
                className={`${statusToken.className} rounded-full px-4 py-1.5 text-xs font-semibold flex-shrink-0`}
              >
                {statusToken.label}
              </Badge>
            </div>

            <div className="space-y-4">
              <div
                className={cn(
                  "grid gap-2 md:gap-4",
                  showBranchInfo && quotation.branch
                    ? "grid-cols-2"
                    : "grid-cols-1"
                )}
              >
                <div className="space-y-2 rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-gray-50/70 dark:bg-[#151515] p-2 md:p-3">
                  <p className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                    Cliente
                  </p>
                  <p className="font-semibold text-gray-900 dark:text-white">
                    {customerName}
                  </p>
                  {(quotation.customer?.email || quotation.customer?.ruc) && (
                    <div className="flex flex-col text-xs text-gray-500 dark:text-gray-400">
                      {quotation.customer?.email && (
                        <span>{quotation.customer.email}</span>
                      )}
                      {quotation.customer?.ruc && (
                        <span>CI: {quotation.customer.ruc}</span>
                      )}
                    </div>
                  )}
                  <div className="flex flex-col gap-1 text-xs text-gray-500 dark:text-gray-400">
                    {customerPhone && <span>Tel: {customerPhone}</span>}
                    {quotation.customer?.address && (
                      <span>Dir: {quotation.customer.address}</span>
                    )}
                  </div>
                </div>
                {showBranchInfo && quotation.branch && (
                  <div className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#151515] p-2 md:p-3 text-sm text-gray-700 dark:text-gray-300">
                    <p className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                      Sucursal
                    </p>
                    <p className="font-semibold text-gray-900 dark:text-white">
                      {quotation.branch.name ?? t('common.noBranch')}
                    </p>
                    {quotation.branch.address ? (
                      <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                        {quotation.branch.address}
                      </p>
                    ) : (
                      <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                        Sin dirección registrada
                      </p>
                    )}
                  </div>
                )}
              </div>
              <div className="grid gap-3 p-4 rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#151515] text-sm text-gray-700 dark:text-gray-300">
                <div className="flex items-center justify-between">
                  <span>Creada:</span>
                  <span className="font-medium text-gray-900 dark:text-white">
                    {formatDateTime(quotation.createdAt)}
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span>Vencimiento:</span>
                  <span className="font-medium text-gray-900 dark:text-white">
                    {formatDateTime(quotation.expiresAt)}
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span>Actualizada:</span>
                  <span className="font-medium text-gray-900 dark:text-white">
                    {formatDateTime(quotation.updatedAt)}
                  </span>
                </div>
              </div>
            </div>

            {/* Vista de cards para móvil */}
            <div className="md:hidden space-y-3">
              {items.length === 0 ? (
                <div className="text-center py-6 text-gray-500 dark:text-gray-400">
                  No hay productos registrados en esta cotización.
                </div>
              ) : (
                items.map((item) => {
                  const displayName =
                    item.product?.name ||
                    item.productName ||
                    "Producto sin nombre";
                  return (
                    <div
                      key={item.id || item.productId || displayName}
                      className="rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#0d0d0d] p-4 space-y-3"
                    >
                      <div className="space-y-1">
                        <p className="font-semibold text-gray-900 dark:text-white">
                          {displayName}
                        </p>
                      </div>
                      <div className="pt-2 border-t border-gray-200 dark:border-[#2a2a2a]">
                        <div className="grid grid-cols-3 gap-2">
                          <div>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mb-1">
                              Cantidad
                            </p>
                            <p className="font-medium text-gray-900 dark:text-white text-sm">
                              {item.quantity}
                            </p>
                          </div>
                          <div>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mb-1">
                              Precio Unit.
                            </p>
                            <p className="font-medium text-gray-900 dark:text-white text-sm">
                              {formatCurrencyWithoutSymbol(
                                Number(item.unitPrice)
                              )}
                            </p>
                          </div>
                          <div>
                            <p className="text-xs text-gray-500 dark:text-gray-400 mb-1">
                              Subtotal
                            </p>
                            <p className="font-semibold text-gray-900 dark:text-white text-sm">
                              {formatCurrencyWithoutSymbol(
                                Number(item.subtotal)
                              )}
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>

            {/* Vista de tabla para desktop */}
            <div className="hidden md:block overflow-x-auto rounded-2xl border border-gray-200 dark:border-[#2a2a2a]">
              <Table>
                <TableHeader>
                  <TableRow className="bg-gray-50 dark:bg-[#1f1f1f]">
                    <TableHead className="text-gray-700 dark:text-gray-300">
                      Producto
                    </TableHead>
                    <TableHead className="text-gray-700 dark:text-gray-300 w-[90px]">
                      Cant.
                    </TableHead>
                    <TableHead className="text-gray-700 dark:text-gray-300 w-[120px]">
                      Precio
                    </TableHead>
                    <TableHead className="text-gray-700 dark:text-gray-300 w-[120px] text-right">
                      Subtotal
                    </TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {items.length === 0 ? (
                    <TableRow>
                      <TableCell
                        colSpan={4}
                        className="text-center py-6 text-gray-500 dark:text-gray-400"
                      >
                        No hay productos registrados en esta cotización.
                      </TableCell>
                    </TableRow>
                  ) : (
                    items.map((item) => {
                      const displayName =
                        item.product?.name ||
                        item.productName ||
                        "Producto sin nombre";
                      return (
                        <TableRow
                          key={item.id || item.productId || displayName}
                        >
                          <TableCell>
                            <span className="font-medium text-gray-900 dark:text-white">
                              {displayName}
                            </span>
                          </TableCell>
                          <TableCell>{item.quantity}</TableCell>
                          <TableCell>
                            {formatCurrencyWithoutSymbol(
                              Number(item.unitPrice)
                            )}
                          </TableCell>
                          <TableCell className="text-right font-semibold text-gray-900 dark:text-white">
                            {formatCurrencyWithoutSymbol(Number(item.subtotal))}
                          </TableCell>
                        </TableRow>
                      );
                    })
                  )}
                </TableBody>
              </Table>
            </div>

            <div className="grid gap-3 sm:grid-cols-3">
              {/* Subtotal y Descuento: combinados en móvil, separados en desktop */}
              <div className="sm:hidden rounded-2xl bg-gray-100 dark:bg-[#252525] px-4 py-3">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400 mb-1">
                      Subtotal
                    </p>
                    <p className="text-base font-semibold text-gray-900 dark:text-white">
                      {formatCurrencyWithoutSymbol(subtotal)}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400 mb-1">
                      Descuento
                    </p>
                    <p className="text-base font-semibold text-gray-900 dark:text-white">
                      {formatCurrencyWithoutSymbol(discount)}
                    </p>
                  </div>
                </div>
              </div>
              <div className="hidden sm:block space-y-1 rounded-2xl bg-gray-100 dark:bg-[#252525] px-4 py-3">
                <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                  Subtotal
                </p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  {formatCurrencyWithoutSymbol(subtotal)}
                </p>
              </div>
              <div className="hidden sm:block space-y-1 rounded-2xl bg-gray-100 dark:bg-[#252525] px-4 py-3">
                <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                  Descuento
                </p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  {formatCurrencyWithoutSymbol(discount)}
                </p>
              </div>
              <div className="space-y-1 rounded-2xl bg-black text-white dark:bg-white dark:text-black px-4 py-3">
                <p className="text-xs uppercase text-white/70 dark:text-gray-600">
                  Total
                </p>
                <p className="text-lg font-semibold">{formatCurrency(total)}</p>
              </div>
            </div>

            {(() => {
              const currentLanguage = (() => {
                try {
                  const prefs = JSON.parse(localStorage.getItem('sas_prefs') || '{}');
                  return prefs?.language || 'es';
                } catch {
                  return 'es';
                }
              })();
              const notes = getTranslatableText(quotation.notes, (quotation as any).notesTranslations, currentLanguage);
              return notes && (
                <div className="space-y-2">
                  <p className="text-xs uppercase text-gray-500 dark:text-gray-400">
                    Notas
                  </p>
                  <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap bg-gray-50 dark:bg-[#151515] rounded-2xl border border-gray-200 dark:border-[#2a2a2a] px-4 py-3">
                    {notes}
                  </p>
                </div>
              );
            })()}

            {shareUrl && (
              <div className="space-y-3 rounded-2xl border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#151515] p-4">
                <p className="text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400">
                  Enlace para compartir
                </p>
                <div className="space-y-3">
                  <div className="relative">
                    <Input
                      value={shareUrl}
                      readOnly
                      className="rounded-full text-xs sm:text-sm pr-20"
                      title={shareUrl}
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="absolute right-1 top-1/2 -translate-y-1/2 h-7 px-3 rounded-full text-xs"
                      onClick={() => {
                        navigator.clipboard.writeText(shareUrl);
                        toast.success(t('quotations.form.linkCopied'));
                      }}
                    >
                      {t('quotations.form.copyLink')}
                    </Button>
                  </div>
                  <div className="flex flex-col sm:flex-row gap-2">
                    <Button
                      type="button"
                      variant="new"
                      className="rounded-full w-full sm:w-auto sm:flex-1"
                      onClick={handleSendWhatsapp}
                      disabled={!customerWhatsappLink}
                    >
                      <MessageCircle className="mr-2 h-4 w-4" /> Enviar WhatsApp
                    </Button>
                    <Button
                      type="button"
                      variant="outline"
                      className="rounded-full w-full sm:w-auto sm:flex-1"
                      onClick={handleOpenShareUrl}
                    >
                      Abrir PDF
                    </Button>
                  </div>
                </div>
                {!customerWhatsappLink && (
                  <p className="text-xs text-amber-600 dark:text-amber-400">
                    Agrega un número de teléfono al cliente para habilitar el
                    envío por WhatsApp.
                  </p>
                )}
                {customerWhatsappLink && !sanitizedCompanyWhatsapp && (
                  <p className="text-xs text-amber-600 dark:text-amber-400">
                    Tip: define el número de la empresa en Configuración para
                    incluirlo en el mensaje.
                  </p>
                )}
              </div>
            )}
          </div>
        ) : (
          <p className="py-6 text-center text-sm text-gray-500 dark:text-gray-400">
            Selecciona una cotización para ver sus detalles.
          </p>
        )}

        <DialogFooter className="border-t border-gray-200 dark:border-[#2a2a2a] bg-white/90 dark:bg-[#111111]/90 backdrop-blur px-6 py-4 flex flex-col sm:flex-row items-stretch sm:items-center justify-start sm:justify-center gap-3 sm:space-x-3 sm:space-y-0 space-y-2">
          <Button
            variant="new"
            className="rounded-full w-full sm:w-auto"
            onClick={handleExportPdf}
            disabled={!quotation || isExporting}
          >
            {shareUrl
              ? "Ver PDF"
              : isExporting
              ? "Generando..."
              : "Exportar PDF"}
          </Button>
          <Button
            variant="outline"
            className="rounded-full w-full sm:w-auto"
            onClick={() => onOpenChange(false)}
          >
            Cerrar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client"

import { SalesCustomer, SalesProduct } from "@prisma/client"
import { Check, ChevronDown, Package2, Plus, Trash2, X } from "lucide-react"
import { useTranslations } from "next-intl"
import { useEffect, useMemo, useRef, useState, useCallback } from "react"
import { toast } from "sonner"

import { SalesQuotationWithRelations } from "./types"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { useIsMobile } from "@/hooks/use-mobile"
import { cn } from "@/lib/utils"
import { formatCurrencyWithPreferences, formatDateWithPreferences, invalidateConfigCache } from "@/lib/utils/preferences"

const capitalizeWords = (value: string) =>
  value
    .toLowerCase()
    .replace(/\b\p{L}/gu, (char) => char.toUpperCase())

interface BranchOption {
  id: string
  name: string | null
}

interface QuotationFormDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  quotation?: SalesQuotationWithRelations | null
  organizationId: string
  customerSlug: string
  onSave: (data: any) => void
  isBusy?: boolean
  branches?: BranchOption[]
  isAdmin?: boolean
  currentUserBranchId?: string | null
  maxBranches?: number | null
}

interface QuotationItemRow {
  id: string
  productId: string
  productName: string
  productInput: string
  quantity: number | string
  unitPrice: number | string
  subtotal: number
}

const createEmptyItem = (): QuotationItemRow => ({
  id: `${Date.now()}-${Math.random()}`,
  productId: "none",
  productName: "",
  productInput: "",
  quantity: 1,
  unitPrice: 0,
  subtotal: 0,
})

const formatDateForInput = (value: string | Date): string => {
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return ""
  const tzOffset = date.getTimezoneOffset() * 60000
  const localISO = new Date(date.getTime() - tzOffset).toISOString()
  return localISO.split("T")[0]
}

const getTodayInputValue = () => formatDateForInput(new Date())

const toEndOfDayISO = (dateString: string): string => {
  const [year, month, day] = dateString.split("-").map(Number)
  const date = new Date(year, (month ?? 1) - 1, day ?? 1, 23, 59, 59, 999)
  return date.toISOString()
}

export function QuotationFormDialog({
  open,
  onOpenChange,
  quotation,
  organizationId: _organizationId,
  customerSlug,
  onSave,
  isBusy = false,
  branches = [],
  isAdmin = false,
  currentUserBranchId = null,
  maxBranches,
}: QuotationFormDialogProps) {
  const t = useTranslations()
  const isMobile = useIsMobile()
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null)
  const [customerInputValue, setCustomerInputValue] = useState("")
  const [customerPhoneInput, setCustomerPhoneInput] = useState("")
  const [isCustomerDropdownOpen, setIsCustomerDropdownOpen] = useState(false)
  const [highlightedCustomerIndex, setHighlightedCustomerIndex] = useState(0)
  const [isManualCustomerUsed, setIsManualCustomerUsed] = useState(false)
  const customerContainerRef = useRef<HTMLDivElement>(null)
  const customerInputRef = useRef<HTMLInputElement>(null)
  const PLACEHOLDER_BRANCH_VALUE = "__placeholder__"
  const [selectedBranchId, setSelectedBranchId] = useState<string>(PLACEHOLDER_BRANCH_VALUE)

  const [customers, setCustomers] = useState<(SalesCustomer & { lastName?: string | null })[]>([])
  const [products, setProducts] = useState<SalesProduct[]>([])
  const [items, setItems] = useState<QuotationItemRow[]>([])
  const [openProductDropdownId, setOpenProductDropdownId] = useState<string | null>(null)
  const [highlightedProductIndex, setHighlightedProductIndex] = useState<Record<string, number>>({})
  const productInputRefs = useRef<Map<string, HTMLInputElement>>(new Map())
  const productContainerRefs = useRef<Map<string, HTMLDivElement>>(new Map())
  const quantityInputRefs = useRef<Map<string, HTMLInputElement>>(new Map())
  const [discount, setDiscount] = useState(0)
  const [expiresAt, setExpiresAt] = useState("")
  const [notes, setNotes] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [isLoadingData, setIsLoadingData] = useState(false)
  const [formattedTotal, setFormattedTotal] = useState("")
  const [countryCode, setCountryCode] = useState<string>("+591") // Código de país por defecto
  const [currency, setCurrency] = useState<string>("BOB") // Moneda por defecto
  const todayInputValue = useMemo(() => getTodayInputValue(), [])
  const branchOptions = useMemo<BranchOption[]>(() => {
    return (branches ?? []).map((branch) => ({
      id: branch.id,
      name: branch.name ?? t('common.noBranch'),
    }))
  }, [branches])

  // Ocultar select de sucursal si el plan solo permite una y solo hay una disponible
  const shouldHideBranchSelect = maxBranches === 1 && branchOptions.length === 1
  const normalizedSelectedBranchId =
    selectedBranchId === PLACEHOLDER_BRANCH_VALUE ? "" : selectedBranchId
  const renderCustomerInput = (wrapperClassName: string) => (
    <div className={cn("w-full", wrapperClassName)}>
      <Label htmlFor="customer" className="text-sm font-semibold text-gray-700 dark:text-gray-200 uppercase tracking-wide">
        {t('quotations.form.customer')} <span className="text-red-500">*</span>
      </Label>
      <div className="relative mt-2">
        <input
          ref={customerInputRef}
          type="text"
          value={customerInputValue}
          onChange={(e) => {
            const formatted = e.target.value.length === 0 ? "" : capitalizeWords(e.target.value)
            setCustomerInputValue(formatted)
            setIsCustomerDropdownOpen(true)
            setHighlightedCustomerIndex(0)
            setSelectedCustomerId(null)
            setIsManualCustomerUsed(false) // Reset cuando se está escribiendo
          }}
          onFocus={() => setIsCustomerDropdownOpen(true)}
          onKeyDown={handleCustomerKeyDown}
          onBlur={() => {
            // No cerrar inmediatamente para permitir clics en el dropdown
            setTimeout(() => setIsCustomerDropdownOpen(false), 200)
          }}
          placeholder={t('quotations.form.customerPlaceholder')}
          disabled={isFormLocked}
          className={`w-full px-5 py-3 ${isManualCustomerUsed ? 'pr-28' : 'pr-20'} border border-gray-200 dark:border-[#2a2a2a] rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_oklch,var(--primary)_50%,white)] bg-white dark:bg-[#161616] text-gray-900 dark:text-white shadow-sm`}
        />
        <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-2">
          {isManualCustomerUsed && (
              <div className="p-1.5 flex items-center justify-center" title={t('quotations.form.customerNotRegistered')}>
              <Check size={16} className="text-green-600 dark:text-green-400" />
            </div>
          )}
          {customerInputValue && (
            <button
              onClick={clearCustomer}
              className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
              type="button"
              disabled={isFormLocked}
            >
              <X size={16} className="text-gray-500" />
            </button>
          )}

          <button
            onClick={() => setIsCustomerDropdownOpen(!isCustomerDropdownOpen)}
            className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
            type="button"
            disabled={isFormLocked}
          >
            <ChevronDown
              size={16}
              className={`text-gray-500 transition-transform ${isCustomerDropdownOpen ? 'rotate-180' : ''}`}
            />
          </button>
        </div>

        {isCustomerDropdownOpen && (
          <div className="absolute left-0 right-0 mt-2 z-20 bg-white dark:bg-[#161616] border border-gray-200 dark:border-[#2a2a2a] rounded-2xl shadow-xl overflow-hidden">
            <div className="max-h-64 overflow-y-auto">
              {filteredCustomers.length > 0 ? (
                filteredCustomers.map((customer, index) => (
                  <button
                    key={customer.id}
                    type="button"
                    onClick={() => selectCustomer(customer)}
                    onMouseEnter={() => setHighlightedCustomerIndex(index)}
                    className={`w-full text-left px-5 py-3 transition-colors ${index === highlightedCustomerIndex
                      ? 'bg-[color-mix(in_oklch,var(--primary)_18%,white)] text-gray-900 dark:bg-white/10 dark:text-white'
                      : 'text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-white/10'
                      }`}
                  >
                    <div className="font-semibold">{capitalizeWords(`${customer.name ?? ""} ${customer.lastName ?? ""}`.trim())}</div>
                    {customer.email && (
                      <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">{customer.email}</div>
                    )}
                  </button>
                ))
              ) : (
                <div className="px-5 py-6 text-center">
                  {customerInputValue.trim() ? (
                    <div className="space-y-2">
                      <p className="text-sm font-medium text-gray-900 dark:text-white">
                        {t('quotations.form.useCustomer')}: <span className="font-semibold">"{capitalizeWords(customerInputValue.trim())}"</span>
                      </p>
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        {t('quotations.form.pressEnterOrClick')}
                      </p>
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        className="mt-2 rounded-full"
                        onClick={() => handleManualCustomer(customerInputValue.trim())}
                      >
                        {t('quotations.form.useThisCustomer')}
                      </Button>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      <p className="text-sm text-gray-500 dark:text-gray-400">{t('quotations.form.noCustomersFound')}</p>
                      <p className="text-xs text-gray-400 dark:text-gray-500">
                        {t('quotations.form.customerNameHint')}
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )

  const renderPhoneInput = (wrapperClassName: string) => {
    // Función para obtener solo el número sin el código de país para mostrar en el input
    const getPhoneNumberWithoutCode = (value: string) => {
      if (!value) return ""
      if (value.startsWith(countryCode)) {
        return value.substring(countryCode.length).trim()
      }
      if (value.startsWith('+')) {
        // Si tiene otro código de país, mantenerlo completo
        return value
      }
      return value
    }

    const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const inputValue = e.target.value
      // Permitir solo números, espacios, guiones y el símbolo +
      const cleaned = inputValue.replace(/[^\d\s\-+]/g, '')
      setCustomerPhoneInput(cleaned)
    }

    const handlePhoneBlur = () => {
      // Al perder el foco, asegurar que tenga el código de país si tiene valor
      if (customerPhoneInput.trim() && !customerPhoneInput.startsWith('+')) {
        const cleaned = customerPhoneInput.replace(/\D/g, '')
        if (cleaned) {
          setCustomerPhoneInput(`${countryCode}${cleaned}`)
        }
      }
    }

    return (
      <div className={cn("w-full", wrapperClassName)}>
        <Label htmlFor="customerPhone" className="text-sm font-semibold text-gray-700 dark:text-gray-200 uppercase tracking-wide">{t('quotations.form.phone')}</Label>
        <div className="mt-2 relative">
          <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500 dark:text-gray-400 text-sm font-medium z-10 pointer-events-none">
            {countryCode}
          </div>
          <Input
            id="customerPhone"
            type="tel"
            value={getPhoneNumberWithoutCode(customerPhoneInput)}
            onChange={handlePhoneChange}
            onBlur={handlePhoneBlur}
            placeholder={t('quotations.form.phonePlaceholder')}
            disabled={isFormLocked}
            className="rounded-full pl-20"
          />
        </div>
      </div>
    )
  }

  // Filtrar clientes basados en el input
  const filteredCustomers = useMemo(() => {
    if (!customerInputValue.trim()) return customers
    const search = customerInputValue.trim().toLowerCase()
    return customers.filter(customer => {
      const combined = `${customer.name ?? ""} ${customer.lastName ?? ""}`.trim().toLowerCase()
      return combined.includes(search)
    })
  }, [customers, customerInputValue])

  // Filtrar productos basados en el input de cada item
  const getFilteredProducts = useCallback((itemId: string) => {
    const item = items.find(i => i.id === itemId)
    if (!item) return []

    const search = item.productInput.trim().toLowerCase()
    if (!search) return products.filter(p => !items.some(i => i.id !== itemId && i.productId === p.id))

    return products.filter(product => {
      const isAlreadySelected = items.some(
        (otherItem) => otherItem.id !== itemId && otherItem.productId === product.id
      )
      if (isAlreadySelected) return false
      return product.name?.toLowerCase().includes(search)
    })
  }, [products, items])

  // Cerrar dropdown al hacer click fuera
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (customerContainerRef.current && !customerContainerRef.current.contains(event.target as Node)) {
        setIsCustomerDropdownOpen(false)
      }
      // Cerrar dropdowns de productos
      productContainerRefs.current.forEach((container, itemId) => {
        if (container && !container.contains(event.target as Node)) {
          setOpenProductDropdownId(prev => prev === itemId ? null : prev)
        }
      })
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const loadCustomers = useCallback(async () => {
    try {
      setIsLoadingData(true)
      const response = await fetch(`/api/${customerSlug}/clientes?page=1&pageSize=1000`, {
        cache: "no-store",
      })
      if (response.ok) {
        const data = await response.json()
        const normalized = (data.customers || []).map((customer: any) => ({
          ...customer,
          lastName: customer.lastName ?? customer.apellido ?? null,
        }))
        setCustomers(normalized)
      }
    } catch (error) {
      console.error('Error al cargar clientes:', error)
    } finally {
      setIsLoadingData(false)
    }
  }, [customerSlug])

  const loadProducts = useCallback(async (branchIdOverride?: string | null) => {
    try {
      setIsLoadingData(true)
      const effectiveBranchId = isAdmin
        ? branchIdOverride && branchIdOverride !== PLACEHOLDER_BRANCH_VALUE
          ? branchIdOverride
          : null
        : currentUserBranchId ?? null

      const branchQuery = effectiveBranchId ? `&branchId=${effectiveBranchId}` : ""

      const response = await fetch(`/api/${customerSlug}/productos?page=1&pageSize=1000${branchQuery}`, {
        cache: "no-store",
      })
      if (response.ok) {
        const data = await response.json()
        setProducts(data.products || [])
      }
    } catch (error) {
      console.error('Error al cargar productos:', error)
    } finally {
      setIsLoadingData(false)
    }
  }, [customerSlug, isAdmin, currentUserBranchId])

  const loadCountryCode = useCallback(async () => {
    try {
      const response = await fetch(`/api/${customerSlug}/config/preferencias`, {
        credentials: 'include'
      })
      if (response.ok) {
        const data = await response.json()
        if (data.configuration?.whatsappCountryCode) {
          setCountryCode(data.configuration.whatsappCountryCode)
        }
        // También cargar la moneda
        if (data.configuration?.currency) {
          setCurrency(data.configuration.currency)
          // Invalidar caché para que otras funciones usen la moneda actualizada
          invalidateConfigCache(customerSlug)
        }
      }
    } catch (error) {
      console.error('Error al cargar configuración:', error)
    }
  }, [customerSlug])

  // Cargar clientes y productos
  useEffect(() => {
    if (open) {
      loadCustomers()
      const initialBranchId = isAdmin
        ? selectedBranchId
        : currentUserBranchId
      loadProducts(initialBranchId)
      loadCountryCode()
    }
  }, [open, customerSlug, isAdmin, selectedBranchId, currentUserBranchId, loadCustomers, loadProducts, loadCountryCode])

  useEffect(() => {
    if (!open || !isAdmin) return
    loadProducts(selectedBranchId)
  }, [open, isAdmin, selectedBranchId, loadProducts])

  // Cargar datos de la cotización si existe
  useEffect(() => {
    if (quotation && open) {
      const initialName = quotation.customer?.name || quotation.customerName || ""
      setSelectedCustomerId(quotation.customerId ?? null)
      const combinedName = `${quotation.customer?.name ?? ""} ${(quotation.customer as any)?.lastName ?? ""}`.trim()
      setCustomerInputValue(capitalizeWords(combinedName || initialName))
      const phoneValue = (quotation.customer?.phone as string | undefined) ?? (quotation as any)?.customerPhone ?? ""
      setCustomerPhoneInput(phoneValue ?? "")
      const branchIdFromQuotation =
        (quotation as any)?.branchId ??
        quotation.branchId ??
        quotation.branch?.id ??
        null
      setSelectedBranchId(branchIdFromQuotation ?? currentUserBranchId ?? PLACEHOLDER_BRANCH_VALUE)
      setDiscount(Number(quotation.discount) || 0)
      if (quotation.expiresAt) {
        const formatted = formatDateForInput(quotation.expiresAt)
        setExpiresAt(formatted < todayInputValue ? todayInputValue : formatted)
      } else {
        setExpiresAt("")
      }
      setNotes(quotation.notes || "")
      if (quotation.items) {
        const mapped = quotation.items.map((item: any) => {
          const baseName = item.product?.name || item.productName || ""
          const formattedName = baseName ? capitalizeWords(baseName) : ""
          return {
            id: item.id || `${item.productId ?? 'manual'}-${Math.random()}`,
            productId: item.productId ?? "none",
            productName: formattedName,
            productInput: formattedName,
            quantity: Number(item.quantity || 1),
            unitPrice: Number(item.unitPrice || 0),
            subtotal: Number(item.subtotal || 0),
          }
        })
        setItems(mapped.length > 0 ? mapped : [createEmptyItem()])
      }
    } else if (!quotation && open) {
      setSelectedCustomerId(null)
      setCustomerInputValue("")
      setCustomerPhoneInput("")
      setIsManualCustomerUsed(false) // Reset al abrir nuevo formulario
      // Si el plan solo permite una sucursal y solo hay una disponible, seleccionarla automáticamente
      const autoSelectBranchId = shouldHideBranchSelect && branchOptions.length === 1
        ? branchOptions[0].id
        : currentUserBranchId ?? PLACEHOLDER_BRANCH_VALUE
      setSelectedBranchId(autoSelectBranchId)
      setDiscount(0)
      setExpiresAt("")
      setNotes("")
      setItems([createEmptyItem()])
    }
  }, [branchOptions, currentUserBranchId, isAdmin, open, quotation, todayInputValue, shouldHideBranchSelect])

  const handleCustomerKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isCustomerDropdownOpen && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
      setIsCustomerDropdownOpen(true)
      return
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightedCustomerIndex(prev =>
          prev < filteredCustomers.length - 1 ? prev + 1 : prev
        )
        break
      case 'ArrowUp':
        e.preventDefault()
        setHighlightedCustomerIndex(prev => prev > 0 ? prev - 1 : prev)
        break
      case 'Enter':
        e.preventDefault()
        const trimmed = customerInputValue.trim()
        if (isCustomerDropdownOpen && filteredCustomers[highlightedCustomerIndex]) {
          selectCustomer(filteredCustomers[highlightedCustomerIndex])
        } else if (trimmed.length > 0) {
          handleManualCustomer(trimmed)
        } else {
          setIsCustomerDropdownOpen(false)
        }
        break
      case 'Escape':
        setIsCustomerDropdownOpen(false)
        break
    }
  }

  const selectCustomer = (customer: SalesCustomer & { lastName?: string | null }) => {
    setSelectedCustomerId(customer.id)
    const fullName = `${customer.name ?? ""} ${customer.lastName ?? ""}`.trim()
    setCustomerInputValue(capitalizeWords(fullName))
    setIsCustomerDropdownOpen(false)
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput(customer.phone ?? "")
    setIsManualCustomerUsed(false) // Reset cuando se selecciona un cliente registrado
  }

  const clearCustomer = () => {
    setSelectedCustomerId(null)
    setCustomerInputValue("")
    if (!isMobile) {
      customerInputRef.current?.focus()
    }
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput("")
    setIsManualCustomerUsed(false) // Reset al limpiar
  }

  const handleManualCustomer = (value: string) => {
    const trimmed = value.trim()
    if (trimmed.length === 0) return
    setSelectedCustomerId(null)
    const formatted = capitalizeWords(trimmed)
    setCustomerInputValue(formatted)
    setIsCustomerDropdownOpen(false)
    setHighlightedCustomerIndex(0)
    setCustomerPhoneInput("")
    setIsManualCustomerUsed(true) // Marcar como usado cuando se confirma el cliente manual
  }

  const addItem = () => {
    setItems((prev) => [...prev, createEmptyItem()])
  }

  const removeItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id))
  }

  const normalizeNumber = (value: string | number, fallback = 0) => {
    if (typeof value === "number" && !Number.isNaN(value)) return value
    const parsed = parseFloat(value as string)
    return Number.isNaN(parsed) ? fallback : parsed
  }

  const updateItem = (id: string, field: keyof QuotationItemRow, rawValue: any) => {
    setItems((prev) => {
      return prev.map((item) => {
        if (item.id !== id) return item

        const updated: QuotationItemRow = { ...item }

        if (field === "productId") {
          if (rawValue === "none") {
            updated.productId = "none"
            return updated
          }
          const product = products.find((p) => p.id === rawValue)
          updated.productId = rawValue
          if (product) {
            const unitPrice = Number(product.price || 0)
            const formattedName = capitalizeWords(product.name || "")
            updated.productName = formattedName
            updated.productInput = formattedName
            updated.unitPrice = unitPrice
            const qty = typeof updated.quantity === 'string' ? (updated.quantity === '' ? 1 : Number(updated.quantity) || 1) : updated.quantity
            updated.subtotal = unitPrice * qty
          }
        } else if (field === "quantity") {
          // Permitir valores vacíos temporalmente
          if (rawValue === "" || rawValue === null || rawValue === undefined) {
            updated.quantity = ""
          } else {
            const numValue = typeof rawValue === 'string' ? parseFloat(rawValue) : rawValue
            if (!isNaN(numValue) && numValue >= 0) {
              updated.quantity = numValue
            } else {
              updated.quantity = ""
            }
          }
          // Calcular subtotal solo si ambos valores son números válidos
          const qty = typeof updated.quantity === 'string' ? (updated.quantity === '' ? 0 : Number(updated.quantity) || 0) : updated.quantity
          const price = typeof updated.unitPrice === 'string' ? (updated.unitPrice === '' ? 0 : Number(updated.unitPrice) || 0) : updated.unitPrice
          updated.subtotal = qty * price
        } else if (field === "unitPrice") {
          // Permitir valores vacíos temporalmente
          if (rawValue === "" || rawValue === null || rawValue === undefined) {
            updated.unitPrice = ""
          } else {
            const numValue = typeof rawValue === 'string' ? parseFloat(rawValue) : rawValue
            if (!isNaN(numValue) && numValue >= 0) {
              updated.unitPrice = numValue
            } else {
              updated.unitPrice = ""
            }
          }
          // Calcular subtotal solo si ambos valores son números válidos
          const qty = typeof updated.quantity === 'string' ? (updated.quantity === '' ? 0 : Number(updated.quantity) || 0) : updated.quantity
          const price = typeof updated.unitPrice === 'string' ? (updated.unitPrice === '' ? 0 : Number(updated.unitPrice) || 0) : updated.unitPrice
          updated.subtotal = qty * price
        }

        return updated
      })
    })
  }

  const normalizeItemField = (id: string, field: "quantity" | "unitPrice") => {
    setItems((prev) => {
      return prev.map((item) => {
        if (item.id !== id) return item

        const updated: QuotationItemRow = { ...item }

        if (field === "quantity") {
          const qty = typeof item.quantity === 'string'
            ? (item.quantity === '' ? 1 : Math.max(1, Math.floor(Number(item.quantity) || 1)))
            : Math.max(1, Math.floor(item.quantity))
          updated.quantity = qty
          const price = typeof item.unitPrice === 'string' ? (Number(item.unitPrice) || 0) : item.unitPrice
          updated.subtotal = qty * price
        } else if (field === "unitPrice") {
          const price = typeof item.unitPrice === 'string'
            ? (item.unitPrice === '' ? 0 : Math.max(0, Number(item.unitPrice) || 0))
            : Math.max(0, item.unitPrice)
          updated.unitPrice = price
          const qty = typeof item.quantity === 'string' ? (Number(item.quantity) || 1) : item.quantity
          updated.subtotal = qty * price
        }

        return updated
      })
    })
  }


  const focusQuantityInput = (itemId: string) => {
    requestAnimationFrame(() => {
      const quantityInput = quantityInputRefs.current.get(itemId)
      if (quantityInput) {
        quantityInput.focus()
        quantityInput.select()
      }
    })
  }

  const handleProductInputChange = (id: string, value: string) => {
    const formatted = value.length === 0 ? "" : capitalizeWords(value)
    setItems((prev) =>
      prev.map((item) =>
        item.id === id
          ? {
            ...item,
            productId: "none",
            productInput: formatted,
            productName: formatted,
          }
          : item,
      ),
    )
    setOpenProductDropdownId(id)
    setHighlightedProductIndex(prev => ({ ...prev, [id]: 0 }))
  }

  const handleProductKeyDown = (itemId: string, e: React.KeyboardEvent<HTMLInputElement>) => {
    const filtered = getFilteredProducts(itemId)
    const currentIndex = highlightedProductIndex[itemId] ?? 0

    if (!openProductDropdownId && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
      setOpenProductDropdownId(itemId)
      return
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightedProductIndex(prev => ({
          ...prev,
          [itemId]: currentIndex < filtered.length - 1 ? currentIndex + 1 : 0
        }))
        break
      case 'ArrowUp':
        e.preventDefault()
        setHighlightedProductIndex(prev => ({
          ...prev,
          [itemId]: currentIndex > 0 ? currentIndex - 1 : filtered.length - 1
        }))
        break
      case 'Enter':
        e.preventDefault()
        if (filtered[currentIndex]) {
          handleProductSelect(itemId, filtered[currentIndex])
        } else {
          const current = items.find((item) => item.id === itemId)
          const trimmed = current?.productInput.trim() ?? ""
          if (trimmed.length > 0) {
            handleProductManualSelection(itemId, trimmed)
          }
        }
        break
      case 'Escape':
        setOpenProductDropdownId(null)
        break
    }
  }


  const handleProductSelect = (itemId: string, product: SalesProduct) => {
    const formattedName = capitalizeWords(product.name || "")
    setItems((prev) =>
      prev.map((item) =>
        item.id === itemId
          ? {
            ...item,
            productId: product.id,
            productName: formattedName,
            productInput: formattedName,
            unitPrice: Number(product.price || 0),
            subtotal: Number(product.price || 0) * (typeof item.quantity === 'string' ? (Number(item.quantity) || 1) : item.quantity),
          }
          : item,
      ),
    )
    setOpenProductDropdownId(null)
    focusQuantityInput(itemId)
  }

  const handleProductManualSelection = (itemId: string, value: string) => {
    const trimmed = value.trim()
    if (trimmed.length === 0) {
      setOpenProductDropdownId(null)
      return
    }
    const formatted = capitalizeWords(trimmed)
    setItems((prev) =>
      prev.map((item) =>
        item.id === itemId
          ? {
            ...item,
            productId: "none",
            productName: formatted,
            productInput: formatted,
          }
          : item,
      ),
    )
    setOpenProductDropdownId(null)
    focusQuantityInput(itemId)
  }

  const totals = useMemo(() => {
    const subtotal = items.reduce((sum, item) => sum + Number(item.subtotal || 0), 0)
    const total = Math.max(0, subtotal - Number(discount || 0))
    return { subtotal, total }
  }, [items, discount])

  // Actualizar el total formateado cuando cambia el total o la moneda
  useEffect(() => {
    if (open && typeof window !== 'undefined') {
      // Usar la moneda cargada desde la API
      setFormattedTotal(formatCurrencyWithPreferences(totals.total, customerSlug, currency))
    }
  }, [totals.total, customerSlug, open, currency])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    const trimmedCustomerName = customerInputValue.trim()

    // Validación 1: Cliente (ID o nombre manual)
    if (!selectedCustomerId && trimmedCustomerName.length === 0) {
      toast.error(t('quotations.form.customerRequired'))
      return
    }

    // Validación 2: Fecha de expiración (obligatoria)
    if (!expiresAt || expiresAt.trim().length === 0) {
      toast.error(t('quotations.form.expirationDateRequired'))
      return
    }

    // Si el select está oculto, usar automáticamente la única sucursal disponible
    let branchIdForSubmit: string | null = null
    if (shouldHideBranchSelect && branchOptions.length === 1) {
      branchIdForSubmit = branchOptions[0].id
    } else if (isAdmin) {
      branchIdForSubmit = normalizedSelectedBranchId || null
    } else {
      branchIdForSubmit = currentUserBranchId ?? (normalizedSelectedBranchId || null)
    }

    // Validación 3: Productos (al menos 1 con cantidad >= 1 y precio > 1)
    const validItems = items.filter((item) => {
      const hasProduct = (item.productId !== "none") || item.productName.trim().length > 0
      if (!hasProduct) return false
      
      const qty = Number(item.quantity) || 0
      const price = Number(item.unitPrice) || 0
      
      return qty >= 1 && price > 1
    })

    if (validItems.length === 0) {
      toast.error(t('quotations.form.itemsRequired'))
      return
    }

    const preparedItems = validItems
      .map(({ productId, productName, quantity, unitPrice, subtotal }) => ({
        productId: productId !== "none" ? productId : null,
        productName: productName.trim().length > 0 ? capitalizeWords(productName.trim()) : undefined,
        quantity,
        unitPrice,
        subtotal,
      }))

    setIsLoading(true)
    try {
      const expiresAtIso = expiresAt ? toEndOfDayISO(expiresAt) : undefined
      // Asegurar que el teléfono tenga el código de país
      let normalizedCustomerPhone = customerPhoneInput.trim() || undefined
      if (normalizedCustomerPhone && !normalizedCustomerPhone.startsWith('+')) {
        const cleaned = normalizedCustomerPhone.replace(/\D/g, '')
        if (cleaned) {
          normalizedCustomerPhone = `${countryCode}${cleaned}`
        }
      }

      const payload = {
        customerId: selectedCustomerId,
        customerName: selectedCustomerId ? undefined : trimmedCustomerName,
        customerPhone: normalizedCustomerPhone,
        branchId: branchIdForSubmit,
        subtotal: totals.subtotal,
        discount,
        total: totals.total,
        expiresAt: expiresAtIso,
        notes,
        items: preparedItems
      }

      await onSave(payload)
    } finally {
      setIsLoading(false)
    }
  }

  // Validar items: al menos uno con cantidad >= 1 y precio > 1
  const hasValidItems = items.some((item) => {
    const hasProduct = (item.productId !== "none") || item.productName.trim().length > 0
    if (!hasProduct) return false
    
    const qty = Number(item.quantity) || 0
    const price = Number(item.unitPrice) || 0
    
    return qty >= 1 && price > 1
  })
  
  // Si el select está oculto, no validar branchId (ya se establece automáticamente)
  const isBranchInvalid =
    !shouldHideBranchSelect &&
    isAdmin &&
    (!normalizedSelectedBranchId || normalizedSelectedBranchId.trim().length === 0)
  
  // Validar que haya cliente (ID o nombre)
  const hasValidCustomer = selectedCustomerId || customerInputValue.trim().length > 0
  
  // Validar fecha de expiración
  const hasValidExpirationDate = expiresAt && expiresAt.trim().length > 0
  
  const isSubmitDisabled =
    !hasValidCustomer ||
    !hasValidItems ||
    !hasValidExpirationDate ||
    isBranchInvalid ||
    isLoading ||
    isLoadingData ||
    isBusy
  const isFormLocked = isLoading || isLoadingData || isBusy

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="sm:max-w-[900px] lg:max-w-2xl max-h-[92vh] flex flex-col overflow-hidden p-0 rounded-lg"
        onOpenAutoFocus={(e) => {
          e.preventDefault()
        }}
      >
        <div className="px-6 sm:px-8 py-5 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky top-0 z-10">
          <DialogHeader className="px-0 py-0 space-y-2">
            <DialogTitle className="text-2xl font-semibold text-gray-900 dark:text-white">
              {quotation ? t('quotations.edit') : t('quotations.new')}
            </DialogTitle>
            <DialogDescription className="text-gray-500 dark:text-gray-400">
              {quotation
                ? t('quotations.editDescription')
                : t('quotations.newDescription')}
            </DialogDescription>
          </DialogHeader>
        </div>
        <form onSubmit={handleSubmit} className="flex flex-col flex-1 min-h-0">
          <div className="flex-1 overflow-y-auto px-6 sm:px-8 py-6 space-y-8 bg-gray-50/60 dark:bg-[#0c0c0c]">
            <div className="space-y-6">
              {/* Cliente con ComboBox */}
              <div className="space-y-5" ref={customerContainerRef}>
                {isAdmin ? (
                  <>
                    {renderCustomerInput("")}
                    <div className="flex flex-col md:flex-row md:items-end md:gap-4 gap-4">
                      {!shouldHideBranchSelect && (
                        <div className="md:flex-1">
                          <Label htmlFor="quotation-branch" className="text-sm font-semibold text-gray-700 dark:text-gray-200 uppercase tracking-wide">
                            {t('form.branch')}
                          </Label>
                          <Select
                            value={selectedBranchId}
                            onValueChange={(value) => {
                              setSelectedBranchId(value)
                            }}
                            disabled={isFormLocked}
                          >
                            <SelectTrigger id="quotation-branch" className="mt-2 w-full rounded-full">
                              <SelectValue placeholder={t('quotations.form.selectBranch')} />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value={PLACEHOLDER_BRANCH_VALUE}>{t('quotations.form.selectBranch')}</SelectItem>
                              {branchOptions.map((branch) => (
                                <SelectItem key={branch.id} value={branch.id}>
                                  {branch.name ?? t('common.noBranch')}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                      )}
                      {renderPhoneInput("md:flex-1")}
                    </div>
                  </>
                ) : (
                  <div className="flex flex-col md:flex-row md:items-end md:gap-4 gap-4">
                    {renderCustomerInput("md:flex-1")}
                    {renderPhoneInput("md:w-[320px]")}
                  </div>
                )}
              </div>
              {/* Items */}
              <div className="space-y-4">
                <Label className="text-sm font-semibold text-gray-700 dark:text-gray-200 uppercase tracking-wide">
                  {t('quotations.form.items')} <span className="text-red-500">*</span>
                </Label>

                {items.length === 0 ? (
                  <div className="flex flex-col items-center justify-center gap-3 py-12 text-gray-500 dark:text-gray-400 border-2 border-dashed border-gray-300 dark:border-[#2a2a2a] rounded-full">
                    <Package2 className="h-10 w-10" />
                    <p className="text-sm">{t('quotations.form.noProducts')}</p>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className="rounded-full"
                      onClick={addItem}
                      disabled={isFormLocked}
                    >
                      <Plus className="h-4 w-4 mr-1" /> {t('quotations.form.addProduct')}
                    </Button>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {items.map((item) => {
                      const quantityInputId = `quotation-quantity-${item.id}`
                      const priceInputId = `quotation-price-${item.id}`

                      return (
                        <div
                          key={item.id}
                          className="space-y-3 border border-gray-200 dark:border-[#2f2f2f] rounded-2xl bg-white dark:bg-[#181818] px-4 py-4 shadow-sm lg:grid lg:gap-4 lg:grid-cols-[2fr_0.9fr_0.4fr_auto] lg:space-y-0 items-start"
                        >
                          {/* Desktop: Producto y Cantidad en una fila (3/4 y 1/4) */}
                          <div className="hidden lg:grid lg:grid-cols-[3fr_1fr] lg:gap-3 lg:space-y-0">
                            <div className="space-y-1">
                              <Label className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">{t('quotations.form.product')}</Label>
                              <div
                                ref={(el) => {
                                  if (el) productContainerRefs.current.set(item.id, el)
                                  else productContainerRefs.current.delete(item.id)
                                }}
                                className="relative"
                              >
                                <input
                                  ref={(el) => {
                                    if (el) productInputRefs.current.set(item.id, el)
                                    else productInputRefs.current.delete(item.id)
                                  }}
                                  type="text"
                                  value={item.productInput}
                                  onChange={(e) => handleProductInputChange(item.id, e.target.value)}
                                  onFocus={() => setOpenProductDropdownId(item.id)}
                                  onKeyDown={(e) => handleProductKeyDown(item.id, e)}
                                  onBlur={() => {
                                    setTimeout(() => setOpenProductDropdownId(null), 200)
                                  }}
                                  placeholder={t('quotations.form.customerPlaceholder').replace('cliente', 'producto')}
                                  disabled={isLoading || isBusy}
                                  className="w-full px-4 py-3 pr-20 border border-gray-200 dark:border-[#2a2a2a] rounded-xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_oklch,var(--primary)_50%,white)] bg-white dark:bg-[#1f1f1f] text-gray-900 dark:text-white shadow-sm h-[44px]"
                                />
                                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-2">
                                  {item.productInput && (
                                    <button
                                      onClick={() => {
                                        setItems((prev) =>
                                          prev.map((i) =>
                                            i.id === item.id
                                              ? {
                                                ...i,
                                                productId: "none",
                                                productInput: "",
                                                productName: "",
                                                unitPrice: 0,
                                                subtotal: 0,
                                              }
                                              : i,
                                          ),
                                        )
                                        setOpenProductDropdownId(null)
                                      }}
                                      className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
                                      type="button"
                                      disabled={isLoading || isBusy}
                                    >
                                      <X size={16} className="text-gray-500" />
                                    </button>
                                  )}

                                  <button
                                    onClick={() => setOpenProductDropdownId(openProductDropdownId === item.id ? null : item.id)}
                                    className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
                                    type="button"
                                    disabled={isLoading || isBusy}
                                  >
                                    <ChevronDown
                                      size={16}
                                      className={`text-gray-500 transition-transform ${openProductDropdownId === item.id ? 'rotate-180' : ''}`}
                                    />
                                  </button>
                                </div>

                                {openProductDropdownId === item.id && (
                                  <div className="absolute left-0 right-0 mt-2 z-20 bg-white dark:bg-[#161616] border border-gray-200 dark:border-[#2a2a2a] rounded-2xl shadow-xl overflow-hidden">
                                    <div className="max-h-64 overflow-y-auto">
                                      {getFilteredProducts(item.id).length > 0 ? (
                                        getFilteredProducts(item.id).map((product, index) => (
                                          <button
                                            key={product.id}
                                            type="button"
                                            onClick={() => handleProductSelect(item.id, product)}
                                            onMouseEnter={() => setHighlightedProductIndex(prev => ({ ...prev, [item.id]: index }))}
                                            className={`w-full text-left px-5 py-3 transition-colors ${(highlightedProductIndex[item.id] ?? 0) === index
                                              ? 'bg-[color-mix(in_oklch,var(--primary)_18%,white)] text-gray-900 dark:bg-white/10 dark:text-white'
                                              : 'text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-white/10'
                                              }`}
                                          >
                                            <div className="font-semibold">{product.name}</div>
                                            <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                                              ${Number(product.price).toFixed(2)}
                                            </div>
                                          </button>
                                        ))
                                      ) : (
                                        <div className="px-5 py-6 text-center">
                                          {item.productInput.trim() ? (
                                            <div className="space-y-2">
                                              <p className="text-sm font-medium text-gray-900 dark:text-white">
                                                {t('quotations.form.useProduct')}: <span className="font-semibold">"{capitalizeWords(item.productInput.trim())}"</span>
                                              </p>
                                              <p className="text-xs text-gray-500 dark:text-gray-400">
                                                {t('quotations.form.pressEnterOrClickProduct')}
                                              </p>
                                              <Button
                                                type="button"
                                                variant="outline"
                                                size="sm"
                                                className="mt-2 rounded-full"
                                                onClick={() => handleProductManualSelection(item.id, item.productInput.trim())}
                                              >
                                                {t('quotations.form.useThisProduct')}
                                              </Button>
                                            </div>
                                          ) : (
                                            <div className="space-y-2">
                                              <p className="text-sm text-gray-500 dark:text-gray-400">{t('quotations.form.noProductsFound')}</p>
                                              <p className="text-xs text-gray-400 dark:text-gray-500">
                                                {t('quotations.form.productNameHint')}
                                              </p>
                                            </div>
                                          )}
                                        </div>
                                      )}
                                    </div>
                                  </div>
                                )}
                              </div>
                            </div>

                            <div className="space-y-1">
                              <Label htmlFor={quantityInputId} className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                                {t('form.quantity')}
                              </Label>
                              <Input
                                id={quantityInputId}
                                type="number"
                                placeholder={t('quotations.form.quantityShort')}
                                value={item.quantity}
                                onChange={(e) => updateItem(item.id, "quantity", e.target.value)}
                                onBlur={() => normalizeItemField(item.id, "quantity")}
                                ref={(element) => {
                                  const map = quantityInputRefs.current
                                  if (element) {
                                    map.set(item.id, element)
                                  } else {
                                    map.delete(item.id)
                                  }
                                }}
                                className="rounded-full h-11"
                                min="1"
                                disabled={isFormLocked}
                              />
                            </div>
                          </div>

                          {/* Móvil: Producto solo */}
                          <div className="space-y-1 lg:hidden">
                            <Label className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">Producto</Label>
                            <div
                              ref={(el) => {
                                if (el) productContainerRefs.current.set(item.id, el)
                                else productContainerRefs.current.delete(item.id)
                              }}
                              className="relative"
                            >
                              <input
                                ref={(el) => {
                                  if (el) productInputRefs.current.set(item.id, el)
                                  else productInputRefs.current.delete(item.id)
                                }}
                                type="text"
                                value={item.productInput}
                                onChange={(e) => handleProductInputChange(item.id, e.target.value)}
                                onFocus={() => setOpenProductDropdownId(item.id)}
                                onKeyDown={(e) => handleProductKeyDown(item.id, e)}
                                onBlur={() => {
                                  setTimeout(() => setOpenProductDropdownId(null), 200)
                                }}
                                placeholder={t('common.placeholders.productName')}
                                disabled={isLoading || isBusy}
                                className="w-full px-4 py-3 pr-20 border border-gray-200 dark:border-[#2a2a2a] rounded-xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color-mix(in_oklch,var(--primary)_50%,white)] bg-white dark:bg-[#1f1f1f] text-gray-900 dark:text-white shadow-sm h-[44px]"
                              />
                              <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-2">
                                {item.productInput && (
                                  <button
                                    onClick={() => {
                                      setItems((prev) =>
                                        prev.map((i) =>
                                          i.id === item.id
                                            ? {
                                              ...i,
                                              productId: "none",
                                              productInput: "",
                                              productName: "",
                                              unitPrice: 0,
                                              subtotal: 0,
                                            }
                                            : i,
                                        ),
                                      )
                                      setOpenProductDropdownId(null)
                                    }}
                                    className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
                                    type="button"
                                    disabled={isLoading || isBusy}
                                  >
                                    <X size={16} className="text-gray-500" />
                                  </button>
                                )}

                                <button
                                  onClick={() => setOpenProductDropdownId(openProductDropdownId === item.id ? null : item.id)}
                                  className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
                                  type="button"
                                  disabled={isLoading || isBusy}
                                >
                                  <ChevronDown
                                    size={16}
                                    className={`text-gray-500 transition-transform ${openProductDropdownId === item.id ? 'rotate-180' : ''}`}
                                  />
                                </button>
                              </div>

                              {openProductDropdownId === item.id && (
                                <div className="absolute left-0 right-0 mt-2 z-20 bg-white dark:bg-[#161616] border border-gray-200 dark:border-[#2a2a2a] rounded-2xl shadow-xl overflow-hidden">
                                  <div className="max-h-64 overflow-y-auto">
                                    {getFilteredProducts(item.id).length > 0 ? (
                                      getFilteredProducts(item.id).map((product, index) => (
                                        <button
                                          key={product.id}
                                          type="button"
                                          onClick={() => handleProductSelect(item.id, product)}
                                          onMouseEnter={() => setHighlightedProductIndex(prev => ({ ...prev, [item.id]: index }))}
                                          className={`w-full text-left px-5 py-3 transition-colors ${(highlightedProductIndex[item.id] ?? 0) === index
                                            ? 'bg-[color-mix(in_oklch,var(--primary)_18%,white)] text-gray-900 dark:bg-white/10 dark:text-white'
                                            : 'text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-white/10'
                                            }`}
                                        >
                                          <div className="font-semibold">{product.name}</div>
                                          <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                                            ${Number(product.price).toFixed(2)}
                                          </div>
                                        </button>
                                      ))
                                    ) : (
                                      <div className="px-5 py-6 text-center">
                                        {item.productInput.trim() ? (
                                          <div className="space-y-2">
                                            <p className="text-sm font-medium text-gray-900 dark:text-white">
                                              Usar producto: <span className="font-semibold">"{capitalizeWords(item.productInput.trim())}"</span>
                                            </p>
                                            <p className="text-xs text-gray-500 dark:text-gray-400">
                                              Presiona Enter o haz clic aquí para usar este producto sin registrarlo
                                            </p>
                                            <Button
                                              type="button"
                                              variant="outline"
                                              size="sm"
                                              className="mt-2 rounded-full"
                                              onClick={() => handleProductManualSelection(item.id, item.productInput.trim())}
                                            >
                                              Usar este producto
                                            </Button>
                                          </div>
                                        ) : (
                                          <div className="space-y-2">
                                            <p className="text-sm text-gray-500 dark:text-gray-400">No se encontraron productos registrados</p>
                                            <p className="text-xs text-gray-400 dark:text-gray-500">
                                              Nombre del producto para crearlo automáticamente en la cotización
                                            </p>
                                          </div>
                                        )}
                                      </div>
                                    )}
                                  </div>
                                </div>
                              )}
                            </div>
                          </div>

                          <div className="space-y-1 hidden lg:block">
                            <Label htmlFor={priceInputId} className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                              {t('quotations.form.price')}
                            </Label>
                            <Input
                              id={priceInputId}
                              type="number"
                              placeholder={t('quotations.form.price')}
                              value={item.unitPrice}
                              onChange={(e) => updateItem(item.id, "unitPrice", e.target.value)}
                              onBlur={() => normalizeItemField(item.id, "unitPrice")}
                              className="rounded-full h-11"
                              step="0.01"
                              min="0"
                              disabled={isFormLocked}
                            />
                          </div>

                          {/* Móvil: Cantidad y Precio en grid de 2 columnas */}
                          <div className="grid grid-cols-2 gap-2 lg:hidden">
                            <div className="space-y-1">
                              <Label htmlFor={`${quantityInputId}-mobile`} className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                                {t('form.quantity')}
                              </Label>
                              <Input
                                id={`${quantityInputId}-mobile`}
                                type="number"
                                placeholder={t('quotations.form.quantityShort')}
                                value={item.quantity}
                                onChange={(e) => updateItem(item.id, "quantity", e.target.value)}
                                onBlur={() => normalizeItemField(item.id, "quantity")}
                                className="rounded-full h-11"
                                min="1"
                                disabled={isFormLocked}
                              />
                            </div>

                            <div className="space-y-1">
                              <Label htmlFor={`${priceInputId}-mobile`} className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                                {t('quotations.form.price')}
                              </Label>
                              <Input
                                id={`${priceInputId}-mobile`}
                                type="number"
                                placeholder={t('quotations.form.price')}
                                value={item.unitPrice}
                                onChange={(e) => updateItem(item.id, "unitPrice", e.target.value)}
                                onBlur={() => normalizeItemField(item.id, "unitPrice")}
                                className="rounded-full h-11"
                                step="0.01"
                                min="0"
                                disabled={isFormLocked}
                              />
                            </div>
                          </div>

                          <div className="space-y-1 hidden lg:block">
                            <Label className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                              {t('quotations.form.subtotal')}
                            </Label>
                            <div className="flex items-center justify-center rounded-xl bg-gray-100 dark:bg-[#242424] px-2 py-2 h-11">
                              <span className="font-semibold text-sm text-gray-900 dark:text-white">{item.subtotal.toFixed(2)}</span>
                            </div>
                          </div>

                          <div className="flex items-end justify-end hidden lg:flex">
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon"
                              className="rounded-full h-11 w-10 text-red-500 hover:bg-red-100 dark:hover:bg-red-900/20"
                              onClick={() => removeItem(item.id)}
                              disabled={isFormLocked || items.length === 1}
                              aria-label="Eliminar producto"
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>

                          {/* Móvil: Subtotal y botón eliminar en grid de 2 columnas */}
                          <div className="grid grid-cols-[3fr_1fr] gap-2 lg:hidden">
                            <div className="space-y-1">
                              <Label className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                                {t('quotations.form.subtotal')}
                              </Label>
                              <div className="flex items-center justify-center rounded-xl bg-gray-100 dark:bg-[#242424] px-4 py-2 h-11">
                                <span className="font-semibold text-gray-900 dark:text-white">{item.subtotal.toFixed(2)}</span>
                              </div>
                            </div>

                            <div className="flex items-end justify-end">
                              <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                className="rounded-full h-11 w-full text-red-500 hover:bg-red-100 dark:hover:bg-red-900/20"
                                onClick={() => removeItem(item.id)}
                                disabled={isFormLocked || items.length === 1}
                                aria-label="Eliminar producto"
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </div>
                          </div>
                        </div>
                      )
                    })}
                    <div className="flex justify-center pt-3">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        className="rounded-full"
                        onClick={addItem}
                        disabled={isFormLocked}
                      >
                        <Plus className="h-4 w-4 mr-1" /> Agregar Producto
                      </Button>
                    </div>
                  </div>
                )}
              </div>
              {/* Totales y extras */}
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">{t('quotations.form.subtotal')}</Label>
                    <Input
                      type="text"
                      value={totals.subtotal.toFixed(2)}
                      readOnly
                      className="rounded-full font-semibold text-right bg-[color-mix(in_oklch,var(--primary)_8%,white)] dark:bg-[color-mix(in_oklch,var(--primary)_18%,black)] text-gray-900 dark:text-white border border-transparent"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="discount" className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">{t('quotations.form.discount')}</Label>
                    <Input
                      id="discount"
                      type="number"
                      value={discount}
                      onChange={(e) => setDiscount(normalizeNumber(e.target.value, 0))}
                      onFocus={(e) => {
                        if (e.target.value === "0" || e.target.value === "0.0" || e.target.value === "0.00") {
                          setDiscount(0)
                          e.target.value = ""
                        } else {
                          e.target.select()
                        }
                      }}
                      className="rounded-full"
                      step="0.01"
                      min="0"
                      disabled={isFormLocked}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="expiresAt" className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">
                      {t('quotations.form.validUntil')} <span className="text-red-500">*</span>
                    </Label>
                    <div className="relative">
                      <Input
                        id="expiresAt"
                        type="date"
                        value={expiresAt}
                        min={todayInputValue}
                        required
                        onChange={(e) => {
                          const value = e.target.value
                          if (!value) {
                            setExpiresAt("")
                            return
                          }
                          setExpiresAt(value < todayInputValue ? todayInputValue : value)
                        }}
                        className={cn(
                          "w-full rounded-full",
                          // En móviles: ocultar el indicador y los campos de fecha nativos
                          isMobile && "[&::-webkit-calendar-picker-indicator]:opacity-0 [&::-webkit-calendar-picker-indicator]:absolute [&::-webkit-calendar-picker-indicator]:right-0 [&::-webkit-calendar-picker-indicator]:w-full [&::-webkit-calendar-picker-indicator]:h-full [&::-webkit-calendar-picker-indicator]:cursor-pointer [&::-webkit-datetime-edit]:opacity-0 [&::-webkit-datetime-edit-text]:opacity-0 [&::-webkit-datetime-edit-month-field]:opacity-0 [&::-webkit-datetime-edit-day-field]:opacity-0 [&::-webkit-datetime-edit-year-field]:opacity-0 [&::-webkit-inner-spin-button]:opacity-0 [&::-webkit-outer-spin-button]:opacity-0",
                          // En PC: mostrar todo normalmente
                          !isMobile && "[&::-webkit-calendar-picker-indicator]:opacity-100 [&::-webkit-calendar-picker-indicator]:cursor-pointer [&::-webkit-calendar-picker-indicator]:z-10"
                        )}
                        disabled={isFormLocked}
                        style={expiresAt && isMobile ? { color: 'transparent', caretColor: 'transparent' } : undefined}
                      />
                      {!expiresAt && (
                        <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none flex items-center gap-2 sm:hidden">
                          <span className="text-sm text-gray-400">dd/mm/aaa</span>
                        </div>
                      )}
                      {expiresAt && (
                        <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none flex items-center gap-2 sm:hidden">
                          <span className="text-sm text-gray-900 dark:text-white">
                            {(() => {
                              const [year, month, day] = expiresAt.split('-').map(Number)
                              const localDate = new Date(year, month - 1, day)
                              return formatDateWithPreferences(localDate, customerSlug)
                            })()}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="total" className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">{t('quotations.form.total')}</Label>
                    <Input
                      id="total"
                      type="text"
                      value={formattedTotal || totals.total.toFixed(2)}
                      readOnly
                      className="rounded-full font-semibold text-right bg-[color-mix(in_oklch,var(--primary)_12%,white)] dark:bg-[color-mix(in_oklch,var(--primary)_24%,black)] text-gray-900 dark:text-white border border-transparent"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="notes" className="text-xs font-semibold uppercase text-gray-500 dark:text-gray-400">{t('quotations.form.notes')}</Label>
                  <Textarea
                    id="notes"
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    placeholder={t('quotations.form.notes') + '...'}
                    disabled={isFormLocked}
                    rows={4}
                    className="rounded-lg"
                  />
                </div>
              </div>
            </div>
          </div>
          <DialogFooter className="flex flex-col sm:flex-row w-full justify-center sm:justify-center items-stretch sm:items-center gap-3 border-t border-gray-200 dark:border-[#2a2a2a] px-6 sm:px-8 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky bottom-0 z-10">
            <Button
              type="button"
              variant="outline"
              className="rounded-full w-full sm:w-auto"
              onClick={() => onOpenChange(false)}
              disabled={isFormLocked}
            >
              {t('action.cancel')}
            </Button>
            <Button
              type="submit"
              variant="new"
              className="rounded-full px-6 w-full sm:w-auto"
              disabled={isSubmitDisabled}
            >
              {isLoading ? t('message.saving') : quotation ? t('action.update') : t('action.add')}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { FileText } from "lucide-react"
import { useTranslations } from "next-intl"
import { FC, memo, useMemo, useState, useEffect } from "react"

import { QuotationsCards } from "./quotations-cards"
import { QuotationsFilters } from "./quotations-filters"
import { QuotationsPagination } from "./quotations-pagination"
import { QuotationsStats } from "./quotations-stats"
import { QuotationsTable } from "./quotations-table"

import { SalesQuotationWithRelations } from "@/components/sales/quotation/types"
import { Card, CardContent } from "@/components/ui/card"
import { getTranslatableText } from "@/lib/utils/translatable-text"

const QuotationsTableComponent = QuotationsTable as unknown as FC<any>

export interface QuotationsContainerProps {
  quotations: SalesQuotationWithRelations[]
  isLoading?: boolean
  organizationId: string
  customerSlug: string
  onEdit?: (quotation: SalesQuotationWithRelations) => void
  onDelete?: (quotation: SalesQuotationWithRelations) => void
  onViewDetails?: (quotation: SalesQuotationWithRelations) => void
  onConvert?: (quotation: SalesQuotationWithRelations) => void | Promise<void>
  showBranchColumn?: boolean
  branches?: { id: string; name: string | null }[]
  allowBranchFilter?: boolean
  maxBranches?: number | null
  onBranchFilterChange?: (branchId: string | null) => void
  selectedBranchFilter?: string | null
}

const QuotationsContainerComponent: FC<QuotationsContainerProps> = ({
  quotations,
  isLoading = false,
  organizationId: _organizationId,
  customerSlug,
  onEdit,
  onDelete,
  onViewDetails,
  onConvert,
  showBranchColumn = false,
  branches = [],
  allowBranchFilter = false,
  maxBranches,
  onBranchFilterChange,
  selectedBranchFilter,
}) => {
  const t = useTranslations()
  const [pageSize, setPageSize] = useState(10)
  const [currentPage, setCurrentPage] = useState(1)
  const [searchTerm, setSearchTerm] = useState("")
  const [statusFilter, setStatusFilter] = useState<string>("all")
  const [branchFilter, setBranchFilter] = useState<string | null>(selectedBranchFilter ?? null)

  useEffect(() => {
    setBranchFilter(selectedBranchFilter ?? null)
  }, [selectedBranchFilter])

  const branchOptions = useMemo(() => {
    const unique = new Map<string, { id: string; name: string | null }>()
    let includeUnassigned = false

    branches.forEach((branch) => {
      if (!branch?.id) {
        return
      }
      if (!unique.has(branch.id)) {
        unique.set(branch.id, { id: branch.id, name: branch.name ?? t('common.noBranch') })
      }
    })

    quotations.forEach((quotation) => {
      const branchId = quotation.branchId ?? quotation.branch?.id ?? undefined
      const branchName =
        quotation.branch?.name ??
        unique.get(branchId ?? "")?.name ??
        t('common.noBranch')

      if (branchId) {
        if (!unique.has(branchId)) {
          unique.set(branchId, { id: branchId, name: branchName })
        }
      } else {
        includeUnassigned = true
      }
    })

    const options = Array.from(unique.values())

    if (includeUnassigned) {
      options.push({ id: "none", name: t('common.noBranch') })
    }

    return options
  }, [branches, quotations])

  // Filtrar cotizaciones por búsqueda y estado
  const filteredQuotations = useMemo(() => {
    return quotations.filter((quotation) => {
      const matchesStatus = statusFilter === "all" || quotation.status === statusFilter
      const normalizedQuotationBranchId = quotation.branchId ?? quotation.branch?.id ?? null
      const matchesBranch =
        !allowBranchFilter ||
        branchFilter === null ||
        (branchFilter === "none"
          ? !normalizedQuotationBranchId
          : normalizedQuotationBranchId === branchFilter)

      if (searchTerm.trim() !== "") {
        const searchLower = searchTerm.toLowerCase()
        // Obtener notas traducidas para búsqueda
        const currentLanguage = (() => {
          try {
            const prefs = JSON.parse(localStorage.getItem('sas_prefs') || '{}');
            return prefs?.language || 'es';
          } catch {
            return 'es';
          }
        })();
        const notes = getTranslatableText(
          quotation.notes,
          (quotation as any).notesTranslations,
          currentLanguage
        ) || "";
        const matchesSearch =
          quotation.quotationNumber?.toLowerCase().includes(searchLower) ||
          `${quotation.customer?.name ?? ""} ${quotation.customer?.lastName ?? ""}`.trim().toLowerCase().includes(searchLower) ||
          quotation.customerName?.toLowerCase().includes(searchLower) ||
          notes.toLowerCase().includes(searchLower)

        return matchesSearch && matchesStatus && matchesBranch
      }

      return matchesStatus && matchesBranch
    })
  }, [branchFilter, quotations, searchTerm, statusFilter, allowBranchFilter])

  const handleSearchChange = (term: string) => {
    setSearchTerm(term)
    setCurrentPage(1)
  }

  const handleStatusChange = (status: string) => {
    setStatusFilter(status)
    setCurrentPage(1)
  }

  const handleBranchChange = (branchId: string | null) => {
    setBranchFilter(branchId)
    setCurrentPage(1)
    if (onBranchFilterChange) {
      onBranchFilterChange(branchId)
    }
  }

  // Calcular cotizaciones para la página actual
  const startIndex = (currentPage - 1) * pageSize
  const endIndex = startIndex + pageSize
  const currentQuotations = filteredQuotations.slice(startIndex, endIndex)

  const handlePageSizeChange = (size: number) => {
    setPageSize(size)
    setCurrentPage(1)
  }

  const handlePageChange = (page: number) => {
    setCurrentPage(page)
  }

  return (
    <div className="space-y-6">
      <QuotationsStats quotations={quotations as any} isLoading={isLoading} />

      <Card className="bg-white dark:bg-[#1a1a1a] border-gray-200 dark:border-[#2a2a2a]">
        <CardContent className="pt-6">
          <QuotationsFilters 
            onPageSizeChange={handlePageSizeChange}
            onSearchChange={handleSearchChange}
            onStatusChange={handleStatusChange}
            statusValue={statusFilter}
            branches={branchOptions}
            selectedBranchId={branchFilter}
            onBranchChange={allowBranchFilter ? handleBranchChange : undefined}
            showBranchFilter={allowBranchFilter && !(maxBranches === 1 && branchOptions.length === 1)}
            maxBranches={maxBranches}
          />
        </CardContent>
      </Card>

      {/* Mostrar cards y tabla solo si hay cotizaciones */}
      {currentQuotations.length > 0 ? (
        <>
          {/* Cards de cotizaciones (solo móvil) */}
          <QuotationsCards
            customerSlug={customerSlug}
            quotations={currentQuotations as any}
            showBranchColumn={showBranchColumn}
            onEdit={onEdit as any}
            onDelete={onDelete as any}
            onViewDetails={onViewDetails as any}
            onConvert={onConvert}
            maxBranches={maxBranches}
          />

          {/* Tabla de cotizaciones (solo desktop) */}
          <div className="hidden md:block rounded-md border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#1a1a1a] overflow-hidden">
            <QuotationsTableComponent
              quotations={currentQuotations as any}
              isLoading={isLoading}
              onEditClick={onEdit as any}
              onDeleteClick={onDelete as any}
              onViewDetails={onViewDetails as any}
              onConvertClick={onConvert}
              showBranchColumn={showBranchColumn && !(maxBranches === 1 && branches.length === 1)}
              branches={branches}
              maxBranches={maxBranches}
            />
          </div>
        </>
      ) : (
        <div className="text-center py-12 rounded-md border border-gray-200 dark:border-[#2a2a2a] bg-white dark:bg-[#1a1a1a]">
          <div className="flex flex-col items-center gap-2">
            <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-[#2a2a2a] flex items-center justify-center">
              <FileText className="h-8 w-8 text-gray-400" />
            </div>
            <p className="text-gray-500 dark:text-gray-400">No hay cotizaciones registradas</p>
          </div>
        </div>
      )}

      <div className="flex justify-center">
        <QuotationsPagination
          currentPage={currentPage}
          totalPages={Math.ceil(filteredQuotations.length / pageSize)}
          pageSize={pageSize}
          onPageChange={handlePageChange}
          onPageSizeChange={handlePageSizeChange}
        />
      </div>
    </div>
  )
}

QuotationsContainerComponent.displayName = "QuotationsContainer"

export const QuotationsContainer = memo(QuotationsContainerComponent)

"use client"

import { Search, X } from "lucide-react"
import { useTranslations } from "next-intl"
import { useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

type BranchOption = {
  id: string
  name: string | null
}

const statusOptions = [
  { value: 'all', label: 'Todos los estados', shortLabel: 'Todos' },
  { value: 'active', label: 'Activas' },
  { value: 'converted', label: 'Convertidas' },
  { value: 'expired', label: 'Vencidas' },
]

export interface QuotationsFiltersProps {
  onPageSizeChange: (size: number) => void
  onStatusChange: (status: string) => void
  onSearchChange: (term: string) => void
  statusValue?: string
  branches?: BranchOption[]
  selectedBranchId?: string | null
  onBranchChange?: (branchId: string | null) => void
  showBranchFilter?: boolean
  maxBranches?: number | null
}

export function QuotationsFilters({
  onPageSizeChange,
  onStatusChange,
  onSearchChange,
  statusValue = "all",
  branches = [],
  selectedBranchId = null,
  onBranchChange,
  showBranchFilter = false,
  maxBranches,
}: QuotationsFiltersProps) {
  const t = useTranslations()
  const [searchValue, setSearchValue] = useState("")

  const handleSearchChange = (value: string) => {
    setSearchValue(value)
    onSearchChange(value)
  }

  const handleClearSearch = () => {
    setSearchValue("")
    onSearchChange("")
  }

  const { branchOptions, hasUnassignedBranch } = useMemo(() => {
    const unique = new Map<string, BranchOption>()
    let includeUnassigned = false

    branches.forEach((branch) => {
      if (!branch) {
        return
      }

      if (branch.id === "none" || !branch.id) {
        includeUnassigned = true
        return
      }

      if (!unique.has(branch.id)) {
        unique.set(branch.id, { id: branch.id, name: branch.name ?? t('branches.details.noName') })
      }
    })

    return {
      branchOptions: Array.from(unique.values()),
      hasUnassignedBranch:
        includeUnassigned || branches.some((branch) => branch?.id === "none"),
    }
  }, [branches])

  return (
    <div className="flex flex-col sm:flex-row gap-4 items-end">
          <div className="flex-1 w-full sm:w-auto">
            <Label
              htmlFor="quotations-search"
              className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2 block"
            >
              Buscar
            </Label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4 z-10" />
              <Input
                id="quotations-search"
                placeholder={t('common.placeholders.searchQuotations')}
                className="pl-10 pr-10 w-full rounded-full"
                value={searchValue}
                onChange={(e) => handleSearchChange(e.target.value)}
              />
              {searchValue && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="absolute right-1 top-1/2 transform -translate-y-1/2 h-7 w-7 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800"
                  onClick={handleClearSearch}
                  aria-label="Limpiar búsqueda"
                >
                  <X className="h-4 w-4 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300" />
                </Button>
              )}
            </div>
          </div>

          {showBranchFilter && (branchOptions.length > 0 || hasUnassignedBranch) && (
            <div className="w-full sm:w-[200px]">
              <Label
                htmlFor="branch-filter"
                className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2 block"
              >
                Sucursal
              </Label>
              <Select
                value={selectedBranchId ?? "all"}
                onValueChange={(value) => {
                  if (onBranchChange) {
                    if (value === "all") {
                      onBranchChange(null)
                      return
                    }

                    if (value === "none") {
                      onBranchChange("none")
                      return
                    }

                    onBranchChange(value)
                  }
                }}
              >
                <SelectTrigger id="branch-filter" className="w-full rounded-full">
                  <SelectValue placeholder={t('common.placeholders.allBranches')} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">{t('common.placeholders.allBranches')}</SelectItem>
                  {branchOptions.map((branch) => (
                    <SelectItem key={branch.id} value={branch.id}>
                      {branch.name ?? t('branches.details.noName')}
                    </SelectItem>
                  ))}
                  {hasUnassignedBranch && (
                    <SelectItem value="none">{t('common.noBranch')}</SelectItem>
                  )}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Estado y Datos en fila de 2 en móvil */}
          <div className="grid grid-cols-2 gap-3 w-full sm:contents">
            <div className="w-full sm:w-[180px]">
              <Label
                htmlFor="status-filter"
                className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2 block"
              >
                Estado
              </Label>
              <Select
                onValueChange={onStatusChange}
                value={statusValue}
                defaultValue="all"
              >
                <SelectTrigger id="status-filter" className="w-full rounded-full">
                  <SelectValue placeholder={t('common.placeholders.filterByStatus')} />
                </SelectTrigger>
                <SelectContent>
                  {statusOptions.map((option) => (
                    <SelectItem key={option.value} value={option.value}>
                      <span className="sm:hidden">{option.shortLabel || option.label}</span>
                      <span className="hidden sm:inline">{option.label}</span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="w-full sm:w-[150px]">
              <Label
                htmlFor="page-size"
                className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2 block"
              >
                Datos
              </Label>
              <Select
                onValueChange={(value) => onPageSizeChange(Number(value))}
                defaultValue="10"
              >
                <SelectTrigger id="page-size" className="w-full rounded-full">
                  <SelectValue placeholder={t('common.placeholders.perPage')} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="5">5 por página</SelectItem>
                  <SelectItem value="10">10 por página</SelectItem>
                  <SelectItem value="20">20 por página</SelectItem>
                  <SelectItem value="50">50 por página</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

    </div>
  )
}

"use client"

import {
  FileText,
  Lock,
  Users,
  Calendar,
  CheckCircle,
  XCircle,
} from "lucide-react"
import { useMemo } from "react"

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Separator } from "@/components/ui/separator"
import { PermissionSasService } from "@/lib/services/sales/permission-sas-service"

type RoleSasWithRelations = {
  id: string
  nombre: string
  descripcion?: string | null
  isActive: boolean
  permissions?: any
  createdAt: Date
  organization?: { razonSocial: string | null; name: string | null; slug: string | null } | null
  sucursal?: { name: string } | null
  _count?: { usuariosSas: number }
}

interface RoleSasDetailDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  role: RoleSasWithRelations | null
}

export function RoleSasDetailDialog({
  open,
  onOpenChange,
  role,
}: RoleSasDetailDialogProps) {
  const formatDate = (date: Date | string | null) => {
    if (!date) return "N/A"
    return new Date(date).toLocaleString("es-BO", {
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    })
  }

  const permissions = Array.isArray(role?.permissions) ? role.permissions : []
  const userCount = role?._count?.usuariosSas || 0

  // Función para extraer el módulo del nombre del permiso (formato: modulo_accion)
  const getModuleFromPermission = (permissionName: string): string => {
    const parts = String(permissionName).split('_')
    return parts[0] || 'unknown'
  }

  // Agrupar permisos por módulo
  const permissionsByModule = useMemo(() => {
    if (!role) return {}
    const grouped: Record<string, string[]> = {}
    permissions.forEach((perm) => {
      const module = getModuleFromPermission(perm)
      if (!grouped[module]) {
        grouped[module] = []
      }
      grouped[module].push(String(perm))
    })
    return grouped
  }, [permissions, role])

  if (!role) return null

  // Obtener módulos disponibles
  const availableModules = PermissionSasService.getAvailableModules()

  // Ordenar módulos según el orden de availableModules y filtrar solo los que tienen permisos
  const modulesWithPermissions = availableModules
    .filter(m => permissionsByModule[m.id] && permissionsByModule[m.id].length > 0)
    .map(m => ({
      id: m.id,
      label: m.label,
      permissions: permissionsByModule[m.id],
    }))

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px] lg:max-w-2xl max-h-[90vh] flex flex-col overflow-hidden p-0 rounded-lg">
        {/* Header estático */}
        <div className="px-6 sm:px-8 py-5 border-b border-gray-200 dark:border-[#2a2a2a] bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky top-0 z-10">
          <DialogHeader className="px-0 py-0 space-y-2">
            <DialogTitle>
              {role.nombre}
            </DialogTitle>
            <DialogDescription>
              Información detallada del rol del sistema
            </DialogDescription>
          </DialogHeader>
        </div>

        <div className="flex flex-col flex-1 min-h-0">
          {/* Contenido con scroll */}
          <div className="flex-1 overflow-y-auto px-6 sm:px-8 py-6 space-y-6 bg-gray-50/60 dark:bg-[#0c0c0c]">
            {/* Información General */}
            <div className="space-y-4">
              <h3 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                <FileText className="h-4 w-4" />
                Información General
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <p className="text-xs text-gray-500 dark:text-gray-400">Nombre del Rol</p>
                  <p className="text-sm font-medium text-gray-900 dark:text-white">
                    {role.nombre}
                  </p>
                </div>
                <div className="space-y-1">
                  <p className="text-xs text-gray-500 dark:text-gray-400">Estado</p>
                  <Badge
                    variant="secondary"
                    className={
                      role.isActive
                        ? "bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 border-green-200 dark:border-green-800"
                        : "bg-gray-100 dark:bg-gray-900/30 text-gray-700 dark:text-gray-300 border-gray-200 dark:border-gray-800"
                    }
                  >
                    {role.isActive ? (
                      <>
                        <CheckCircle className="h-3 w-3 mr-1" />
                        Activo
                      </>
                    ) : (
                      <>
                        <XCircle className="h-3 w-3 mr-1" />
                        Inactivo
                      </>
                    )}
                  </Badge>
                </div>
                {role.descripcion && (
                  <div className="space-y-1 md:col-span-2">
                    <p className="text-xs text-gray-500 dark:text-gray-400">Descripción</p>
                    <p className="text-sm text-gray-900 dark:text-white">
                      {role.descripcion}
                    </p>
                  </div>
                )}
                {role.sucursal && (
                  <div className="space-y-1">
                    <p className="text-xs text-gray-500 dark:text-gray-400">Sucursal</p>
                    <p className="text-sm text-gray-900 dark:text-white">
                      {role.sucursal.name}
                    </p>
                  </div>
                )}
              </div>
            </div>

            <Separator />

            {/* Permisos */}
            <div className="space-y-4">
              <h3 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                <Lock className="h-4 w-4" />
                Permisos ({permissions.length})
              </h3>
              {permissions.length > 0 ? (
                <Accordion type="multiple" className="w-full space-y-2">
                  {modulesWithPermissions.map((module) => (
                    <AccordionItem
                      key={module.id}
                      value={module.id}
                      className="border border-gray-200 dark:border-[#2a2a2a] rounded-lg px-4 bg-white dark:bg-[#1a1a1a]"
                    >
                      <AccordionTrigger className="hover:no-underline py-3">
                        <div className="flex items-center justify-between w-full pr-2">
                          <div className="flex items-center gap-2">
                            <span className="text-sm font-semibold text-gray-900 dark:text-white">
                              {module.label}
                            </span>
                            <Badge
                              variant="secondary"
                              className="bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 text-xs"
                            >
                              {module.permissions.length}
                            </Badge>
                          </div>
                        </div>
                      </AccordionTrigger>
                      <AccordionContent className="pt-2 pb-4">
                        <div className="flex flex-wrap gap-2">
                          {module.permissions.map((permission, index) => {
                            // Extraer la acción del permiso (formato: modulo_accion)
                            const action = permission.split('_').slice(1).join('_')
                            return (
                              <Badge
                                key={index}
                                variant="outline"
                                className="text-xs border-gray-300 dark:border-gray-600"
                              >
                                {action.replace(/_/g, ' ')}
                              </Badge>
                            )
                          })}
                        </div>
                      </AccordionContent>
                    </AccordionItem>
                  ))}
                </Accordion>
              ) : (
                <p className="text-sm text-gray-500 dark:text-gray-400 italic">
                  Este rol no tiene permisos asignados
                </p>
              )}
            </div>

            <Separator />

            {/* Usuarios Asociados */}
            <div className="space-y-4">
              <h3 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                <Users className="h-4 w-4" />
                Usuarios Asociados
              </h3>
              <div className="space-y-1">
                <p className="text-xs text-gray-500 dark:text-gray-400">Total de Usuarios</p>
                <div className="flex items-center gap-2">
                  <Badge variant="secondary" className="bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300">
                    {userCount} {userCount === 1 ? "usuario" : "usuarios"}
                  </Badge>
                </div>
                {userCount === 0 && (
                  <p className="text-sm text-gray-500 dark:text-gray-400 italic mt-2">
                    No hay usuarios asociados a este rol
                  </p>
                )}
              </div>
            </div>

            <Separator />

            {/* Información del Sistema */}
            <div className="space-y-4">
              <h3 className="text-sm font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                <Calendar className="h-4 w-4" />
                Información del Sistema
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <p className="text-xs text-gray-500 dark:text-gray-400">Fecha de Creación</p>
                  <p className="text-sm text-gray-900 dark:text-white">
                    {formatDate(role.createdAt)}
                  </p>
                </div>
                <div className="space-y-1">
                  <p className="text-xs text-gray-500 dark:text-gray-400">ID del Rol</p>
                  <p className="text-sm font-mono text-gray-600 dark:text-gray-400 text-xs break-all">
                    {role.id}
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Footer estático */}
          <div className="flex justify-center border-t border-gray-200 dark:border-[#2a2a2a] px-6 sm:px-8 py-4 bg-white/95 dark:bg-[#111111]/95 backdrop-blur sticky bottom-0 z-10">
            <Button
              variant="new"
              rounded="full"
              onClick={() => onOpenChange(false)}
              className="w-full sm:w-auto"
            >
              Cerrar
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

const { execSync } = require('child_process');

try {
    console.log('Running migrations...');
    execSync('npx prisma migrate deploy', { stdio: 'inherit' });
} catch (error) {
    console.warn('\x1b[33m%s\x1b[0m', 'Migration failed or indicated existing failed state.');
    console.warn('\x1b[33m%s\x1b[0m', 'Proceeding as requested by user (ignoring migration error).');
    console.warn('If you need to fix the migration state, run: npx prisma migrate resolve --applied <migration_name>');
    // Exit with 0 to allow the process to continue
    process.exit(0);
}
